LL w[30]={1};
LL calc(LL x1,LL y1,LL x2,LL y2,int d){
	if(d==-1)return llabs(y2-y1);
	int a=(x1-1)/w[d],b=(y1-1)/w[d],c=(x2-1)/w[d],d1=(y2-1)/w[d];
	if(a!=c){
		if(b!=d1)return llabs(x2-x1)+llabs(y2-y1);
		return calc(y1,x1,y2,x2,d);
	}
	else if(a==1&&b!=d1){
		x1-=w[d],x2-=w[d];
		return llabs(y2-y1)+min(x1+x2,w[d]*2+2-x1-x2);
	}
	x1-=w[d]*a,x2-=w[d]*a;
	return calc(x1,y1,x2,y2,d-1);
}
