using namespace std;

i64 solve(i64 a, i64 b, i64 c, i64 d) {

	for(int level = 30; level > 0; level--) {

		i64 width = 1;
		for(int i = 0; i < level - 1; i++) {
			width = width * 3;
		}

		i64 x1 = a / width;
		i64 y1 = b / width;
		i64 x2 = c / width;
		i64 y2 = d / width;

		if(x1 != x2 && y1 != y2) {
			return abs(c - a) + abs(d - b);
		}

		if(x1 == x2 && y1 == y2) {
			continue;
		}

		if(x1 != x2) {
			swap(x1, y1);
			swap(x2, y2);
			swap(a, b);
			swap(c, d);
		}

		if(x1 % 3 != 1) {
			continue;
		}

		if((y1 + 1) / 3 == (y2 + 1) / 3) {
			continue;
		}

		i64 p = a % width;
		i64 q = c % width;
		return abs(b - d) + min(p + q + 2, 2 * width - p - q);
	}

	return abs(c - a) + abs(d - b);
}

