void solve(ll sz)
{
	ll x1=a/sz,y1=b/sz,x2=c/sz,y2=d/sz;
	if(x1!=x2||y1!=y2)
	{
		if(x1==x2&&x1%3==1&&abs(y1-y2)>1)
		{
			cost=min(a%sz+c%sz+2,2*sz-a%sz-c%sz)+abs(d-b);
			return;
		}
		if(y1==y2&&y1%3==1&&abs(x1-x2)>1)
		{
			cost=min(b%sz+d%sz+2,2*sz-b%sz-d%sz)+abs(a-c);
			return;
		}
	}
	if(sz>1)
	{
		solve(sz/3);
	}
}
