LL func(int dep, LL a, LL b, LL c, LL d)
{
    if(dep == -1) return abs(a - c) + abs(b - d);

    LL w = po[dep];
    LL aw = a / w, bw = b / w, cw = c / w, dw = d / w;

    if(abs(aw - cw) > abs(bw - dw))
    {
        swap(a, c);
        swap(b, d);
        swap(aw, cw);
        swap(bw, dw);
    }

