long long pow(long long x,long long y) {
  if(y == 0)return 1;
  else if(y%2 == 0)return pow(x*x,y/2);
  else return pow(x*x,y/2)*x;
}
long long AB(long long& a,long long& b,long long& c,long long& d,int& level) {
