vector<vector<bool>> fractal(size_fractal, vector<bool>(size_fractal, false));

void make_fractal(int x, int y, int level)
{
  if (level == 0)
  {
    fractal[x][y] = false;
    return;
  }

  ll pow_three = pow(3, level - 1);

  rep(i, 3) rep(j, 3)
  {
    if (i == 1 and j == 1)
    {
      rep(ii, pow_three) rep(jj, pow_three)
          fractal[x + pow_three + ii][y + pow_three + jj] = true;
      continue;
    }

    make_fractal(x + i * pow_three, y + j * pow_three, level - 1);
  }
}

ll distTest(pll ab, pll cd)
{
  ll ans = 0;

  vector<vector<bool>> is_reached(size_fractal, vector<bool>(size_fractal, false));
  queue<pll> q;
  q.push(ab);
  is_reached[ab.first][ab.second] = true;
  while (!is_reached[cd.first][cd.second])
  {
    queue<pll> nextq;
    while (!q.empty())
    {
      pll xy = q.front();
      q.pop();
      rep(k, 4)
      {
        int nx = xy.first + udlr[k].first;
        int ny = xy.second + udlr[k].second;
        if (!(0 <= nx and nx < size_fractal and 0 <= ny and ny < size_fractal))
          continue;

        if (!fractal[nx][ny] and !is_reached[nx][ny])
        {
          nextq.push({nx, ny});
          is_reached[nx][ny] = true;
        }
      }
