	}
	return false;
}
long long get_detour(long long x1,long long y1,long long x2,long long y2){
	long long ans=0LL,tmp,p3=1LL;
	for(int i=0;i<35;i++){
		if((x1/p3==x2/p3)&&between(x1/p3,y1/p3,y2/p3)){
			tmp=min(min(x1%p3,x2%p3)+1LL,p3-max(x1%p3,x2%p3));
			ans=max(ans,tmp);
		}
		p3*=3LL;
	}
	return ans;
}
