long long extra(long long x1, long long x2) {
    long long ans = 0;
    long long sz = 1;
    for (int k = 0; k <= 31; k++) {
        if (x1 / 3 == x2 / 3) {
            if (x1 % 3 == 1 && x2 % 3 == 1) {
                long long p = x1 % (3*sz) + 1 + x2 % (3*sz) + 1;
                long long cand = min(p, 2*(sz+1) - p);
                ans = max(ans, cand);
            }
        }
        x1 /= 3;
        x2 /= 3;
        sz *= 3;
    }
    return ans;
}

