vector<pair<LL, LL> > build(LL x, LL y) {
    vector<pair<LL, LL> > ret;
    for (int t=0; t<=31; t++) {
	LL k = T[t];
	LL a = x - x%k;
	LL b = a + k - 1;
	LL c = y - y%k;
	LL d = c + k - 1;
	ret.emplace_back(a, c);
	ret.emplace_back(a, d);
	ret.emplace_back(b, c);
	ret.emplace_back(b, d);
    }
    return ret;
}

