ll pw(ll x, ll y) {
    if (y < 0) return 0;
    if (y == 0) return 1;
    else if (y == 1) return x;
    else if (y % 2 == 0) {
        ll p = pw(x, y / 2);
        return p * p;
    }
    else {
        ll p = pw(x, y / 2);
        return p * p * x;
    }
}

Pll func(ll a, ll b) {
    ll l = 0, r = pw(3, 30), k = 30;
    while (r - l > 1) {
        if (l <= a && a < l + (r - l) / 3) {
            r = l + (r - l) / 3;
        }
        else if (l + 2 * (r - l) / 3 <= a && a < r) {
            l = l + 2 * (r - l) / 3;
        }
        else {
            ll tl = l, tr = r;
            l = tl + 1 * (tr - tl) / 3;
            r = tl + 2 * (tr - tl) / 3;
            //cerr << "m: " << l _ r _ k _ b << endl;
            if (b >= pw(3, k - 1)) break;
        }
        k--;
    }
    k--;
    if (k == -1) r--;
    return Pll(l, k);
}

void solve(ll a, ll b, ll c, ll d) {
    vector<Pll> v = {func(a, b), func(b, a),
        func(pw(3, 30) - 1 - a, pw(3, 30) - 1 - b),
        func(pw(3, 30) - 1 - b, pw(3, 30) - 1 - a),
        func(c, d), func(d, c),
        func(pw(3, 30) - 1 - c, pw(3, 30) - 1 - d),
        func(pw(3, 30) - 1 - d, pw(3, 30) - 1 - c)};
    for (int i = 2; i <= 7; i++) {
        if (i != 4 && i != 5)
        v[i] = Pll(pw(3, 30) - v[i].first - pw(3, v[i].second), v[i].second);
    }
    for (auto i : v) cerr << i.first _ i.second << endl;
    ll ans = abs(a - c) + abs(b - d);
    if (v[0] == v[6] && v[0].second != -1) {
        ll k = v[0].second;
        if (abs(a - c) >= 2 * pw(3, k) - 1) {
            ll l = v[0].first, r = l + pw(3, k);
            ans += min(a + c - 2 * l + 2, 2 * r - a - c);
        }
    }
    if (v[1] == v[7] && v[1].second != -1) {
        ll k = v[1].second;
        if (abs(b - d) >= 2 * pw(3, k) - 1) {
            ll l = v[1].first, r = l + pw(3, k);
            ans += min(b + d - 2 * l + 2, 2 * r - b - d);
        }
    }
    if (v[2] == v[4] && v[2].second != -1) {
        ll k = v[2].second;
        //cerr << ans << endl;
        if (abs(a - c) >= 2 * pw(3, k) - 1) {
            ll l = v[0].first, r = l + pw(3, k);
            ans += min(a + c - 2 * l + 2, 2 * r - a - c);
        }
    }
    if (v[3] == v[5] && v[3].second != -1) {
        ll k = v[3].second;
        if (abs(b - d) >= 2 * pw(3, k) - 1) {
            ll l = v[1].first, r = l + pw(3, k);
            ans += min(b + d - 2 * l + 2, 2 * r - b - d);
        }
    }

    cout << ans << endl;
}

