ll pow3[31];

void solve(){
    ll a,b,c,d;cin>>a>>b>>c>>d;
    --a;--b;--c;--d;
    ll _a=a,_b=b,_c=c,_d=d;
    ll p[31],q[31],r[31],s[31];
    for (int i=0;i<31;i++){p[i]=_a%3;_a/=3;}
    for (int i=0;i<31;i++){q[i]=_b%3;_b/=3;}
    for (int i=0;i<31;i++){r[i]=_c%3;_c/=3;}
    for (int i=0;i<31;i++){s[i]=_d%3;_d/=3;}

    ll cost=0;
    for (int i=0;i<31;i++){
        // make sure p[i],q[i] is not 1
        if (p[i]==1){
            if (a<c){
                p[i]++;cost+=pow3[i];a+=pow3[i];
            }else{
                p[i]--;cost+=pow3[i];a-=pow3[i];
            }
        }
        if (q[i]==1){
            if (a<c){
                q[i]++;cost+=pow3[i];b+=pow3[i];
            }else{
                q[i]--;cost+=pow3[i];b-=pow3[i];
            }
        }
    }
    for (int i=30;i>=0;i--){
        if (p[i]!=r[i]){
            if (p[i]<r[i]){
                ll target=r[i]*pow3[i];
                ll cur=a%pow3[i+1];
                cost+=target-cur;
                for (int j=0;j<i;j++)
                    p[j]=0;
                p[i]=r[i];
            }else{
                ll target=(r[i]+1)*pow3[i]-1;
                ll cur=a%pow3[i+1];
                cost+=cur-target;
                for (int j=0;j<i;j++)
                    p[j]=2;
                p[i]=r[i];
            }
        }
        if (q[i]!=s[i]){
            if (q[i]<s[i]){
                ll target=s[i]*pow3[i];
                ll cur=b%pow3[i+1];
                cost+=target-cur;
                for (int j=0;j<i;j++)
                    q[j]=0;
                q[i]=s[i];
            }else{
                ll target=(s[i]+1)*pow3[i]-1;
                ll cur=b%pow3[i+1];
                for (int j=0;j<i;j++)
                    q[j]=2;
                q[i]=s[i];
            }
        }
    }
    cout<<cost<<endl;
}

