using namespace std;

int get(long long a, int x) {
    int i;

    for (i = 0; i < x; i++) a /= 3;

    return a % 3;
}

long long get2(long long a, int x) {
    int i;

    for (i = 0; i < x; i++) a *= 3;

    return a;
}

long long calc(long long a, long long b, long long c, long long d) {
    int i;
    long long pa = 0, pb = 0, pc = 0, pd = 0;

    for (i = 29; i >= 0; i--) {
        pa = pa * 3 + get(a, i);
        pb = pb * 3 + get(b, i);
        pc = pc * 3 + get(c, i);
        pd = pd * 3 + get(d, i);

        if (pa == pc && pb != pd && pa % 3 == 1) {
            long long x, y;

            x = get2(pa, i) - 1;
            y = get2(pa + 1, i);

            return min(abs(a - x) + abs(c - x), abs(a - y) + abs(c - y)) + abs(b - d);
        } else if (pb == pd && pa != pc && pb % 3 == 1) {
            long long x, y;

            x = get2(pb, i) - 1;
            y = get2(pb + 1, i);

            return min(abs(b - x) + abs(d - x), abs(b - y) + abs(d - y)) + abs(a - c);
        }
    }

    return abs(a - c) + abs(b - d);
}

