				ll mn=std::min(a,c),mx=std::max(a,c);
				return res+std::min(mn-mn/t*t+1LL,(mx/t+1LL)*t-mx)*2LL;
			}
			std::swap(a,b),std::swap(c,d);
		}
		t/=3LL;
	}
	return res;
}

