int dist[3][3][3][3];
const int d[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

void BFS(int x, int y, int dist[3][3]) {
  queue<ii> Q;
  Q.push({x, y});
  dist[x][y] = 0;
  while (!Q.empty()) {
    auto cur = Q.front();
    int x, y;
    std::tie(x, y) = cur;
    Q.pop();
    for (int k = 0; k < 4; ++k) {
      int nx = x + d[k][0];
      int ny = y + d[k][1];
      if (nx == 1 && ny == 1) continue;
      if (nx >= 0 && nx < 3 && ny >= 0 && ny < 3 && dist[nx][ny] < 0) {
        dist[nx][ny] = dist[x][y] + 1;
        Q.push({nx, ny});
      }
    }
  }
}

int main() {
  memset(dist, 255, sizeof(dist));
  for (int i = 0; i < 3; ++i) {
    for (int j = 0; j < 3; ++j) {
      BFS(i, j, dist[i][j]);
    }
  }
  int cas;
  scanf("%d", &cas);
  while (cas--) {
    int64 x0, y0, x1, y1;
    scanf("%lld%lld%lld%lld", &x0, &y0, &x1, &y1);
    --x0; --y0; --x1; --y1;
    int64 step = 1;
    for (int k = 0; k < 29; ++k) step *= 3;
    int64 ret = 0;
    for (; step; step /= 3) {
      int64 ux = x0 / step, uy = y0 / step;
      int64 vx = x1 / step, vy = y1 / step;
      // trace(step, x0, y0, x1, y1, ux, uy, vx, vy, ret);
      if (ux * 3 + uy <= vx * 3 + vy) {
        ret += dist[ux][uy][vx][vy] * step;
      } else {
        ret -= dist[ux][uy][vx][vy] * step;
      }
      x0 %= step; y0 %= step;
      x1 %= step; y1 %= step;
    }
    printf("%lld\n", abs(ret));
  }
  return 0;
}

