LL s[50];



vector<LL> cal(LL x, LL y, int d) {

  LL sx = (x - 1) / s[d] + 1;

  LL tx = (x - 1) % s[d] + 1;

  LL sy = (y - 1) / s[d] + 1;

  LL ty = (y - 1) % s[d] + 1;



  if(tx > s[d - 1] && tx <= s[d - 1] * 2) {

    int p = ty <= s[d - 1] ? 0 : 1;

    return {1, sx, sy + p, tx - s[d - 1], s[d - 1] * 2 - tx + 1};

  }

  if(ty > s[d - 1] && ty <= s[d - 1] * 2) {

    int p = tx <= s[d - 1] ? 0 : 1;

    return {2, sy, sx + p, ty - s[d - 1], s[d - 1] * 2 - ty + 1};

  }

  return {0, 0, 0, 0};

}



