ll f(ll a1, ll a2, ll b1, ll b2, int level, ll size)
{
	// cerr << a1 << ' ' << a2 << ' ' << b1 <<  ' ' << b2 << ' ' << level << ' ' << size << '\n';
	if(level == 0)
		return 0;

	int sec_index_a_i = a1 / (size / 3);
	int sec_index_a_j = a2 / (size / 3);
	int sec_index_b_i = b1 / (size / 3);
	int sec_index_b_j = b2 / (size / 3);

	if(sec_index_a_i == sec_index_b_i and sec_index_a_j == sec_index_b_j)
		return f(a1 % (size / 3), a2 % (size / 3), b1 % (size / 3), b2 % (size / 3), level - 1, size / 3);

	if(sec_index_a_j == sec_index_b_j)
	{
		swap(a1, a2);
		swap(b1, b2);
	}

	while(size != 1)
	{
		int sec_index_a = a1 / (size / 3);
		int sec_index_b = b1 / (size / 3);
		if(sec_index_a != sec_index_b)
			return dist(a1, a2, b1, b2);
		if(sec_index_a == 1 and abs((a2 / (size / 3)) - (b2 / (size / 3))) > 1)
			return abs(a2 - b2) + min((a1 % (size / 3) + 1 + (b1 % (size / 3)) + 1), 2 * (size / 3) - (a1 % (size / 3) + (b1 % (size / 3))));
		a1 %= (size / 3);
		b1 %= (size / 3);
		size /= 3;
	}
	return abs(a2 - b2);
}

