inline ll solve()
{
	--a,--b,--c,--d;
	int res=abs(a-c)+abs(b-d),t=1LL;
	for(rgi i=1;i<=33;++i) t*=3LL;
	for(rgi i=33;i>=0;--i)
	{
		for(rgi j=0;j<2;++j)
		{
			if(a/t==c/t&&(a/t)%3LL==1LL&&abs(b/t-d/t)!=1&&abs(b-d)>=t)
			{
				int mn=min(a,c),mx=max(a,c);
				return res+min(mn-mn/t*t+1LL,(mx/t+1LL)*t-mx)*2LL;
			}
			swap(a,b),swap(c,d);
		}
		t/=3LL;
	}
	return res;
}

