#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;

vector<ll> deg3;

struct point {
    ll x, y;
};

struct sqp {
    point p;
    ll d3;
};

int bbs(ll v1, ll v2, int deg, ll c2) {
    //cout << v1 << " " << v2 << " " << deg << " " << c2 << "\n";
    if (deg < 0) {
        return -1;
    }
    ll pv1, pv2, pvc;
    pv1 = v1 / deg3[deg];
    pv2 = v2 / deg3[deg];
    pvc = c2 / deg3[deg];
    if (pv1 != pv2) {
        if (pvc == 1) {
            return deg;
        } else {
            int lv = pv1 + 1;
            int rv = pv2 - 1;
            if (v1 % deg3[deg] == 0) {
                --lv;
            }
            if ((v2 + 1) % deg3[deg] == 0) {
                ++rv;
            }
            if (rv >= lv) {
                return bbs(0, deg3[deg] - 1, deg - 1, c2 % deg3[deg]);
            }
            int ans1 = bbs(v1 % deg3[deg], deg3[deg] - 1, deg - 1, c2 % deg3[deg]);
            int ans2 = bbs(0, v2 % deg3[deg], deg - 1, c2 % deg3[deg]);
            return max(ans1, ans2);
        }
    }
    return bbs(v1 % deg3[deg], v2 % deg3[deg], deg - 1, c2 % deg3[deg]);
}

void normalize(point& plt, point& prd) {
    if (plt.x > prd.x) {
        swap(plt.x, prd.x);
    }
    if (plt.y > prd.y) {
        swap(plt.y, prd.y);
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    deg3.push_back(1LL);
    for (int i = 0; i < 33; ++i) {
        deg3.push_back(deg3.back() * 3LL);
    }
    int q;
    cin >> q;
    for (int qq = 0; qq < q; ++qq) {
        point plt, prd;
        cin >> plt.x >> plt.y >> prd.x >> prd.y;
        --plt.x;
        --plt.y;
        --prd.x;
        --prd.y;
        normalize(plt, prd);
        vector<int> vs;
        vector<int> coor{plt.y, plt.x, prd.y, prd.x};
        vs.push_back(bbs(plt.x, prd.x, 29, plt.y));
        vs.push_back(bbs(plt.y, prd.y, 29, plt.x));
        vs.push_back(bbs(plt.x, prd.x, 29, prd.y));
        vs.push_back(bbs(plt.y, prd.y, 29, prd.x));
        int maxad = 0;
        for (int i = 0; i < 2; ++i) {
            if (vs[i] != vs[i + 2] || vs[i] < 0) {
                continue;
            }
            if (coor[i + 2] - coor[i] >= deg3[vs[i]]) {
                continue;
            }
            if (coor[i + 2] % deg3[vs[i]] <= coor[i] % deg3[vs[i]]) {
                continue;
            }
            ll ots = min(coor[i] % deg3[vs[i]] + 1, deg3[vs[i]] - coor[i + 2] % deg3[vs[i]]);
            maxad = ots * 2;
        }
        cout << prd.y - plt.y + prd.x - plt.x + maxad * 2 << "\n";
    }
    return 0;
}

