    {
        long long a,b,c,d;
        scanf("%lld%lld%lld%lld",&a,&b,&c,&d);
        int first=(int)(upper_bound(dis,dis+31,abs(a-c))-dis);
        int second=(int)(upper_bound(dis,dis+31,abs(b-d))-dis);
        long long size=max(dis[first],dis[second]);
        update(a,size); update(b,size); update(c,size); update(d,size);
        size/=3;
        long long one=((a+size-1)/size-1)*3+(b+size-1)/size;
        long long two=((c+size-1)/size-1)*3+(d+size-1)/size;
        if(one>two)
        {
            swap(a,c);
            swap(b,d);
            swap(one,two);
        }
        long long ans;
        if(one==2&&two==8)
            ans=min(size*4-b-d+2,b+d-size*2)+c-a;
        else if(one==4&&two==6)
            ans=min(size*4-a-c+2,a+c-size*2)+d-b;
        else
            ans=abs(b-d)+abs(a-c);
        printf("%lld\n",ans);
    }
    return 0;
}

