    }
}

ll solve(ll y1, ll x1, ll y2, ll x2, ll ly, ll lx){
    if(ly == 1){
        if((y1 == y2 && x1 == x2) || (y1 != y2 && x1 != x2)){
            return abs(y1 - y2) + abs(x1 - x2);
        }else if(y1 == y2){
            if(y1 == 1){
                return abs(x1 - x2) + 2;
            }else{
                return abs(x1 - x2);
            }
        }else{
            assert(x1 == x2 && lx == 1);
            if(x1 == 1){
                return abs(y1 - y2) + 2;
            }else{
                return abs(y1 - y2);
            }
        }
    }
    if(lx == 1){
        return solve(x1, y1, x2, y2, lx, ly);
    }

    const ll h = pow3.at(ly);
    const ll w = pow3.at(lx);

    const ll yi1 = y1 / h, yi2 = y2 / h;
    const ll xi1 = x1 / w, xi2 = x2 / w;

    if(yi1 == yi2 && xi1 == xi2){
        return solve(y1 % h, x1 % w, y2 % h, x2 % w, ly - 1, lx - 1);
    }else if(yi1 != yi2 && xi1 != xi2){
        return abs(y1 - y2) + abs(x1 - x2);
    }else if(yi1 == yi2){
        if(yi1 == 1){
            ll ret = abs(x1 - x2);
            ret += min(
                y1 % pow3.at(ly) + y2 % pow3.at(ly) + 2,
                2 * pow3.at(ly) - y1 % pow3.at(ly) - y2 % pow3.at(ly)
            );
            return ret;
        }else{
            return solve(y1 % h, x1, y2 % h, x2, ly - 1, lx);
        }
    }else{
        assert(xi1 == xi2);
        return solve(x1, y1, x2, y2, lx, ly);
    }
}

