vector<int> memo3(31);
ll pow3(ll a)
{
  if (a == 0)
    return 1;
  if (memo3[a] == 0)
    return memo3[a] = pow3(a - 1) * 3;
  else
    return memo3[a];
}
ll getIth(ll x, ll i)
{
  return (x / pow3(i)) % 3;
}
ll getOverIth(ll x, ll i)
{
  return x / pow3(i);
}
ll mdist(ll a, ll b, ll c, ll d)
{
  return abs(a - c) + abs(b - d);
}
ll sameXBlackBoxDist(ll rank, ll a, ll b, ll c, ll d)
{
  return min(a % pow3(rank) + c % pow3(rank) + 2,
             pow3(rank) * 2 - a % pow3(rank) - c % pow3(rank)) +
         abs(b - d);
}
ll sameXDist(ll rank, ll a, ll b, ll c, ll d)
{
  if (rank == 0)
    return mdist(a, b, c, d);
  else
  {
    ll abit = getIth(a, rank - 1);
    ll bbit = getOverIth(b, rank - 1);
    ll cbit = getIth(c, rank - 1);
    ll dbit = getOverIth(d, rank - 1);
    if (abit != cbit)
      return mdist(a, b, c, d);
    if (abit == 1)
    {
      if (abs(bbit - dbit) <= 1)
      {
        return sameXDist(rank - 1, a, b, c, d);
      }
      else
      {
        return sameXBlackBoxDist(rank - 1, a, b, c, d);
      }
    }
    else
    {
      return sameXDist(rank - 1, a, b, c, d);
    }
  }
}
ll dist(ll rank, ll a, ll b, ll c, ll d)
{
  if (rank == 0)
    return 0;
  else
  {
    ll abit = getIth(a, rank - 1);
    ll bbit = getIth(b, rank - 1);
    ll cbit = getIth(c, rank - 1);
    ll dbit = getIth(d, rank - 1);
    if (abit == cbit && bbit == dbit)
      return dist(rank - 1, a, b, c, d);
    if (abit == cbit)
    {
      if (abit == 1)
        return sameXBlackBoxDist(rank - 1, a, b, c, d);
      return sameXDist(rank - 1, a, b, c, d);
    }
    if (bbit == dbit)
    {
      if (bbit == 1)
        return sameXBlackBoxDist(rank - 1, b, a, d, c);
      return sameXDist(rank - 1, b, a, d, c);
    }
    if (abit != cbit && bbit != dbit)
      return mdist(a, b, c, d);
    throw "Fool!";
  }
}
