  for (int i = 1; i < 33; i++) {
    if (x1 % 3 == 1 && x2 % 3 == 1 && x1 == x2) {
     // if ((y1 % 3 == 0 && y2 % 3 == 2) || (y1 % 3 == 2 && y2 % 3 == 0)) {
