vector<int> getBit(LL x, int bitn = 30) {
	vector<int> res;
	res.clear();
	while (x > (LL)(0)) {
		res.push_back((int)(x % (LL)(3)));
		x /= (LL)(3);
	}
	while (res.size() < bitn) {
		res.push_back(0);
	}
	return res;
}
