vector<Int> v;

Int func(point a, point b){
	int l = 30;
	Int xa = a.x;
	Int xb = b.x;
	while(l > 0){
		--l;
		Int qa = xa / v[l];
		Int qb = xb / v[l];
		if((qa == 0 && qb == 2) || (qa == 2 && qb == 0)){
			Int ya = a.y;
			Int yb = b.y;
			for(Int i=29; i>l; --i){
				ya = ya % v[i];
				yb = yb % v[i];
			}
			if(ya / v[l] == 1 && yb / v[l] == 1){
				return abs(a.x - b.x) + min(ya + yb, 2*v[l+1] - ya - yb);
			}
		}
		xa = xa % v[l];
		xb = xb % v[l];
	}
	l = 30;
	Int ya = a.y;
	Int yb = b.y;
	while(l > 0){
		--l;
		Int qa = ya / v[l];
		Int qb = yb / v[l];
		if((qa == 0 && qb == 2) || (qa == 2 && qb == 0)){
			xa = a.x;
			xb = b.x;
			for(Int i=29; i>l; --i){
				xa = xa % v[i];
				xb = xb % v[i];
			}
