void make_d(ll d[33], ll val)
{
    rep (pos, 32) {
        d[pos] = val % 3LL;
        val /= 3LL;
    }
}

void solve(ll x1, ll y1, ll x2, ll y2, bool flag)
{
    ll dx1[33]; make_d(dx1, x1);
    ll dx2[33]; make_d(dx2, x2);
    ll dy1[33]; make_d(dy1, y1);
    ll dy2[33]; make_d(dy2, y2);

    ll ans = abs(x1 - x2) + abs(y1 - y2);

    rrep (pos, 32) {
        if (dx1[pos] != dx2[pos]) {
            if (flag) cout << ans << endl;
            else solve(y1, x1, y2, x2, true);
            return;
        }
        if (dx1[pos] == 1LL && dy1[pos] != dy2[pos]) {
            debug_printf("pos=%lld\n", pos);
            ans = abs(y1 - y2);
            x1 %= (ll)pow(3LL, pos+1LL);
            x2 %= (ll)pow(3LL, pos+1LL);
            ll incr1 = x1 - ((ll)pow(3LL, pos) - 1LL);
            incr1 += x2 - ((ll)pow(3LL, pos) - 1LL);
            ll incr2 = ((ll)pow(3LL, pos) * 2LL) - x1;
            incr2 += ((ll)pow(3LL, pos) * 2LL) - x2;
            ans += min(incr1, incr2);
            cout << ans << endl;
            return;
        }
    }

    cout << ans << endl;
}

