int main() {
  int Q;
  cin >> Q;

  const int D = 31;
  auto base3 = [](ll n) {
    vector<int> res(D);
    for (int i = 0; i < (int)(D); ++i) {
      res[i] = n % 3;
      n /= 3;
    }
    return res;
  };

  auto restore = [&](const vector<int>& d, int k) -> ll {
    ll res = 0;
    for (int i = k; i >= 0; --i) {
      res *= 3;
      res += d[i];
    }
    return res;
  };

  vector<ll> u(D), l(D);
  u[0] = 2;
  l[0] = 0;
  for (int i = 0; i < (int)(D - 1); ++i) {
    u[i + 1] = 3 * u[i];
    l[i + 1] = 3 * l[i] + 2;
  }

  auto solve = [&]() {
    ll a, b, c, d;
    cin >> a >> b >> c >> d;
    --a, --b, --c, --d;
    vector<int> da(base3(a)), db(base3(b)), dc(base3(c)), dd(base3(d));

    for (int k = D; k > 0; --k) {
      if (da[k] == 1 && dc[k] == 1 && (db[k] ^ dd[k]) == 2) {
        ll ak = restore(da, k), ck = restore(dc, k);
        ll ans = min(abs(u[k] - ak + u[k] - ck), abs(ak - l[k] + ck - l[k])) +
                 abs(b - d);
        cout << ans << endl;
        return;
      }
      if (db[k] == 1 && dd[k] == 1 && (da[k] ^ dc[k]) == 2) {
        ll bk = restore(db, k), dk = restore(dd, k);
        ll ans = abs(a - c) +
                 min(abs(u[k] - bk + u[k] - dk), abs(bk - l[k] + dk - l[k]));
        cout << ans << endl;
        return;
      }
    }
    cout << abs(c - a) + abs(d - b) << endl;
  };

  for (int i = 0; i < (int)(Q); ++i) solve();

  return 0;
}

