int main(){
    using namespace std;
    unsigned long Q;
    cin >> Q;
    constexpr unsigned long M{205891132094649UL};
    const auto& calc = [](unsigned long a, unsigned long b, unsigned long c, unsigned long d) -> unsigned long {
        unsigned long mx{M};
        while(a > a / mx * mx + mx / 3 || a / mx * mx + mx / 3 > c)mx /= 3;
        auto ub{b}, lb{b};
        while(mx /= 3){
            if(ub / mx % 3 == 1)ub = ub / (3 * mx) * 3 * mx + 2 * mx;
            if(lb / mx % 3 == 1)lb = lb / (3 * mx) * 3 * mx + mx - 1;
        }
        return c - a + min(ub - b + max(ub, d) - min(ub, d), b + d - 2 * lb);
    };
    for(unsigned long _{0}, a, b, c, d; _ < Q; ++_){
        scanf("%lu%lu%lu%lu", &a, &b, &c, &d);
        --a;
        --b;
        --c;
        --d;
        if(a > c){
            swap(a, c);
            swap(b, d);
        }
        if(b > d){
            b = M - b;
            d = M - d;
        }
        printf("%lu\n", max(calc(a, b, c, d), calc(b, a, d, c)));
    }
    return 0;
}

