long long solve2(long long xa, long long xb, int level) {
    if (level == 0) {
        return abs(xb - xa);
    }
    int ra = xa / pot[level - 1];
    int rb = xb / pot[level - 1];
    if (ra == rb) {
        if (ra == 1) {
            xa = xa % pot[level - 1];
            xb = xb % pot[level - 1];
            return min(xa + xb + 2, pot[level - 1] - xa + pot[level - 1] - xb);
        }
        if (rb == 2) {
            xa = xa % pot[level - 1];
            xb = xb % pot[level - 1];
        }
        return solve2(xa, xb, level - 1);
    } else {
        return abs(xa - xb);
    }
}


