}

long long solve(long long xa, long long ya, long long xb, long long yb, int level) {    

    if (level == 0) {
        return abs(xb - xa) + abs(yb - ya);
    }
    int ra = xa / pot[level - 1];
    int ca = ya / pot[level - 1];
    int rb = xb / pot[level - 1];
    int cb = yb / pot[level - 1];
    if (ra == rb && ca == cb) {
        return solve(xa % pot[level - 1], ya % pot[level - 1], xb % pot[level - 1], yb % pot[level - 1], level - 1);
    }

    if (ra != rb && ca != cb) {
        return abs(xa - xb) + abs(ya - yb);
    }
    if (ra == rb) {
        long long d = abs(ya - yb);
        if (abs(cb - ca) == 2) {
            return d + solve2(xa, xb, level);
        }
//         cerr << max(solve3(xa % pot[level - 1], xb % pot[level - 1], min(ya, yb) % pot[level - 1], 1, level - 1), solve3(xa, xb, max(ya, yb) % pot[level - 1], 0, level - 1)) << endl;
        return d + max(solve3(xa % pot[level - 1], xb % pot[level - 1], min(ya, yb) % pot[level - 1], 1, level - 1), solve3(xa % pot[level - 1], xb % pot[level - 1], max(ya, yb) % pot[level - 1], 0, level - 1));
    }
    if (ca == cb) {
        long long d = abs(xa - xb);
        if (abs(rb - ra) == 2) {
            return d + solve2(ya, yb, level);
        }
        return d + max(solve3(ya % pot[level - 1], yb % pot[level - 1], min(xa, xb) % pot[level - 1], 1, level - 1), solve3(ya % pot[level - 1], yb % pot[level - 1], max(xa, xb) % pot[level - 1], 0, level - 1));
    }
    return 0;
}

