ll dist(pll ab, pll cd, pii level)
{
    if (level.first == 0)
        return abs(ab.second - cd.second);

    ll pow_three_x = pow(3, level.first - 1);

    int A = ab.first / pow_three_x;
    int C = cd.first / pow_three_x;

    if (A != C)
        return L1norm(ab - cd);

    ab.first -= A * pow_three_x;
    cd.first -= A * pow_three_x;
    level.first--;

    if (A != 1)
        return dist(ab, cd, level);

    // A==C==1
    ll B = (ab.second + pow_three_x) / pow_three_x / 3;
    ll D = (cd.second + pow_three_x) / pow_three_x / 3;
    if (B == D)
        return dist(ab, cd, level);

    ll dx = min(abs(ab.first - (-1)) + abs(cd.first - (-1)), abs(ab.first - pow_three_x) + abs(cd.first - pow_three_x));
    ll dy = abs(ab.second - cd.second);
    return dx + dy;
}

