		array<ll, 2> a, b;
		cin>>a[0]>>a[1]>>b[0]>>b[1];--a[0],--a[1],--b[0],--b[1];
		ll ans=0;
		FOR(i,0,30){
			if(a[0] / p3[i] == b[0] / p3[i] && a[1] / p3[i] == b[1] / p3[i]) continue;
