				cerr<<i<<"!\n";
				ans=max(ans,min({a[0]%p3[i+1]-p3[i]+1,p3[i]*2-a[0]%p3[i+1],b[0]%p3[i+1]-p3[i]+1,p3[i]*2-b[0]%p3[i+1]}));
