typedef long long LL;

typedef pair<LL, LL> P;

P s, t;

LL p3[100];


int findK(const P &p) {
    int k = 0;
    LL mx = max(p.first, p.second);
    while (p3[k] < mx)
        ++k;
    return k;
}

P idp(const P &p, int k) {
    if (k == 0)
        return p;
    else {
        return P(p.first / p3[k-1], p.second / p3[k-1]);
    }
}

LL dis(const P &a, const P &b) {
    return llabs(a.first - b.first) + llabs(a.second - b.second);
}


int main(int argc, char const *argv[]) {
    // code
    p3[0] = 1;
    for (int i=1; i<=30; ++i)
        p3[i] = p3[i-1] * 3;
    int tt; scanf("%d", &tt);
    for (int kk=0; kk<tt; ++kk) {
        // cin >> s.first >> s.second >> t.first >> t.second;
        scanf("%lld%lld%lld%lld", &s.first, &s.second, &t.first, &t.second);
        if (s == t) {
            puts("0");
            continue;
        }
        --s.first; --t.first;
        --s.second; --t.second;
        if (s.second > t.second)
            swap(s, t);
        int k = max(findK(s), findK(t));

        P ids = idp(s, k), idt = idp(t, k);
        while (ids == idt && k > 0) {
            P xp(ids.first * p3[k-1], ids.second * p3[k-1]);
            s.first -= xp.first;
            s.second -= xp.second;
            t.first -= xp.first;
            t.second -= xp.second;
            --k;
            ids = idp(s, k); idt = idp(t, k);
        }
        // dbg(ids.first, ids.second, idt.first, idt.second, k);
        LL ans = dis(s, t);
        if (ids.first == idt.first && ids.second == 0) { // left to right
            P b1(p3[k-1], p3[k-1]-1), b2(p3[k-1], p3[k-1]*2),
            c1(p3[k-2]*2-1, p3[k-1]-1), c2(p3[k-1]*2-1, p3[k-1]*2);
            LL tans = min(dis(s, b1) + dis(b2, t), dis(s, c1) + dis(c2, t)) + 3 + p3[k-1];
            ans = max(ans, tans);
        } else if (ids.second == idt.second && ids.first == 0) {
            P b1(p3[k-1]-1, p3[k-1]), b2(p3[k-1]*2, p3[k-1]),
            c1(p3[k-1]-1, p3[k-1]*2-1), c2(p3[k-1]*2, p3[k-1]*2-1);
            LL tans = min(dis(s, b1) + dis(b2, t), dis(s, c1) + dis(c2, t)) + 3 + p3[k-1];
            ans = max(ans, tans);
        }
        printf("%lld\n", ans);
    }
    return 0;
}

