//sx <= gx
ll func(ll sx,ll sy,ll gx,ll gy,int level){
  if(level==1){
    if(sx==1&&gx==1)return 2;
    return 0;
  }
  if(gx-sx> current_wide(level-1))return 0;
  if(gx/current_wide(level-1) != sx/current_wide(level-1))return 0;
  if(sx/current_wide(level-1)==1&&gx/current_wide(level-1)==1&&min(sy,gy)<current_wide(level-1)&&current_wide(level-1)*2<=max(sy,gy)){
    return min((sx-current_wide(level-1)+1)*2,(current_wide(level-1)*2-sx)*2);
  }
  sx %= current_wide(level-1);
  gx %= current_wide(level-1);
  if(abs(sy-gy)>current_wide(level-1)){
    return func(sx,current_wide(level-1)-1,gx,0,level-1);
  }
  sy %= current_wide(level-1);
  gy %= current_wide(level-1);

  return func(sx,sy,gx,gy,level-1);
}

