long long process(long long x1, long long y1, long long x2, long long y2)
{
	long long d = 1;
	for (int i = 0; i < 2; i++) d *= 3;

	if (y1 > y2)
	{
		swap(x1, x2);
		swap(y1, y2);
	}

	long long result = abs(x1 - x2) + abs(y1 - y2);
	while (d > 1)
	{
		d /= 3;

		long long x1_idx = x1 / d;
		long long x2_idx = x2 / d;
		long long y1_idx = y1 / d;
		long long y2_idx = y2 / d;
		if (x1_idx != x2_idx) break;

		if (x1_idx % 3 == 1 && abs(y1_idx - y2_idx) > 1)
		{
			result += abs(y1 - y2) + min(x1 % d + 1 + x2 % d + 1, (d - x1 % d) + (d - x2 % d));
			break;
		}
	}

	return result;
}

