/*
 * 避けなければならないものは高々一つです。
 * 大きい方から順にためします。
 *
 * 最大の壁は 3^30 です。
 * L で割った商を見ましょう。
 *
 * 事前条件（このとき、3L はないものとしてよいです。）：
 *     i0/3L==i1/3L
 *
 * f(i0,j0,i1,j1,L):
 * match (i0/L==i1/L, j0/L==j1/L)
 *     (false,false) => 最短
 *     (true,false) => {
 *         if i0/L%3==1 && 2<=abs(j0/L-j1/L) { // L を回避です。
 *             min(i0%L+1,i1%L+1,L-i0%L,L-i1%L)
 *         }
 *         f(..,L/3)
 *     }
 *     (false, true) => swap(i0,j0),swap(i1,j1)
 *     (true,true) => ひとつ下の事前条件を満たします。
 *
 * 縦のみまたは横のみ違っているばあいは、L が邪魔ならそれを避けます。
 * そうでなければもう少し小さいものを見ましょう。
 *
 * 3L が邪魔でなく、かつ i を L で割った商が等しいとします。
 * このとき、L が邪魔である条件は、(i/3L)%L==1 && 2<=j1/L-j0/L です。
 */

#include <bits/stdc++.h>
#define rep(i,n) for(int i=0; i<int(n); i++)
typedef long long ll;
using namespace std;

ll solve(ll x1, ll y1, ll x2, ll y2) {
	ll d=1;
	rep(i, 30) d*=3; // pow(3, 30)
	if( x1>x2 ) swap(x1, x2), swap(y1, y2);
	ll ans=abs(x1-x2)+abs(y1-y2);
	while(d > 1) {
		d/=3;
		ll nx1=x1/d, nx2=x2/d;
		ll ny1=y1/d, ny2=y2/d;
		if( nx1!=nx2 ) break;
		if( nx1%3==1 && ny1!=ny2 ) {
			ll top=nx1*d-1;
			ll bot=nx1*d+d;
			ll loss=min(nx1,nx2)-top;
			loss=min(loss, bot-max(nx1,nx2));
			ans+=loss*2;
			break;
		}
	}
	return ans;
}

int main () {
	int Q;
	cin >> Q;
	while(Q--) {
		ll x1,y1,x2,y2;
		cin >> x1 >> y1 >> x2 >> y2;
		x1--; y1--; x2--; y2--;
		ll ans1 = solve(x1, y1, x2, y2);
		ll ans2 = solve(y1, x1, y2, x2);
		cout << max(ans1, ans2) << '\n';
	}
	return 0;
}

