	vector<ll> pow3(31);
	pow3[0] = 1;
	for (int i = 1; i <= 30; i++) {
		pow3[i] = pow3[i - 1] * 3LL;
	}

	for (int q = 0; q < Q; q++) {
		ll a, b, c, d; cin >> a >> b >> c >> d;
		a--, b--, c--, d--;
		if (a > c) {
			ll e = a; a = c; c = e;
			e = b; b = d; d = e;
		}
		if (b > d) {
			b = pow3[30] - 1 - b;
			d = pow3[30] - 1 - d;
		}

		if (c - a < d - b) {
			ll e = a; a = b; b = e;
			e = c; c = d; d = e;
		}

		ll ans = c - a + d - b;

		vector<ll> A(30), B(30), C(30), D(30);
		for (int i = 0; i < 30; i++) {
			A[i] = a % 3;
			B[i] = b % 3;
			C[i] = c % 3;
			D[i] = d % 3;

			a /= 3;
			b /= 3;
			c /= 3;
			d /= 3;
		}

		ll y = 0;
		for (int i = 29; i >= 0; i--) {
			if (A[i] == C[i]) { continue; }
			if (B[i] != D[i]) { break; }

			y += pow3[i] * B[i];

