typedef llint Int;

Int distance(Int a, Int b, Int c, Int d, Int k)
{
    Int u = k/3;
    if (a > c) swap(a,c);
    if (b > d) swap(b,d);

    int ap=a/u, bp=b/u, cp=c/u, dp=d/u;
    if (ap != cp && bp != dp) {
        return (c-a)+(d-b);
    } else if (ap == cp) {
        swap(a, b);
        swap(c, d);
    }

    Int v = u;
    Int bj=b, dj=d;
    while (v > 1) {
        if (bj/v == dj/v && bj/v == 1) {
            break;
        } else if (bj/v != dj/v) {
            v = 1;
            break;
        } else {
            bj %= v;
            dj %= v;
            v /= 3;
        }
    }
    if (v==1 || (a-v/3)%v == (c-v/3)%v) {
        return c-a+d-b;
    } else {
        bj %= v;
        dj %= v;
        Int diff = max(bj+dj, 2*v-bj-dj) - (dj-bj);
        return c-a+d-b + diff;
    } 
}


