  ll ans = abs(a.first - b.first) + abs(a.second - b.second);
  for (int i = 30; i > 0; i--) {
    ll sx = a.first % fractal_size[i];
    ll gx = b.first % fractal_size[i];
    ll sy = a.second;
    ll gy = b.second;

    if (sx >= black_pos[i] && sx < black_pos[i] + black_size[i] && gx >= black_pos[i] &&
        gx < black_pos[i] + black_size[i]) {
      if ((sy < black_pos[i] && gy >= black_pos[i] + black_size[i]) ||
          (gy < black_pos[i] && sy >= black_pos[i] + black_size[i])) {
        ans = abs(sx - black_pos[i]) + abs(gx - black_pos[i]);
        chmin(ans, abs(sx - black_pos[i] + black_size[i]) + abs(gx - black_pos[i] + black_size[i]));
        ans += abs(a.second - b.second);
        break;
      }
      break;
    }
  }
  return ans;
}

