LL p3[31] = {1};

LL solve(LL a, LL b, LL c, LL d){
	if(a > c){
		a = p3[30] - 1 - a;
		c = p3[30] - 1 - c;
	}
	if(b > d){
		b = p3[30] - 1 - b;
		d = p3[30] - 1 - d;
	}

	int l;
	for(l = 29; ; --l){
		if(l < 0){
			return c + d - a - b;
		}
		LL e = c / p3[l], f = d / p3[l];
		if(e % 3 != 1){ --e; }
		if(e % 3 != 1){ --e; }
		if(f % 3 != 1){ --f; }
		if(f % 3 != 1){ --f; }
		if(e >= 0 && f >= 0 && (e + 1) * p3[l] >= a && (f + 1) * p3[l] >= b){
			auto calc = [](LL x, LL y, LL z){ return abs(x - z) + abs(y - z); };
			LL ret = 0;
			ret += min(calc(a, c, e * p3[l] - 1), calc(a, c, (e + 1) * p3[l]));
			ret += min(calc(b, d, f * p3[l] - 1), calc(b, d, (f + 1) * p3[l]));
			return ret;
		}
	}
}

