void solve() {
  int n = 1;
  rep(i,30) n *= 3;

  int q; cin >> q;

  while (q--) {
    int a, b, c, d; cin >> a >> b >> c >> d;
    int level = 30;
    int lx = 0, rx = n;
    int ly = 0, ry = n;
    int A, B, C, D;

    while (--level) {
      int sx = lx + (rx-lx) / 3;
      int tx = rx - (rx-lx) / 3;
      A = (a<=sx ? 0 : (a<=tx ? 1 : 2));
      C = (c<=sx ? 0 : (c<=tx ? 1 : 2));
      int sy = ly + (ry-ly) / 3;
      int ty = ry - (ry-ly) / 3;
      B = (b<=sy ? 0 : (b<=ty ? 1 : 2));
      D = (d<=sy ? 0 : (d<=ty ? 1 : 2));

      lx += (rx-lx) / 3 * A;
      rx -= (rx-lx) / 3 * (2-A);
      ly += (ry-ly) / 3 * B;
      ry -= (rx-lx) / 3 * (2-B);

      if (A != C || B != D) break;
    }

    if ((A != C && B != D) || level == 0) {
      cout << abs(a-c) + abs(b-d) << endl;
      continue;
    }

    if (B == D) {
      swap(a,c); swap(b,d);
      swap(A,C); swap(B,D);
      swap(lx,ly); swap(rx,ry);
    }

    if (A == 1) {
      cout << min(a-lx + c-lx, rx-a + rx-c) + abs(b-d) << endl;
      continue;
    }

    while (level--) {
      int sx = lx + (rx-lx) / 3;
      int tx = rx - (rx-lx) / 3;
      A = (a<=sx ? 0 : (a<=tx ? 1 : 2));
      C = (c<=sx ? 0 : (c<=tx ? 1 : 2));
      lx += (rx-lx) / 3 * A;
      rx -= (rx-lx) / 3 * (2-A);

      if (A == 1) {
        cout << min(a-lx + c-lx, rx-a + rx-c) + abs(b-d) << endl;
        break;
      }

      if (A != C || level == 0) {
        cout << abs(a-c) + abs(b-d) << endl;
        break;
      }
    }
  }
}


