ll check(ll scale, pll ab, pll cd, pll p) {
	ll block = 1;
	rep(i, scale - 1) block * 3;

	pll a, c;
	a.first = ab.first / block;
	a.second = ab.second / block;
	c.first = cd.first / block;
	c.second = cd.second / block;

	if (a.first == c.first || a.second == c.second) {
		if (a.first == 1 && a.second != c.second) {
			if (!(a.second > c.second && p.second == 1) && !(a.second < c.second && p.second == -1)) {
				return abs(ab.second - cd.second) + min(ab.first - block + cd.first - block, (4 * block + 2) - ab.first - cd.first);
			}
		}
		else if (a.second == 1 && a.first != c.first) {
			if (!(a.first > c.first && p.first == 1) && !(a.first < c.first && p.first == -1)) {
				return abs(ab.first - cd.first) + min(ab.second - block + cd.second - block, (4 * block + 2) - ab.second - cd.second);
			}
