i64 result(i64 a, i64 b, i64 c, i64 d) {
    if(a > c) {
      swap(a, c);
      swap(b, d);
    }

    i64 W = 3;
    i64 len = 1;
    rep(L, 0, 29) {
      len *= 3;
      W *= 3;
    }

    i64 Lans = -1;
    i64 delta = abs(c - a) + abs(d - b);
    for(i64 L = 30; L --> 0;) {
      i64 A = a % W;
      i64 C = c % W;
      //cout << L << ": " << A << " " << C << " -- " << len << endl;
      if(A <= C && len <= A && C < len + len) {
        if(abs(d - b) >= W) {
          Lans = L;
          break;
        }
        i64 B = b % W;
        i64 D = d % W;
        if(b > d) swap(B, D);
        if(!(B <= D && len <= B && D < len + len)) {
          Lans = L;
          break;
        }
      }
      W /= 3;
      len /= 3;
    }
    if(Lans != -1) {
      //cout << Lans << endl;
      i64 A = a % W;
      i64 C = c % W;
      delta = delta + std::min(A - len + 1, len + len - C) * 2;
    }
    return delta;
}

