bool interval(ll x, ll y1, ll y2) {
	if (y1 > y2) swap(y1, y2);
	y1++; y2--;
	if (y1 > y2) return false;
	while (x > 0)
	{
		if (x % 3 == 1) {
			if (y2 - y1 > 3) return true;
			for (ll y = y1; y <= y2; y++) {
				if (y % 3 == 1) return true;
			}
		}
		x /= 3;
		y1 /= 3;
		y2 /= 3;
	}
}
