}

li diffs(li a,li b){
  // a,b は xの幅にいる
  li x=1;
  while(a!=b){
    a/=3; b/=3; x*=3;
  }
  return x;
}

int btwn(li a,li b,li c,li d,li bd){
  a%=bd*3; c%=bd*3;
  if(a/bd!=1)return 0;
  b/=bd; d/=bd;
  if(d-b>4) return 1;
  if(d%3==2 or b%3==0)return 1;
  return 0;
}

li di(li a,li b,li c,li d){
  li ac=diffs(a,c),bd=diffs(b,d);
  if(ac>=bd){
    swap(ac,bd);
    swap(a,c);
    swap(b,d);
  }
  bd/=3;
  while(bd>ac){
    if(btwn(a,b,c,d,bd))break;
    bd/=3;
  }
  li m=min(a%bd+c%bd, (a-a%bd)+(c-c%bd));
  return dist(a,c)+dist(b,d)+m;
}


