inline long long getDist(long long div, long long a, long long b) {
    long long blk1 = a / div;
    long long blk2 = b / div;

    if (blk1 == blk2 && blk1%3 == 1) {
        long long from = blk1 * div;
        long long to = blk1 * div + div - 1;
        return min(abs(a-from)+abs(b-from), abs(b-to)+abs(b-from));
    }

    return abs(a-b);
}

long long solve(long long a, long long b, long long c, long long d) {
    long long dx = INF;
    long long dy = INF;
    long long div = 3;

    for (int i = 0; i < MAXD; ++i) {
        dx = min(dx, getDist(div, a, c));
        dy = min(dy, getDist(div, b, d));

        div *= 3;
    }

    return dx + dy;
}

