inline long long getDist(long long div, long long a, long long b, long long da, long long db) {
    long long blk1 = a / div;
    long long blk2 = b / div;

    long long dblk1 = da / div;
    long long dblk2 = db / div;
    bool cross = false;

    if (dblk1 - dblk2 >= 3) {
        cross = true;
    } else {
        for (long long y = dblk1; y <= dblk2; ++y) {
            if (y % 3 == 1) {
                cross = true;
                break;
            }
        }
    }

    if (blk1 == blk2 && blk1%3 == 1 && cross) {
        long long from = blk1 * div;
        long long to = blk1 * div + div - 1;
        return min(abs(a-from)+abs(b-from), abs(b-to)+abs(b-to));
