    if (blk1 == blk2 && blk1%3 == 1 && checkCross(min(dblk1, dblk2), max(dblk1, dblk2))) {
        long long from = blk1 * div - 1;
        long long to = (blk1+1) * div;
        return min(abs(a-from)+abs(b-from), abs(a-to)+abs(b-to));
