      ll e = a-c==0 ? a : b;  // 縦か横に並んでいるが、うちindexが同じものを入れる
      ll buf = h; ll left = 0;
      rep(i, 30){
        h /= 3;
        if (left + h <= e && e < left + 2*h){
          // 一辺の長さhの黒い正方形が間に立ちふさがっている
          res += 2 * min(e - (left+h-1), left + 2*h - e); // よけて進
          break;
        }else if (left + 2*h <= e){
          // こっちじゃなければleftの更新は必要ないがこっちは必要
          left += 2*h;
        }
      }
      cout <<res <<endl;
    }else{
      // 最短距離は折れ線になる
      ll buf = h; ll left = 0, up = 0;
      rep(i, 29){ // 大きさ1*1の黒は邪魔になりえない
        h /= 3;
        if (min(abs(a-c),abs(b-d)) >= h) break; // 両方の差が大きければ避けられる、以降のより小さいやつも同様
        if (left + h <= min(a,c) && max(a,c) < left + 2*h && up + h <= min(b,d) && max(b,c) < up + 2*h){
          // 両方小さかったらおかしいよね
          cout <<"hey" <<endl;
        }else if (left + h <= min(a,c) && max(a,c) < left + 2*h){
          // 縦方向に引っかかる
          res += 2 * min(min(a,c) - (left+h-1), left + 2*h - max(a,c));
          break;
        }else if (up + h <= min(b,d) && max(b,c) < up + 2*h){
          res += 2 * min(min(b,d)- (up+h-1), up + 2*h - max(b,d));
          break;
        }else{
          // 引っかからない
          if (min(a,c) >= left + 2*h) left += 2*h;
          if (min(b,d) >= up + 2*h) up += 2*h; 
        }
      }
      cout <<res <<endl;
    }
  }
