ll solve_eq(ll p,ll q,ll a,ll b){
    ll cur = 0, cur2 = 0, base = 1, ans = abs(a-b) + abs(p-q), ret = abs(a-b) + abs(p-q);

    while(p || q){
        if(p%3 == 1 && p == q){
            for(ll x=a;x<=b;x++){
                ll aa = x, ab = p;
                {
                    if(aa%3 == 1 && ab%3 == 1){
                        chmax(ret, ans + min(cur+1+cur2+1, base+base-cur2-cur));
                        goto nxt;
                    }
                }
            }
        }
        nxt:;
        cur += p%3 * base;
        cur2 += q%3 * base;
        base *= 3;

        p /= 3;
        q /= 3;
        a /= 3;
        b /= 3;
    }
    return ret;
}
