using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	ULL Solve2(ULL x0, ULL y0, ULL x1, ULL y1, ULL d = 205891132094649) {
		ULL xx0 = x0 / d, xx1 = x1 / d;
		ULL yy0 = y0 / d, yy1 = y1 / d;
		if (d == 1) {
			ULL dx = max(xx0, xx1) - min(xx0, xx1);
			ULL dy = max(yy0, yy1) - min(yy0, yy1);
			return dx + dy;
		}
		x0 %= d; y0 %= d;
		x1 %= d; y1 %= d;
		if (xx0 == xx1 && yy0 == yy1) return Solve2(x0, y0, x1, y1, d / 3);
		if (xx0 == xx1) {
			swap(xx0, yy0); swap(xx1, yy1);
			swap(x0, y0); swap(x1, y1);
		}
		if (yy0 == 1 && yy1 == 1) {
			if (xx0 == 2) {
				swap(xx0, xx1); swap(yy0, yy1);
				swap(x0, x1); swap(y0, y1);
			}
			ULL D0 = (d - x0) + (d - y0) + (d - x1) + (d - y1);
			ULL D1 = (d - x0) + (y0 + 1) + (d - x1) + (y1 + 1);
			return min(D0, D1) + d + 1;
		}
		if (yy0 == yy1) {
			if (xx0 > xx1) {
				swap(xx0, xx1); swap(yy0, yy1);
				swap(x0, x1); swap(y0, y1);
			}
			if (x0 > x1) {
				ULL dd = d / 3;
				ULL xxx0 = x0 / dd, xxx1 = x1 / dd;
				ULL yyy0 = y0 / dd, yyy1 = y1 / dd;
				x0 %= dd; x1 %= dd;
				if (xxx1 - xxx0 + (xx1 - xx0) * 3 == 1)
					return Solve2(x0, y0, x1 + dd, y1, dd);
				else
					return Solve2(x0, y0, x1 + dd * 2, y1, dd) +
					(xxx1 - xxx0 + (xx1 - xx0) * 3 - 2) * dd;
			}
		}
		x0 += 3 * xx0; x1 += 3 * xx1;
		y0 += 3 * yy0; y1 += 3 * yy1;
		ULL dx = max(x0, x1) - min(x0, x1);
		ULL dy = max(y0, y1) - min(y0, y1);
		return dx + dy;
	}

	void Solve() {
		UL Q; cin >> Q;
		rep(i, Q) {
			UL a, b, c, d; cin >> a >> b >> c >> d;
			a--; b--; c--; d--;
			cout << Solve2(a, b, c, d) << endl;
		}
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

