    int64_t dh = abs(a.at(i) - c.at(i)), dw = abs(b.at(i) - d.at(i));
    int64_t direct = dh + dw;
    vector<int> a3(30), b3(30), c3(30), d3(30);
    a.at(i)--; b.at(i)--; c.at(i)--; d.at(i)--;
