    for (int j = 0; j < 30; j++) {
      c3.at(j) = c.at(i) % 3;
      c.at(i) /= 3;
    }
    for (int j = 0; j < 30; j++) {
      d3.at(j) = d.at(i) % 3;
      d.at(i) /= 3;
    }
    int64_t add_h = 0, add_w = 0;
    bool same_h = true, same_w = true;
    for (int j = 29; j >= 0; j--) {
      if (add_h == 0 && same_h && a3.at(j) == 1 && c3.at(j) == 1
          && ((same_w && dw >= p.at(j)) || dw >= 2 * p.at(j))) {
        int64_t ar = (j == 0) ? 0 : a3.at(j - 1),
        cr = (j == 0) ? 0 : c3.at(j - 1);
        add_h = 2 * min({ar + 1, p.at(j) - ar,
                         cr + 1, p.at(j) - cr});
      }
      if (add_w == 0 && same_w && b3.at(j) == 1 && d3.at(j) == 1
