ll calc2(ll x1, ll y1, ll x2, ll y2) {

	ll res = 0;
	ll v = pow(3, 30);
	if (y1 > y2) {
		swap(y1, y2);
	}
	// 縦のエリアが同じ限り処理する
	while (v > 3)
	{
		v /= 3;
		// 縦のエリアが同じかどうか
		if (getArea(x1, v) != getArea(x2,v))break;

		// 同じエリア内で両方1かどうか
		ll po = v / 3;
		ll p1 = x1 % v;
		ll p2 = x2 % v;
		if (getArea(p1,po) != 1 || getArea(p2, po) != 1)
			continue;

		// 両方同じエリア内で1である場合Yの位置が2以上離れているか
		ll le = y2 - y1;
		if (le / po < 2) continue;
		res = max(res, calc3(p1 % po, p2 % po, po));

	}
	return res;
}

ll calc(ll x1, ll y1, ll x2, ll y2) {
	return abs(x1 - x2) + abs(y1 - y2)
		+ max(calc2(x1, y1, x2, y2), calc2(y1, x1, y2, x2));
}
