using namespace std;

vector<int> ternary(long long x) {
    vector<int> repr;
    for (long long p = 3, i = 0; i < 30; p *= 3, x /= 3, i++)
        repr.push_back(x % p);
    return repr;
}

long long pw(int e) {
    long long ret = 1, p = 3;
    while (e > 0) {
        if (e % 2) ret *= p;
        p *= p;
        e /= 2;
    }
    return ret;
}

long long ev(vector<int>& repr) {
    long long val = 0;
    for (int t : repr) val = 3 * val + t;
    return val;
}

long long dist(long long a, long long b, long long c, long long d) {
    return abs(a - b) + abs(c - d);
}

long long solve(long long a, long long b, long long c, long long d) {
    vector<int> r1 = ternary(a), c1 = ternary(b),
        r2 = ternary(c), c2 = ternary(d);
    while (r1.back() == r2.back() && c1.back() == c2.back()) {
        r1.pop_back();
        c1.pop_back();
        r2.pop_back();
        c2.pop_back();
    }
    assert (!r1.empty() && !c1.empty() && !r2.empty() && !c2.empty());
    if (c1.back() == c2.back()) {
        swap(r1, c1);
        swap(r2, c2);
    }
    assert(c1.back() != c2.back());
    if (r1.back() == r2.back()) {
        return abs(a - c) + abs(b - d);
    } else {
        while (!r1.empty() && r1.back() == r2.back()) {
            if (r1.back() == 1) {
                long long p = pw(r1.size()) - 1,
                    q = (3 * p - 1) / 2,
                    d1 = dist(ev(r1), ev(c1), p, q) + dist(ev(r2), ev(c2), p, q),
                    p1 = 2 * p + 1,
                    d2 = dist(ev(r1), ev(c1), p1, q) + dist(ev(r2), ev(c2), p1, q);
                return min(d1, d2);
            }
            r1.pop_back();
            r2.pop_back();
        }
        return abs(a - c) + abs(b - d);
    }
}

int main() {
    int q; cin >> q;
    while (q--) {
        long long a, b, c, d; cin >> a >> b >> c >> d;
        cout << solve(a-1, b-1, c-1, d-1) << endl;
    }
}

