ll func(ll sx,ll sy,ll gx,ll gy,int level){
  if(level==1){
    return (sx==1&&gx==1)*2;
  }
  ll wide = current_wide(level-1);
  if(sx/wide!=gx/wide)return 0;
  if(sx/wide==1&&gx/wide==1&&abs(sy-gy)>wide){
    return max((sx-wide+1)*2,(wide*2-sx)*2);
  }
  sx %= wide;
  gx %= wide;
  if(sy/wide==gy/wide){
    sy %= wide;
    gy %= wide;
    return func(sx,sy,gx,gy,level-1);
  }else{
    if(sy>gy)swap(sy,gy);
    sy %= wide;
    gy %= wide;
    return max(func(sx,sy,gx,wide-1,level-1),func(sx,0,gx,gy,level-1));
  }
  return 0;
}



