vec san(32, 1);

int bit3_t(ll a, int t){
    return (a % san[t + 1]) / san[t];
}

ll f(ll a, ll b, ll c, ll d){
    ll res = 0;
    Rrep(i, 31){
        if(a / san[i] != c / san[i]
        && b / san[i] != d / san[i]) break;
        if(bit3_t(b, i) == 1 && bit3_t(d, i) == 1){
            swap(a, b);
            swap(c, d);
        }
        if(bit3_t(a, i) == 1 && bit3_t(c, i) == 1){
            if(abs(d - b) >= 2 * san[i]
            || abs((d % (san[i + 1])) - (b % (san[i + 1]))) >= san[i]){
                ll diff1 = a % san[i], diff2 = c % san[i];
                res = max(res, min({diff1 + 1, san[i] - diff1,
                                    diff2 + 1, san[i] - diff2}) * 2);
            }
        }
    }
    return res;
}


