void nor(ll &h1,ll &w1,ll &h2,ll &w2,ll level){
    if(h1>h2){
        h1=rui[level]-1-h1;
        h2=rui[level]-1-h2;
    }
    if(w1>w2){
        w1=rui[level]-1-w1;
        w2=rui[level]-1-w2;
    }
}

ll findmi(ll s,ll level){
    if(level==0) return 0;
    ll ba1=rui[level-1];

    ll ps=s/ba1;
    s%=ba1;

    if(ps==0) return findmi(s,level-1);
    if(ps==1) return ba1-1;
    if(ps==2) return ba1*2+findmi(s,level-1);

    return 0;
}

ll findma(ll s,ll level){
    if(level==0) return 0;
    ll ba1=rui[level-1];

    ll ps=s/ba1;
    s%=ba1;

    if(ps==0) return findma(s,level-1);
    if(ps==1) return ba1*2;
    if(ps==2) return ba1*2+findma(s,level-1);

    return 0;
}

ll solve(ll h1,ll w1,ll h2,ll w2,ll level){
    if(level==0) return 0;

    ll ba1=rui[level-1];

    nor(h1,w1,h2,w2,level);

    ll ph1,pw1,ph2,pw2;
    ph1=h1/ba1;
    pw1=w1/ba1;
    ph2=h2/ba1;
    pw2=w2/ba1;

    h1%=ba1;
    w1%=ba1;
    h2%=ba1;
    w2%=ba1;

    if(ph1!=ph2&&pw1!=pw2){
        ll a=solve(h1,w1,ba1-1,ba1-1,level-1);
        ll b=solve(h2,w2,0,0,level-1);

        return a+b+2+(ph2-ph1-1+pw2-pw1-1)*ba1;
    }

    if(ph1==ph2&&pw1==pw2){
        return solve(h1,w1,h2,w2,level-1);
    }

    if(ph1==ph2){
        if(ph1==1){
            ll a1=solve(h1,w1,0,ba1-1,level-1),a2=solve(h1,w1,ba1-1,ba1-1,level-1);
            ll b1=solve(h2,w2,0,0,level-1),b2=solve(h2,w2,ba1-1,0,level-1);

            return min(a1+b1+ba1+2,a2+b2+ba1+2);
        }else{
            ll mi1=findmi(h1,level-1),mi2=findmi(h2,level-1);
            ll ma1=findma(h1,level-1),ma2=findma(h2,level-1);

            ll res=INF;

            ll a1=solve(h1,w1,mi1,ba1-1,level-1),a2=solve(h1,w1,ma1,ba1-1,level-1);
            ll b1=solve(h2,w2,mi2,0,level-1),b2=solve(h2,w2,ma2,0,level-1);

            chmin(res,a1+b1+abs(mi2-mi1)+1+ba1);
            chmin(res,a1+b2+abs(ma2-mi1)+1+ba1);
            chmin(res,a2+b1+abs(mi2-ma1)+1+ba1);
            chmin(res,a2+b2+abs(ma2-ma1)+1+ba1);

            return res;
        }
    }

    if(pw1==pw2){
        if(pw1==1){
            ll a1=solve(h1,w1,ba1-1,0,level-1),a2=solve(h1,w1,ba1-1,ba1-1,level-1);
            ll b1=solve(h2,w2,0,0,level-1),b2=solve(h2,w2,0,ba1-1,level-1);

            return min(a1+b1+ba1+2,a2+b2+ba1+2);
        }else{
            ll mi1=findmi(w1,level-1),mi2=findmi(w2,level-1);
            ll ma1=findma(w1,level-1),ma2=findma(w2,level-1);

            ll res=INF;

            ll a1=solve(h1,w1,ba1-1,mi1,level-1),a2=solve(h1,w1,ba1-1,ma1,level-1);
            ll b1=solve(h2,w2,0,mi2,level-1),b2=solve(h2,w2,0,ma2,level-1);

            chmin(res,a1+b1+abs(mi2-mi1)+1+ba1);
            chmin(res,a1+b2+abs(ma2-mi1)+1+ba1);
            chmin(res,a2+b1+abs(mi2-ma1)+1+ba1);
            chmin(res,a2+b2+abs(ma2-ma1)+1+ba1);

            return res;
        }
    }

    return 0;
}

