void MAIN() {
    scanf("%lld%lld%lld%lld", &X0, &Y0, &X1, &Y1);
    X0--;
    Y0--;
    X1--;
    Y1--;

    LL ans = 0;

    for (int t=31; t>=0; t--) {
	LL k = T[t];
	if ((X0/k != X1/k && Y0/k != Y1/k)) {
	    ans += abs(X0-X1) + abs(Y0-Y1);
	    break;
	}
	while (X0/k >= 3 && X1/k >= 3) {
	    X0 -= k*3;
	    X1 -= k*3;
	}
	while (Y0/k >= 3 && Y1/k >= 3) {
	    Y0 -= k*3;
	    Y1 -= k*3;
	}

	if (X0/k == 1 && X1/k == 1 && abs(Y0/k - Y1/k) >= 2) {
	    LL tmp1 = abs(X0 - (k-1)) + abs(X1 - (k-1));
	    LL tmp2 = abs(X0 - 2*k) + abs(X1 - 2*k);
	    ans += min(tmp1, tmp2) + abs(Y0-Y1);
	    break;
	}

	if (abs(X0/k - X1/k) >= 2 && Y0/k == 1 && Y1/k == 1) {
	    LL tmp1 = abs(Y0 - (k-1)) + abs(Y1 - (k-1));
	    LL tmp2 = abs(Y0 - 2*k) + abs(Y1 - 2*k);
	    ans += min(tmp1, tmp2) + abs(X0-X1);
	    break;
	}
	if (t == 0) {
	    ans += abs(X0-X1) + abs(Y0-Y1);
	    break;
	}

	if (X0 > X1) {
	    swap(X0, X1);
	    swap(Y0, Y1);
	}
	LL g = X1/k - X0/k;
	if (g >= 2) {
	    X1 -= (g-1)*k;
	    ans += (g-1)*k;
	}

	if (Y0 > Y1) {
	    swap(X0, X1);
	    swap(Y0, Y1);
	}
	g = Y1/k - Y0/k;
	if (g >= 2) {
	    Y1 -= (g-1)*k;
	    ans += (g-1)*k;
	}
    }
    printf("%lld\n", ans);
}

