LL shortestNeighbor(vector<int> x1, vector<int> y1, vector<int> x2, vector<int> y2, bool sameX) {
	int n = x1.size();
	LL res = 0;
	LL one = (LL)(1);
	for (int i = n - 1; i >= 0; --i) {
		if (!sameX) {
			if (y1[i] == 1 && y2[i] == 1) {
				LL yy1 = getX(y1, i);
				LL yy2 = getX(y2, i);
				LL sz = getM3(i);
				return getDis(yy1, yy2, sz);
			}
			else if (y1[i] != y2[i]) {
				return res;
			}
		}
		else {
			if (x1[i] == 1 && x2[i] == 1) {
				LL xx1 = getX(x1, i);
				LL xx2 = getX(x2, i);
				LL sz = getM3(i);
				return getDis(xx1, xx2, sz);
			}
			else if (x1[i] != x2[i]) {
				return res;
			}
		}
	}
	return res;
}

