// nを3進法に直す
vector<int> convert_3(int n) {
	vector<int> res;
	while (n) {
		res.push_back(n % 3);
		n /= 3;
	}
	while (res.size() < 30) res.push_back(0);
	reverse(res.begin(), res.end());
	return res;
}
// 3進法を直す
int inverse(vector<int>& a) {
	int res = 0;
	for (int i = 0; i < a.size(); ++i) {
		res *= 3; res += a[i];
	}
	return res;
}
// 3の累乗
int pow3(int k) {
	if (k == 0) return 1;
	return pow3(k - 1) * 3;
}
// 3進展開した座標から答えの計算
int _solve(
	vector<int>& st_x, vector<int>& st_y,
	vector<int>& gl_x, vector<int>& gl_y
) {
	int lv = st_x.size();
	if (lv == 0) return 0;
	if (st_x[0] != gl_x[0] || st_y[0] != gl_y[0]) {
		int pst = st_x[0] + 3 * st_y[0];
		int pgl = gl_x[0] + 3 * gl_y[0];
		int sx = inverse(st_x), sy = inverse(st_y);
		int gx = inverse(gl_x), gy = inverse(gl_y);
		if (pst + pgl == 8 && (pst & 1)) {
			if (min(pst, pgl) == 1) {
				int res = abs(sy - gy);
				res += min(
					4 * pow3(lv - 1) - sx - gx,
					sx + gx - 2 * pow3(lv - 1) + 2
				);
				return res;
			}
			else {
				int res = abs(sx - gx);
				res += min(
					4 * pow3(lv - 1) - sy - gy,
					sy + gy - 2 * pow3(lv - 1) + 2
				);
				return res;
			}
		}
		else {
			return abs(sx - gx) + abs(sy - gy);
		}
	}
	vector<int> _st_x, _st_y, _gl_x, _gl_y;
	for (int i = 1; i < lv; ++i) {
		_st_x.push_back(st_x[i]);
		_st_y.push_back(st_y[i]);
		_gl_x.push_back(gl_x[i]);
		_gl_y.push_back(gl_y[i]);
	}
	return _solve(_st_x, _st_y, _gl_x, _gl_y);
}
// 答えの計算
int solve(int a, int b, int c, int d) {
	auto va = convert_3(--a);
	auto vb = convert_3(--b);
	auto vc = convert_3(--c);
	auto vd = convert_3(--d);
	return _solve(va, vb, vc, vd);
}

