    }
    x %= pw3[sz - 1];
    auto next_ans = nearest_beam_to_up_with_front_block(x, sz - 1);
    next_ans.first += sx * pw3[sz - 1];
    next_ans.second += sx * pw3[sz - 1];
    return next_ans;
}

pair<lint, lint> nearest_beam_to_up(lint a, lint b, int sz){
    if(sz == 0){
        return {0, 0};
    }
    lint sy = a / pw3[sz - 1];
    lint sx = b / pw3[sz - 1];
    if(sy == 2 && sx == 1){
        return {pw3[sz - 1] - 1, pw3[sz - 1] * 2};
    }
    a %= pw3[sz - 1];
    b %= pw3[sz - 1];
    if(sy == 0){
        auto next_ans = nearest_beam_to_up(a, b, sz - 1);
        next_ans.first += sx * pw3[sz - 1];
        next_ans.second += sx * pw3[sz - 1];
        return next_ans;
    }
    auto next_ans = nearest_beam_to_up_with_front_block(b, sz - 1);
    next_ans.first += sx * pw3[sz - 1];
    next_ans.second += sx * pw3[sz - 1];
    return next_ans;
}

lint get_ans(lint a, lint b, lint c, lint d, int sz){
    if(sz == 0){
        return 0;
    }
    lint sy = a / pw3[sz - 1];
    lint sx = b / pw3[sz - 1];
    lint gy = c / pw3[sz - 1];
    lint gx = d / pw3[sz - 1];
    if(abs(sy - gy) && abs(sx - gx)){
        return abs(a - c) + abs(b - d);
    }
    lint save_a = a, save_b = b, save_c = c, save_d = d;
    a %= pw3[sz - 1];
    b %= pw3[sz - 1];
    c %= pw3[sz - 1];
    d %= pw3[sz - 1];
    if(sy == gy && sx == gx){
        return get_ans(a, b, c, d, sz - 1);
    }
    if(sy == gy){
        swap(a, b);
        swap(c, d);
        swap(sy, sx);
        swap(gy, gx);
    }
    if(sy > gy){
        swap(a, c);
        swap(b, d);
        swap(sy, gy);
        swap(sx, gx);
    }

    lint dist = gy - sy;
    pair<lint, lint> beam1, beam2;
    if(dist == 1){
        beam1 = nearest_beam_to_up(pw3[sz - 1] - 1 - a, b, sz - 1);
        beam2 = nearest_beam_to_up(c, d, sz - 1);
    }else{
        beam1 = nearest_beam_to_up_with_front_block(b, sz - 1);
        beam2 = nearest_beam_to_up_with_front_block(d, sz - 1);
    }
    lint ans = 1e18;
    ans = min(ans, abs(save_b - beam1.first) + abs(beam1.first - beam2.first) + abs(beam2.first - save_d));
    ans = min(ans, abs(save_b - beam1.second) + abs(beam1.second - beam2.first) + abs(beam2.first - save_d));
    ans = min(ans, abs(save_b - beam1.first) + abs(beam1.first - beam2.second) + abs(beam2.second - save_d));
    ans = min(ans, abs(save_b - beam1.second) + abs(beam1.second - beam2.second) + abs(beam2.second - save_d));
    return ans + abs(save_c - save_a);
}

