            dig[i][j] = cur % 3; cur /= 3;
            if (dig[i][j] == 1) one[i] = true;
        }
    }

    if (!one[0] || !one[1]) {
        return abs(A-B);
    }

    ll op1 = 0, op2 = 0;
    F0Rd(i, 30) {
        op1 *= 3; op2 *= 3;
        if (dig[0][i] != 1) {
            op1 += dig[0][i]; op2 += dig[0][i];
        } else {
            op2 += 2;
        }
    }

    return min(abs(A-op1)+abs(op1-B), abs(A-op2) + abs(op2-B));
}

