	VAR(int, Q);
	REP(_, Q) {
		VAR(int, x1, y1, x2, y2);
		--x1; --y1; --x2; --y2;
		int ans = std::abs(x1 - x2) + std::abs(y1 - y2);

		REP(i_, 2) {
			std::swap(x1, y1);
			std::swap(x2, y2);

			if (x1 == x2) continue;
			if (x1 > x2) {
				std::swap(x1, x2);
				std::swap(y1, y2);
			}
			assert(x1 < x2);

			REP(k, 30) {
				int X = x1 % p3[k + 1] / p3[k];
				int Y = y1 % p3[k + 1] / p3[k];
				if (Y == 1) {
					int X1 = x1 / p3[k] * p3[k];
					int Y1 = y1 / p3[k] * p3[k];
					if (X == 0) X1 += p3[k];
					else X1 += 2 * p3[k];
					if (X1 <= x2 && IN(Y1, y2, Y1 + p3[k])) {
						CHMAX(ans, std::min(std::abs(y1 - (Y1 - 1)) + std::abs(x1 - x2) + std::abs((Y1 - 1) - y2), std::abs(y1 - (Y1 + p3[k])) + std::abs(x1 - x2) + std::abs((Y1 + p3[k]) - y2)));
					}
				}
			}
		}
		OUT(ans)BR;
	}

	return 0;
}

