ll mh(ll a, ll b, ll c, ll d) {
	return abs(a - c) + abs(b - d);
}

int main() {
	d3[0] = 1;
	for (int i = 1;i < 31;i++) {
		d3[i] = d3[i - 1] * 3;
	}
	ll Q, a, b, c, d, A, B, C, D, ans;
	cin >> Q;

	for (int i = 0;i < Q;i++) {
		cin >> a >> b >> c >> d;
		a--;b--;c--;d--;
		ans = -1;
		if (abs(a - c) > abs(b - d)) {
			swap(a, b);
			swap(c, d);
		}
		if (a > c) 
			swap(a, c);
		if (b > d)
			swap(b, d);
		for (int j = 29;j > 0;j--) {
			A = a / d3[j] * d3[j];
			B = b / d3[j] * d3[j] + d3[j];

			if ((A / d3[j]) % 3 == 1 && (B / d3[j]) % 3 == 1) {
				if (B + d3[j] > d) {
					ans = min(
						mh(a, b, A - 1, B - 1) + mh(A - 1, B - 1, A + d3[j], B - 1) + mh(A + d3[j], B - 1, c, d),
						mh(a, b, A - 1, B + d3[j]) + mh(A - 1, B + d3[j], A + d3[j], B + d3[j]) + mh(A + d3[j], B + d3[j], c, d));
					cout << ans << endl;
					break;
				}
			}
		}
		if (ans < 0) {
			cout << mh(a, b, c, d) << endl;
		}
	}
}

