ll t3[31];
void solve() {
	t3[0] = 1;
	rep(i, 30) {
		t3[i + 1] = t3[i] * 3;
	}
		ll x[2], y[2];
		cin >> x[0] >> y[0] >> x[1] >> y[1];
		rep(i, 2) {
			x[i]--; y[i]--;
		}

		if (x[0] > x[1]) {
			swap(x[0], x[1]);
			swap(y[0], y[1]);
		}
		ll ans = abs(x[1] - x[0]) + abs(y[1] - y[0]);
		for (int t = 29; t >= 0; t--) {
			ll dx = x[0] / t3[t+1];
			ll gdx = x[1] / t3[t + 1];
			ll dy = y[0] / t3[t + 1];
			ll gdy = y[1] / t3[t + 1];

			if (dx == gdx) {
				ll rx = x[0] % t3[t + 1];
				ll grx = x[0] % t3[t + 1];
				if (t3[t] <= rx && rx < 2 * t3[t] && t3[t] <= grx && grx < 2 * t3[t]) {
					bool prob = true;
					if (dy == gdy) {
						ll ry = y[0] % t3[t + 1];
						ll gry = y[1] % t3[t + 1];
						prob = false;
						if (ry < t3[t] && gry >= 2 * t3[t])prob = true;
						if (gry < t3[t] && ry >= 2 * t3[t])prob = true;
					}
					else {
						ll yy = abs(y[1] - y[0]);
						if (yy < 2 * t3[t])prob = false;
					}
					if (prob) {
						ll ori = abs(x[1] - x[0]);
						ll nexu = rx - t3[t] + 1 + grx - t3[t] + 1;
						ll nexd = 2 * t3[t] - rx + 2 * t3[t] - grx;
						ll ad = min(nexu, nexd) - ori;
						cout << ans + ad << endl; return;
					}
				}
			}
			if (dy == gdy) {
				ll ry = y[0] % t3[t + 1];
				ll gry = y[1] % t3[t + 1];
				if (t3[t] <= ry && ry < 2 * t3[t] && t3[t] <= gry && gry < 2 * t3[t]) {
					bool prob = true;
					if (dx == gdx) {
						ll rx = x[0] % t3[t + 1];
						ll grx = x[1] % t3[t + 1];
						prob = false;
						if (rx < t3[t] && grx >= 2 * t3[t])prob = true;
						if (grx < t3[t] && rx >= 2 * t3[t])prob = true;
					}
					else {
						ll xx = abs(x[1] - x[0]);
						if (xx < 2 * t3[t])prob = false;
					}
					if (prob) {
						ll ori = abs(y[1] - y[0]);
						ll nexu = ry - t3[t] + 1 + gry - t3[t] + 1;
						ll nexd = 2 * t3[t] - ry + 2 * t3[t] - gry;
						ll ad = min(nexu, nexd) - ori;
						cout << ans + ad << endl; return;
					}
				}
			}
		}
		cout << ans << endl;
}


