vector<int> gen3(lint X)
{
    vector<int> d(32);
    int i = 0;
    while (X) {
        d[i] = X % 3;
        X /= 3;
        i++;
    }
    return d;
}

lint solve()
{
    lint x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;
    x1--, y1--, x2--, y2--;
    auto vx1 = gen3(x1);
    auto vy1 = gen3(y1);
    auto vx2 = gen3(x2);
    auto vy2 = gen3(y2);
    lint D0 = abs(x1 - x2) + abs(y1 - y2);

    bool xs = true, ys = true;
    lint additive = 0;
    lint R = 1;
    REP(d, 32) R *= 3;
    IREP(d, 32) {
        R /= 3;
        if (vx1[d] != vx2[d]) xs = false;
        if (vy1[d] != vy2[d]) ys = false;

        if (xs and !ys and vx1[d] == 1) {
            lint rrr = 1e18;
            lint z1 = x1 % R;
            lint z2 = x2 % R;
            chmin(rrr, 2 + min(z1, z2) * 2);
            chmin(rrr, 2 + min((R - 1 - z1), (R - 1 - z2)) * 2);
            chmax(additive, rrr);
        }
        else if (ys and !xs and vy1[d] == 1) {
            lint z1 = y1 % R;
            lint z2 = y2 % R;
            lint rrr = 1e18;
            chmin(rrr, 2 + min(z1, z2) * 2);
            chmin(rrr, 2 + min((R - 1 - z1), (R - 1 - z2)) * 2);
            chmax(additive, rrr);
        }
    }
    return additive + D0;
}

