ll beki3[35];

int maxBlack(ll g, ll h, ll i, ll j){
	int res=29;
	while(res>=0){
		ll hr=h%beki3[res+1], jr=j%beki3[res+1];
		if(min(hr, jr)<=beki3[res] || beki3[res]*2<max(hr, jr)){
			--res;
			continue;
		}
		if((g+beki3[res]-1)/beki3[res+1]==(i+beki3[res]-1)/beki3[res+1]){
			--res;
			continue;
		}
		break;
	}
	return res;
}

ll solve(ll g, ll h, ll i, ll j){
	int x=maxBlack(g, h, i, j), y=maxBlack(h, g, j, i);
	if(x>=0){
		ll k=(h/beki3[x+1])*beki3[x+1]+beki3[x];
		return abs(i-g)+min((h-k+1)+(j-k+1), (k+beki3[x]+1-h)+(k+beki3[x]+1-j));
	}
	if(y>=0){
		ll k=(g/beki3[x+1])*beki3[x+1]+beki3[x];
		return abs(j-h)+min((g-k+1)+(i-k+1), (k+beki3[x]+1-g)+(k+beki3[x]+1-i));
	}
	return abs(i-g)+abs(j-h);
}


