const long long MOD = 998244353;

ll check(ll scale, pll ab, pll cd, pll p) {
	ll block = 1;
	rep(i, scale - 1) block *= 3;

	pll a, c;
	a.first = (ab.first - 1) / block;
	a.second = (ab.second - 1) / block;
	c.first = (cd.first - 1) / block;
	c.second = (cd.second - 1) / block;

	if (a.first == c.first || a.second == c.second) {
		if (scale == 1 && a == c && p != pll(0, 0)) {
			return 2;
		}

		if (a.first == 1 && a.second != c.second) {
			if (!(a.second > c.second && p.second == 1) && !(a.second < c.second && p.second == -1)) {
				return min(ab.first - block + cd.first - block, (4 * block + 2) - ab.first - cd.first)-abs(ab.first-cd.first);
			}
		}
		else if (a.second == 1 && a.first != c.first) {
			if (!(a.first > c.first && p.first == 1) && !(a.first < c.first && p.first == -1)) {
				return min(ab.second - block + cd.second - block, (4 * block + 2) - ab.second - cd.second) - abs(ab.second-cd.second);
			}
		}

		if (scale == 1) return 0;
		else return check(scale - 1, pll(ab.first - a.first*block, ab.second - a.second*block),
			pll(cd.first-c.first*block, cd.second-c.second*block), pll(c.first + p.first * 3 - a.first, c.second + p.second * 3 - a.second));
	}
	else {
		return 0;
	}
}

