const int dim = loc(5)onl(30);
vi convert(ll x) {
	x--;
	vi ans;
	REP(_, dim) {
		ans.push_back(x % 3);
		x /= 3;
	}
	rans;
}
sim> ll read(c b, c e) {
	ll ans = 0, p = 1;
	for (c i = b; i != e; ++i) {
		ans += *i * p;
		p *= 3;
	}
	rans;
}
int main() {
	int Q;
	scanf("%d", &Q);
	vector <ll> p3(dim);
	p3[0] = 1;
	for (int i = 1; i < dim; ++i) p3[i] = p3[i - 1] * 3;
	REP(_, Q) {
		ll a, b, c, d;
		scanf("%lld%lld%lld%lld", &a, &b, &c, &d);
		ll ans = abs(a - c) + abs(b - d);
		vi A = convert(a), B = convert(b), C = convert(c), D = convert(d);
		debug(imie(A), imie(B), imie(C), imie(D));
		bool aceq = true, bdeq = true;
		for (int i = dim - 1; i >= 0; --i) {
			if (B[i] == 1 && D[i] == 1) {
				swap(A, B);
				swap(C, D);
				swap(a, b);
				swap(c, d);
				swap(aceq, bdeq);
			}
			if (A[i] == 1 && C[i] == 1 && aceq) {
				debug(imie(a), imie(b), imie(c), imie(d));
				ll aa = read(A.begin(), A.begin() + i);
				ll cc = read(C.begin(), C.begin() + i);
				ll p = p3[i], q = -1;
				ll inc = min(min(abs(aa - p), abs(aa - q)), min(abs(cc - p), abs(cc - q)));
				ll pow = p3[i], per = pow * 3;
				debug((imie(b) + imie(pow)) / imie(per), (imie(d) + imie(pow)) / imie(per));
				bool on_way = (b + pow) / per != (d + pow) / per;
				debug(imie(i), imie(aa), imie(cc), imie(p), imie(q), imie(inc), imie(on_way));
				if (on_way) {
					ans += 2 * inc;
					break;
				}
			}
			if (A[i] != C[i]) aceq = false;
			if (B[i] != D[i]) bdeq = false;
		}
		printf("%lld\n", ans);
	}
}

