		if(abs(x1-x2)>abs(y1-y2))swap(x1,y1),swap(x2,y2);//抓住图形具有对称性，避免出现258的情况。
		printf("%lld\n",cal(x1,y1,x2,y2,30));
	}
	return 0;
}

