using Num = vector<int>;
Num conv(LL n) {
	Num ret;
	REP(z, 0, 30) {
		ret.push_back(n % 3);
		n /= 3;
	}
	return ret;
}

LL dec(const Num& n) {
	LL sum = 0;
	LL base = 1;
	REP(z, 0, 30) {
		sum += base * n[z];
		base *= 3;
	}
	return sum;
}

LL force(Num n, int k) {
	LL p = dec(n);

	n[k] = 0;
	REP(i, 0, k) n[i] = 2;
	LL a = dec(n);

	n[k] = 2;
	REP(i, 0, k) n[i] = 0;
	LL b = dec(n);
	return min(abs(p - a), abs(p - b));
}

LL rec(const Num& a, const Num& b, const Num& c, const Num& d, int k) {
	if (k == -1) return 0;
	int p = a[k];
	int q = b[k];
	int r = c[k];
	int s = d[k];
	if (p == r && q == s) return rec(a, b, c, d, k - 1);
	if (p != r && q != s) return 0;
	if (q == s) return rec(b, a, d, c, k);
	// p == r
	if (p == 1) {
		Num dd = d;
		REP(i, 0, k) dd[i] = 0;
		Num bb = b;
		REP(i, 0, k) bb[i] = 0;
		LL diff = abs(dec(dd) - dec(bb));
		if (diff >= 2 * power(3LL, k)) {
			return min(force(a, k), force(c, k));
		}
	}
	return rec(a, b, c, d, k - 1);
}

LL sub(LL a, LL b, LL c, LL d) {
	return abs(c - a) + abs(d - b) + 2 * rec(conv(a), conv(b), conv(c), conv(d), 29);
}

int main() {
	int Q;
	cin >> Q;
	REP(i, 0, Q) {
		LL a, b, c, d;
		cin >> a >> b >> c >> d;
		--a; --b; --c; --d;
		cout << sub(a, b, c, d) << endl;
	}
	return 0;
}

