ll solve_eq(ll p,ll q,ll a,ll b){
    ll cur = 0, cur2 = 0, base = 1, ans = abs(a-b), ret = abs(a-b);

    while(p || q){
        if(p%3 == 1 && p == q){
            for(ll x=a;x<=b;x++){
                ll aa = x, ab = p;
                while(aa || ab){
                    if(aa%3 == 1 && ab%3 == 1){
                        chmax(ret, ans + min(cur+1+cur2+1, base+base-cur2-cur));
