int64_t len(int64_t a,int64_t b,int64_t c,int64_t d,int64_t p){
  if(a/p!=c/p&&b/p!=d/p)
    return abs(c-a)+abs(d-b);
  if(a/p==c/p&&b/p==d/p)
    return len(a%p,b%p,c%p,d%p,p/3);
  int64_t x;
  if(a/p==c/p)
    x=(a+c)/2;
  if(b/p==d/p)
    x=(b+d)/2;
  vector<int> t;
  while(x>0){
    t.push_back(x%3);
    x/=3;
  }
  int64_t l=0;
  int64_t g=0;
  bool f=0;
  for(int i=(int)t.size()-1;i>=0;i--){
    l*=3;
    g*=3;
    if(f){
      l+=2;
      continue;
    }
    if(t.at(i)==1){
      g+=2;
      f=1;
      continue;
    }
    l+=t.at(i);
    g+=t.at(i);
  }
  if(a/p==c/p)
    return min(abs(l-a)+abs(l-c)+abs(d-b),abs(g-a)+abs(g-c)+abs(d-b));
  if(b/p==d/p)
    return min(abs(c-a)+abs(l-b)+abs(l-d),abs(c-a)+abs(g-b)+abs(g-d));
}
