ll distance(ll x1,ll y1,ll x2,ll y2,ll level=30){
  if(level==0){
    return abs(y1-y2);
  }
  ll size=1;
  REP(level){
    size*=3;
  }
  ll sizes=size/3;
  pll f,s;
  f.first=x1/sizes;
  f.second=y1/sizes;
  s.first=x2/sizes;
  s.second=y2/sizes;
  if(f.first==s.first&&f.second==s.second){
    return distance(x1%sizes,y1%sizes,x2%sizes,y2%sizes,level-1);
  }
  if(f.first!=s.first&&f.second!=s.second){
    return abs(x1-x2)+abs(y1-y2);
  }
  if(f.second==s.second){
    swap(f.first,f.second);
    swap(s.first,s.second);
    swap(x1,y1);
    swap(x2,y2);
  }
  if(sizes<=x1&&x1<2*sizes){
    return abs(y1-y2)+min(abs(sizes-1-x1)+abs(sizes-1-x2),abs(2*sizes-x1)+abs(2*sizes-x2));
  }
  return distance(x1%sizes,y1,x2%sizes,y2,level-1);
}
