#define _LL long long

void calc3(_LL a, int *p)
{
    for(int i = 0; i < 30; i++)
    {
        p[i] = a % 3;
        a /= 3;
    }
}

int maxborder2(int *s, int *b, int i)
{
    if( i < 0 ) return -1;
    if( s[i] == 0 || b[i] == 2 ) return i;
    if( s[i] == 1 || b[i] == 1 ) return i - 1;
    return maxborder2(s, b, i - 1);
}

int maxborder(int *x1, int *x2)
{
    for( int i = 29; i >= 0; i-- )
    {
        if( x1[i] != x2[i] )
        {
            if( abs(x2[i] - x1[i]) == 2 ) return i;
            if( x1[i] > x2[i] ) return  maxborder2(x2, x1, i - 1);
            return  maxborder2(x1, x2, i - 1);
        }
    }
    return -1;
}

_LL get3(int *a, int index)
{
    _LL ans = 0;
    for( int i = 0; i < index; i++ ) ans = ans * 3 + a[i];
    return ans;
}

_LL getpow3(int index)
{
    _LL ans = 1;
    for( int i = 0; i < index; i++ ) ans *= 3;
    return ans;
}

_LL getBestPath(int *y1, int *y2, int maxb, int xdist, int ydist)
{
//    cout << maxb << "," << xdist << "," << ydist << endl;
    for( int i = 29; i >= 0; i-- )
    {
//        cout << i << "," << y1[i] << "," << y2[i] << endl;
        if( y1[i] != y2[i] ) return xdist + ydist;
        if( i <= maxb && y1[i] == 1)
        {
            _LL pow3 = getpow3(i);
            _LL ydiff = get3(y1, i) + get3(y2, i);
//            cout << "! " << i << "," << pow3 << "," << ydiff << endl;
            return xdist + min( ydiff + 2, pow3 * 2 - ydiff );
        }
    }
    return xdist + ydist;
}

