        }
        _LL ans = getBestPath(p[1], p[3], maxborder(p[0], p[2]), abs(a[2] - a[0]), abs(a[3] - a[1]) );
        ans = max(ans, getBestPath(p[0], p[2], maxborder(p[1], p[3]), abs(a[3] - a[1]), abs(a[2] - a[0]) ));
