        Int p = pow(3, k);
        Int r1 = x1 / p, c1 = y1 / p;
        Int r2 = x2 / p, c2 = y2 / p;

        if (r1 == r2 && c1 == c2) {
            Int ret = rec(k - 1, x1 % p, y1 % p, x2 % p, y2 % p);
            return ret;
        } else if (r1 == r2 || c1 == c2) {
            Int ret = INFl;
            Int R1 = x1 / pow(3, k - 1);
            Int R2 = x2 / pow(3, k - 1);
            Int C1 = y1 / pow(3, k - 1);
            Int C2 = y2 / pow(3, k - 1);

            if ((r1 == 1 && r2 == 1) || (c1 == 1 && c2 == 1)) {
                vector<Int> txs = {p - 1, 2 * p}, tys = {p - 1, 2 * p};
                for (auto tx : txs) {
                    for (auto ty : tys) {
                        Int tmp = dist(x1, y1, tx, ty) + dist(tx, ty, x2, y2);
