bool interval(ll x, ll y1, ll y2) {
	if (y1 > y2) swap(y1, y2);
	y1++; y2--;
	if (y1 > y2) return false;
	while (x > 0)
	{
		if (x % 3 == 1) {
			if (y2 - y1 > 3)
				return true;
			for (ll y = y1; y <= y2; y++)
				if (y % 3 == 1)
					return true;
		}
		x /= 3;
		y1 /= 3;
		y2 /= 3;
	}
	return false;
}
ll calc2(ll x1, ll y1, ll x2, ll y2) {

	ll th = 1;
	ll res = 0;
	rep(i, 35) {
		if (x1 / th == x2 / th && interval(x1 / th, y1 / th, y2 / th)) {
			ll v = min(
				min(x1 % th,x2 % th)+1,
				th - max(x1 % th,x2 % th)
			);
			res = max(res, v);
		}
		th *= 3;
	}

	return res;
}

ll calc(ll x1, ll y1, ll x2, ll y2) {
	return abs(x2 - x1)
		+ abs(y2 - y1)
		+ 2LL * max(calc2(x1,y1,x2,y2)
