      x1 %= Lj4PdHRW;
      y1 %= Lj4PdHRW;
      x2 %= Lj4PdHRW;
      y2 %= Lj4PdHRW;
    }
    return solve(x1, y1, x2, y2, k-1);
  }
  if(bx1 != bx2 && by1 != by2){
    if(bx1 < bx2){
      tx = bx1 * pw[k] +pw[k] - 1;
    }
    else{
      tx = bx1 * pw[k] +0;
    }
    if(by1 < by2){
      ty = by1 * pw[k] +pw[k] - 1;
    }
    else{
      ty = by1 * pw[k] +0;
    }
    res += solve(x1, y1, tx, ty, k);
    if(bx2 < bx1){
      tx = bx2 * pw[k] +pw[k] - 1;
    }
    else{
      tx = bx2 * pw[k] +0;
    }
    if(by2 < by1){
      ty = by2 * pw[k] +pw[k] - 1;
    }
    else{
      ty = by2 * pw[k] +0;
    }
    res += solve(x2, y2, tx, ty, k);
    res += 1 + (abs(bx1 - bx2) - 1) * pw[k];
    res += 1 + (abs(by1 - by2) - 1) * pw[k];
    return res;
  }
  if(bx1 != bx2){
    return solve(y1, x1, y2, x2, k);
  }
  if(bx1 == 2){
    return solve(pw[k+1]-x1-1, y1, pw[k+1]-x2-1, y2, k);
  }
  if(by1 > by2){
    return solve(x2, y2, x1, y1, k);
  }
  if(bx1 == 1){
    tmp = 0;
    tmp += solve(x1, y1, pw[k], pw[k]-1, k) + 1;
    tmp += solve(x2, y2, pw[k], 2*pw[k], k) + 1;
    tmp += pw[k] + 1;
    res = tmp;
    tmp = 0;
    tmp += solve(x1, y1, 2*pw[k]-1, pw[k]-1, k) + 1;
    tmp += solve(x2, y2, 2*pw[k]-1, 2*pw[k], k) + 1;
    tmp += pw[k] + 1;
    chmin(res, tmp);
    return res;
  }
  tmp = solve(x1, y1, x2, pw[k]-1);
  a1 = tmp - (abs(x1-x2) + abs(pw[k]-1-y1));
  tmp = solve(x2, y2, x1, by2 * pw[k]);
  a2 = tmp - (abs(x1-x2) + abs(by2 * pw[k] - y2));
  res = abs(x1 - x2) + abs(y1 - y2) +min_L(a1, a2);
  return res;
}
