    const auto& calc = [](auto a, auto b, auto c, auto d){
        auto u{b}, p{M};
        while(p /= 3)if((a / p + (4 - a / p % 3) % 3) * p <= c)if(b / p % 3 == 1){
            u = b / (3 * p) * 3 * p + 2 * p;
            return c - a + min(u - b + max(u, d) - min(u, d), b + d - 2 * (b / (3 * p) * 3 * p + p - 1));
        }
