            if (A == C && B != D && (((a % (3 * sz)) / sz) == 1)) {
                //pd(a, b, c, d, sz);
                ll betw = count(max(B, D)) - count(min(B, D));
                if (betw > 0) {
                    //pd(a, b, c, d, sz);

                    ll ar = A % sz, cr = C % sz;
                    add = min(ar + cr, 2 * sz - ar - cr);
                }
            }
            if (A != C && B == D && (((b % (3 * sz)) / sz) == 1)) {
                //pd(a, b, c, d, sz);
                ll betw = count(max(A, C)) - count(min(A, C));
                if (betw > 0) {
                    //pd(a, b, c, d, sz);

                    ll br = B % sz, dr = D % sz;
                    add = min(br + dr, 2 * sz - br - dr);
                }
            }
            sz *= 3;
        }

        ps(straight + add);
    }

    // did you check N=1? did you mix up N,M?
    // check your "infinity" and "null" values against the bounds
    return 0;
