const int MAXD = 31;
const long long INF = 1000000000LL * 1000000000LL;

inline long long getDist(long long div, long long a, long long b, long long da, long long db) {
    long long blk1 = a / div;
    long long blk2 = b / div;

    long long dblk1 = da / div;
    long long dblk2 = db / div;
    bool cross = false;

    if (dblk1 - dblk2 >= 3) {
        cross = true;
    } else {
        for (long long y = dblk1; y <= dblk2; ++y) {
            if (y % 3 == 1) {
                cross = true;
                break;
            }
        }
    }

    if (blk1 == blk2 && blk1%3 == 1 && cross) {
        long long from = blk1 * div;
        long long to = blk1 * div + div - 1;
        return min(abs(a-from)+abs(b-from), abs(b-to)+abs(b-to)) + 2;
    }

    return abs(a-b);
}

long long solve(long long a, long long b, long long c, long long d) {
    long long dx = 0;
    long long dy = 0;
    long long div = 3;

    for (int i = 0; i < MAXD; ++i) {
        dx = max(dx, getDist(div, a, c, b, d));
        dy = max(dy, getDist(div, b, d, a, c));

        div *= 3;
    }

    return dx + dy;
}

