    ll ai, aj, bi, bj;
    cin >> ai >> aj >> bi >> bj;
    --ai; --aj; --bi; --bj; // 0-indexed
    ll ans = 0;
    ans = max(ans, solve(ai, aj, bi, bj)); // horizontal
    ans = max(ans, solve(aj, ai, bj, bi)); // vertical
    cout << ans << endl;
  }
}

