class Solve {
public:
    Int pow(Int n, Int p) {
        Int ret = 1;
        while (p > 0) {
            ret *= n;
            p--;
        }
        return ret;
    }

    Int dist(Int x1, Int y1, Int x2, Int y2) {
        return abs(x1 - x2) + abs(y1 - y2);
    }

    Int rec(Int k, Int x1, Int y1, Int x2, Int y2) {
        Int p = pow(3, k - 1);
        Int r1 = x1 / p, c1 = y1 / p;
        Int r2 = x2 / p, c2 = y2 / p;

        if (r1 == r2 && c1 == c2) {
            Int ret = rec(k - 1, x1 % p, y1 % p, x2 % p, y2 % p);
            return ret;
        } else if (r1 == r2 || c1 == c2) {
            Int ret = INFl;
            Int R1 = x1 / pow(3, k - 2);
            Int R2 = x2 / pow(3, k - 2);
            Int C1 = y1 / pow(3, k - 2);
            Int C2 = y2 / pow(3, k - 2);

            if ((r1 == 1 && r2 == 1) || (c1 == 1 && c2 == 1)) {
                vector<Int> txs = {p - 1, 2 * p}, tys = {p - 1, 2 * p};
                for (auto tx : txs) {
                    for (auto ty : tys) {
                        Int tmp = dist(x1, y1, tx, ty) + dist(tx, ty, x2, y2);
                        chmin(ret, tmp);
                    }
                }
            } else if ((R1 == 1 && R2 == 1) || (C1 == 1 && C2 == 1) || (R1 == 7 && R2 == 7) || (C1 == 7 && C2 == 7)) {
                if (C1 != C2) {
                    swap(x1, y1);
                    swap(x2, y2);
                    swap(R1, C1);
                    swap(R2, C2);
                }

                if (abs(R2 - R1) == 1) {
                    ret = dist(x1, y1, x2, y2);
                }

                vector<Int> txs = {x1};
                vector<Int> tys = {C1 * pow(3, k - 2) - 1, (C1 + 1) * pow(3, k - 2)};
                for (auto tx : txs) {
                    for (auto ty : tys) {
                        Int tmp = dist(x1, y1, tx, ty) + dist(tx, ty, x2, y2);
                        chmin(ret, tmp);
                    }
                }

            } else {
                ret = dist(x1, y1, x2, y2);
            }

            return ret;
        } else {
            Int ret = dist(x1, y1, x2, y2);
            return ret;
        }
    }

    void solve() {
        Int Q;
        cin >> Q;
        while (Q--) {
            Int a, b, c, d;
            cin >> a >> b >> c >> d;
            a--, b--, c--, d--;
            Int ans = rec(30, a, b, c, d);
//            Int ans = rec(3, a, b, c, d);
            cout << ans << endl;
        }
    }
};


