ll solve(ll xi, ll yi, ll xj, ll yj) {
    if (xi>xj) {
        swap(xi, xj);
        swap(yi, yj);
    }
    ll s = 1;
    rep(i, 30) s *= 3;
    ll dist = abs(xi-xj) + abs(yi-yj);
    ll res = dist;
    while(1) {
        s /= 3;
        if (s==0) {
            break;
        }
        ll nxi = xi/s;
        ll nxj = xj/s;
        if (nxi!=nxj) {
            break;
        }
        ll nyi = yi/s;
        ll nyj = yj/s;
        if (nyi!=nyj && nxi==1 && nxj==1) {
            ll loss = 2 * (min(yi, yj) - s + 1);
            loss = min(loss, 2*(2*s-max(yi, yj)));
            res = dist + loss;
            break;
        }
        yi %= s;
        yj %= s;
    }
    return res;
}

