bool judgex(ll xx,ll yy1,ll yy2)
{
    for(int i=30;i>=1;i--)
    {
        ll c=p[i]/2+1,d=(p[i-1]-1)/2;
        ll x=xx%p[i],y1=yy1%p[i],y2=yy2%p[i];
        if(x==0) x=p[i];
        if(y1==0) y1=p[i];
        if(y2==0) y2=p[i];
        if((x>=c-d&&x<=c||x>=c&&x<=c+d)&&!(y1>c+d&&y2>c+d||y1<c-d&&y2<c-d)) return false;
    }
    return true;
}
bool judgey(ll yy,ll xx1,ll xx2)
{
    for(int i=30;i>=1;i--)
    {
        ll c=p[i]/2+1,d=(p[i-1]-1)/2;
        ll y=yy%p[i],x1=xx1%p[i],x2=xx2%p[i];
        if(y==0) y=p[i];
        if(x1==0) x1=p[i];
        if(x2==0) x2=p[i];
        if((y>=c-d&&y<=c||y>=c&&y<=c+d)&&!(x1>c+d&&x2>c+d||x1<c-d&&x2<c-d)) return false;
    }
    return true;
}
bool judge(ll x1,ll y1,ll x2,ll y2)
{
    if(x1==x2&&y1==y2) return true;
    if(x1==x2) return judgex(x1,y1,y2);
    if(y1==y2) return judgey(y1,x1,x2);
    return false;
}
ll mp[N][N];
int f[N][N];
ll getdis(ll x1,ll y1,ll x2,ll y2)
{
    if(judge(x1,y1,x2,y2)) return dis(x1,y1,x2,y2);
    return mp[N-1][N-1];
}
ll pre(ll x)
{
    ll ans=1;
    for(int i=29;i>=0;i--)
        if(ans+2*p[i]<=x) ans+=2*p[i];
    return ans;
}
ll bk(ll x)
{
    ll l=x,r=p[30],ans=-1;
    while(l<=r)
    {
        ll m=l+r>>1,k=pre(m);
        if(k>=x) ans=k,r=m-1;
        else l=m+1;
    }
    assert(ans!=-1);
    return ans;
}
