LL check(LL x,LL y,LL x2,LL y2,LL m){
	m/=3;
	if(abs(x2-x)<abs(y2-y))swap(x,y),swap(x2,y2);
	if(x/m==x2/m && y/m==y2/m){
		return check(x%m,x2%m,y%m,y2%m,m);
	}
	if(y/m!=1 || y2/m!=1){
		return abs(x2-x)+abs(y2-y);
	}
	LL s=y%m+y2%m+2;
	LL s2=2*m+2-s;
	if(s>s2)s=s2;
	return s+abs(y-y2);
}

