ll pow3[33];
ll work(ll a,ll b,ll c,ll d,int k)
{
    if(k==0)return 0;
    int sx = a / pow3[k-1];
    int sy = b / pow3[k-1];
    int tx = c / pow3[k-1];
    int ty = d / pow3[k-1];
    if(sx != tx && sy != ty)
    {
        return abs(a-c)+abs(b-d);
    }
    if(sx==tx && sy==ty)
    {
        return work(a%pow3[k-1],b%pow3[k-1],c%pow3[k-1],d%pow3[k-1],k-1);
    }
    if(sx == 1 && tx == 1)
    {
        return abs(b-d) + min(pow3[k-1]*2-a+pow3[k-1]*2-c, a - pow3[k-1] + 1 + c - pow3[k-1] + 1);
    }
    if(sy == 1 && ty == 1)
    {
        return abs(a-c) + min(pow3[k-1]*2-b+pow3[k-1]*2-d, b - pow3[k-1] + 1 + d - pow3[k-1] + 1);
    }
    return pow3[k-1]*2 + work(a%pow3[k-1],b%pow3[k-1],c%pow3[k-1],d%pow3[k-1],k-1);
}
