LL getDis(LL a, LL b, LL sz) {
	LL down = (a + b + 2);
	LL up = (sz - a) + (sz - b);
	return min(up, down) - abs(a - b);
}
LL getX(vector<int> x, int k) {
	LL res = 0;
	for (int i = k - 1; i >= 0; --i) {
		res = res * (LL)(3) + (LL)(x[i]);
	}
	return res;
}
LL getM3(int k) {
	LL res = 1;
	for (int i = 0; i < k; ++i) {
		res *= (LL)(3);
	}
	return res;
}

vector<int> cutV(vector<int> &a, int x) {
	vector<int> res;
	res.clear();
	for (int i = 0; i < x; ++i) {
		res.push_back(a[i]);
	}
	return res;
}
LL shortestNeighbor(vector<int> x1, vector<int> y1, vector<int> x2, vector<int> y2, bool sameX) {
	int n = x1.size();
	LL res = 0;
	LL one = (LL)(1);
	for (int i = n - 1; i >= 0; --i) {
		if (!sameX) {
			if (y1[i] == 1 && y2[i] == 1) {
				LL yy1 = getX(y1, i);
				LL yy2 = getX(y2, i);
				LL sz = getM3(i);
				return getDis(yy1, yy2, sz);
			}
			else if (y1[i] != y2[i]) {
				return res;
			}
		}
		else {
			if (x1[i] == 1 && x2[i] == 1) {
				LL xx1 = getX(x1, i);
				LL xx2 = getX(x2, i);
				LL sz = getM3(i);
				return getDis(xx1, xx2, sz);
			}
			else if (x1[i] != x2[i]) {
				return res;
			}
		}
	}
	return res;
}

LL getPath(LL x1, LL y1, LL x2, LL y2) {
	vector<int> xb1 = getBit(x1), xb2 = getBit(x2);
	vector<int> yb1 = getBit(y1), yb2 = getBit(y2);

	LL res = abs(x1 - x2) + abs(y1 - y2);
	for (int i = bitn - 1; i >= 0; --i) {
