		}
				if (xx1 == 1 && yy1 == 2) {
			corner1 = false;
		}


		//LL zero = (LL)(0), one = (LL)(1), two = (LL)(2);
		if (corner1) {
			if (xx2 != xx1 && yy2 != yy1) {
				return res;
			}
			else {
				// cout << "here" << endl;
				return res + shortestNeighbor(cutV(xb1, i), cutV(yb1, i), cutV(xb2, i), cutV(yb2, i), (xx1 == xx2));
			}
		}
		else {
			int diff = abs(xx1 - xx2) + abs(yy1 - yy2);
			if (diff == 1) {
				return res + shortestNeighbor(cutV(xb1, i), cutV(yb1, i), cutV(xb2, i), cutV(yb2, i), (xx1 == xx2));
			}
			else {
				// return res;
				if (xx2 == xx1 && yy2 + yy1 == 2) {
					LL sz = getM3(i);
					LL xz1 = getX(xb1, i), xz2 = getX(xb2, i);
