// 片道分
pll dfs(ll x,ll f) {

	ll sum = 0;
	vector<ll> a;
	vector<ll> b;
	d[x] = vector<pll>(es[x].size());

	for (auto v : es[x]) {
		if (v.first == f)continue;

		auto r = dfs(v.first,x);
		d[x][es[v.first][v.second].second] = make_pair(r.first, r.second);
		a.push_back(r.first);
		b.push_back(r.second);
		sum += r.second;
	}

	ll r1 = 1;
	ll b1 = 1;

	rep(i,a.size())
	{
		b1 *= COM(sum, b[i]);
		b1 %= INF;
		b1 *= a[i];
		b1 %= INF;
		r1 += b[i];
		sum -= b[i];
	}
	return make_pair(b1, r1);
}
// もう片道分
void dfs2(ll x, ll f,ll cn,ll v) {

	if (f != -1) {
		d[x][f] = (make_pair(v,cn));
	}
	int size = d[x].size();
	vector<ll> lefs(size +1,0);
	vector<ll> rifs(size + 1, 0);
	vector<ll> lev(size + 1, 0);
	vector<ll> riv(size + 1, 0);
	for (ll i = 0; i < size; i++)
	{
		lev[i] = 1;
		lefs[i] = 0;
		if (i > 0) {
			lefs[i] = lefs[i - 1];
			lev[i] = lev[i - 1];
		}
		lefs[i] += d[x][i].second;
		lev[i] *= d[x][i].first;

		lev[i] %= INF;
	}
	riv[size] = 1;
	for (ll i = size - 1; i >= 0; i--)
	{
		riv[i] = 1;
		rifs[i] = 0;
		if (i < size - 1) {
			rifs[i] = rifs[i + 1];
			riv[i] = riv[i + 1];
		}
		rifs[i] += d[x][i].second;
		riv[i] *= d[x][i].first;
		riv[i] %= INF;

		if (i == f) continue;
		ll c = 1 + lefs[size - 1] - d[x][i].second;
		ll t = (i > 0) ? lev[i - 1] : 1;
		t *= riv[i + 1];
		t %= INF;
		t *= COM(lefs[size - 1], d[x][i].second);
		t %= INF;
		dfs2(es[x][i].first, es[x][i].second,
			c, t);
	}
	ll res = lev[size- 1];
	ll sum = lefs[size - 1];
	rep(i, size) {
		res *= COM(sum, d[x][i].second);

		sum -= d[x][i].second;
	}
	result[x] = res;
}
ll interval(ll x, ll y1, ll y2) {
	if (y1 > y2)swap(y1, y2);
	y1++; y2--;
	if (!(y1 <= y2))return false;

	while (x > 0)
	{
		if (x % 3 == 1) {
			if (y2 - y1 > 3) return true;
			for (ll y = y1; y <= y2; y++)
			{
				if (y % 3 == 1) return true;
			}
		}
		x /= 3;
		y1 /= 3;
		y2 /= 3;
	}
	return false;
}
ll cal1(ll x1, ll y1, ll x2, ll y2) {

	ll p = 1;
	ll res = 0;
	rep(i, 35) {
		// x1,x2が同じエリアにあるかどうか
		// y1,y2の間に黒エリアがあるかどうか
		if (x1 / p == x2 / p && interval(x1 / p, y1 / p, y2 / p)) {
			ll xp1 = x1 % p;
			ll xp2 = x2 % p;
			res = max(res, min(min(xp1,xp2) + 1,min(p-xp1,p-xp2)));
		}
		p *= 3;
	}
	return res;
}
