		res += x % 10;
		x /= 10;
	}
	return res;
}
bool inter(ll x, ll y1, ll y2) {

	if (y1 > y2) swap(y1, y2);
	y1++; y2--;
	if (y1 > y2) return false;
	while (x > 0)
	{
		if (x % 3 == 1) {
			if (y2 - y1 > 3) return true;
			for (ll y = y1; y <= y2; y++)if (y % 3 == 1)return true;
		}

		x /= 3;
		y1 /= 3;
		y2 /= 3;
	}
}
ll discal(ll x1, ll y1, ll x2, ll y2) {

	ll th = 1;
	ll r = 0;
	rep(i, 35) {

		if (x1 / th == x2 / th && inter(x1 / th, y1 / th, y2 / th)) {
			ll v = min(min(x1 % th, x2 % th) + 1, th - max(x1 % th, x2 % th));
			r = max(r, v);
		}
		th *= 3;
	}

	return r;
}
ll dist(ll x1, ll y1, ll x2, ll y2) {
	return abs(x1 - x2) + abs(y1 - y2) +
		2LL * max(discal(x1, y1, x2, y2), discal(y1, x1, y2, x2));
}
