        if (min(abs(a-c),abs(b-d)) >= h+1) break; // 両方の差が大きければ避けられる、以降のより小さいやつも同様
        // cout <<"here2 " <<endl;
        if (left + h <= min(a,c) && max(a,c) < left + 2*h && up + h <= min(b,d) && max(b,d) < up + 2*h){
          // 両方小さかったらおかしいよね
        }else if (left + h <= min(a,c) && max(a,c) < left + 2*h){
          // 縦方向に引っかかる
          // cout <<"ha" <<endl;
          res += 2 * min(min(a,c) - (left+h-1), left + 2*h - max(a,c));
          break;
        }else if (up + h <= min(b,d) && max(b,d) < up + 2*h){
          // cout <<"hey" <<endl;
          res += 2 * min(min(b,d)- (up+h-1), up + 2*h - max(b,d));
          break;
        }else{
          // 引っかからない
          if (min(a,c) >= left + 2*h) left += 2*h;
          if (min(b,d) >= up + 2*h) up += 2*h; 
        }
        // cout <<"restest = " <<res <<endl;
      }
      cout <<res <<endl;
    }
  }
}

