ll pw3[31];
bool in(ll x , int bit)
{
	return (x / pw3[bit]) % 3 == 1;
}
ll f(ll x , ll bit)
{
	return (x + pw3[bit]) / pw3[bit + 1];

}
ll dist(ll a , ll b , ll c , ll d)
{
	return abs(a - c) + abs(b - d);
}
ll solve(ll a, ll b, ll c, ll d)
{
	for(int bit = 29; bit >= 0; bit--)
	{
		if(in(a , bit) && in(c , bit) && (a / pw3[bit]) == (c / pw3[bit]) && f(b , bit) != f(d, bit))
		{
			if(b > d)
				swap(b , d);
			return min( dist(a , b , (a / pw3[bit]) * pw3[bit] + pw3[bit] , (b / pw3[bit]) * pw3[bit] + pw3[bit] - 1) + 
					dist(c , d , (a / pw3[bit]) * pw3[bit] + pw3[bit] , (b / pw3[bit]) * pw3[bit] + pw3[bit] - 1) ,
					dist(a , b , (a / pw3[bit]) * pw3[bit] - 1, (b / pw3[bit]) * pw3[bit] + pw3[bit] - 1) + 
					dist(c , d , (a / pw3[bit]) * pw3[bit] - 1 , (b / pw3[bit]) * pw3[bit] + pw3[bit] - 1));
		}
	}
	return -1;
}
