int pow3[40] = {1};

inline int block(int k,int a){
	return a / pow3[k - 1];
}

int calc(int k,int a,int b,int c,int d){
	if(k == 1) return abs(a - b) + abs(c - d);
	int dx = abs(block(k,a) - block(k,c));
	int dy = abs(block(k,b) - block(k,d));
	if(dx == 0 && dy == 0){
		return calc(k - 1,a % pow3[k - 1],b % pow3[k - 1],c % pow3[k - 1],d % pow3[k - 1]);
	}else if(dx == 0 || dy == 0){
		if(dy == 0){
			swap(a,b); swap(c,d);
		}
		while(k >= 1){
			//cout << k << " " << P(a,b) << P(c,d) << endl;
			if(block(k,a) == 1 && block(k,c) == 1){
				if(abs(b - d) == 1) return 1;
				int d1 = pow3[k - 1] * 4 - a - c;
				int d2 = a + c - (pow3[k - 1] - 1) * 2;
				return min(d1,d2) + abs(b - d);
			}else if(block(k,a) != block(k,c)) return abs(a - c) + abs(b - d);
			k--;
			a %= pow3[k];
			c %= pow3[k];
		}
		if(k == 0) return abs(b - d);
	}else{
		return abs(a - b) + abs(c - d);
	}
}

