/* 累乗; 置く場所がないのでここに置いておきます O(logN) */
template <class T>
T power(T base, uint64_t exp) {
	T product = T(1);
	while (exp > 0) {
		if (exp & 1) {
			product *= base;
		}
		base *= base;
		exp >>= 1;
	}
	return product;
}

