        return abs(b-d)+min(x1+1+1+x2,(po[k]-(x1+1))+1+1+(po[k]-(x2+1)));
      }
      if(B==D and B%3==1 and abs(A-C)>=2){
        Int y1=b%po[k];
        Int y2=d%po[k];
        return abs(a-c)+min(y1+1+1+y2,(po[k]-(y1+1))+1+1+(po[k]-(y2+1)));
      }
    }
    return abs(a-c)+abs(b-d);
  };

