vector<int> getBit(LL x, int bitn = 30) {
	vector<int> res;
	res.clear();
	while (x > (LL)(0)) {
		res.push_back((int)(x % (LL)(3)));
		x /= (LL)(3);
	}
	while (res.size() < bitn) {
		res.push_back(0);
	}
	return res;
}
int bitn = 30;

LL getDis(LL a, LL b, LL sz) {
	LL down = (a + b + 2);
	LL up = (sz - a) + (sz - b);
	return min(up, down) - abs(a - b);
}
LL getX(vector<int> x, int k) {
	LL res = 0;
	for (int i = k - 1; i >= 0; --i) {
		res = res * (LL)(3) + (LL)(x[i]);
	}
	return res;
}
LL getM3(int k) {
	LL res = 1;
	for (int i = 0; i < k; ++i) {
		res *= (LL)(3);
	}
	return res;
}

vector<int> cutV(vector<int> &a, int x) {
	vector<int> res;
	res.clear();
	for (int i = 0; i < x; ++i) {
		res.push_back(a[i]);
	}
	return res;
}
