Tri pow(Tri a, ll b) {
  Tri ret(1);
  while(b--) ret *= a;
  return ret;
}

Tri min(Tri a, Tri b) {
  return a < b ? a : b;
}

Tri max(Tri a, Tri b) {
  return a < b ? b : a;
}

