      if((b[i] == d[i] && abs(d-b) >= pow(Tri(3), i))
      || (min(b, d)[i] == 0 && max(b, d)[i] == 2)
      || (min(b, d)[i] == 2 && max(b, d)[i] == 0 && abs(d-b) >= Tri(2)*pow(Tri(3), i))){
