void solve() {
    ll a[4];
    for(int i = 0; i < 4; i++) {
        cin >> a[i];
        a[i]--;
        v[i] = f(a[i]);
    }
    bool Hsame = true;
    bool Wsame = true;
    ll ans = abs(a[0] - a[2]) + abs(a[1] - a[3]);
    for(ll idx = 29; idx >= 0; idx--) {
        if(v[0][idx] != v[2][idx]) Hsame = false;
        if(v[1][idx] != v[3][idx]) Wsame = false;
        if(!Hsame and !Wsame) {
            cout << ans << endl;
            return;
        }
        if(Hsame and Wsame) continue;
        //cerr << idx << " " << Hsame << " " << Wsame << endl;
        if(Hsame) {
            ll tmp = 1e18;
            //cerr << v[0][idx-1] << endl;
            if(v[0][idx] != 1) tmp = 0;
            ll bone = a[0] % beki[idx];
            ll btwo = a[2] % beki[idx];
            chmin(tmp, (bone + 1) * 2);
            chmin(tmp, (btwo + 1) * 2);
            chmin(tmp, (beki[idx] - bone) * 2);
            chmin(tmp, (beki[idx] - btwo) * 2);
            cout << ans + tmp << endl;
            return;
        }
        if(Wsame) {
            ll tmp = 1e18;
            if(v[1][idx] != 1) tmp = 0;
            ll bone = a[1] % beki[idx];
            ll btwo = a[3] % beki[idx];
            chmin(tmp, (bone + 1) * 2);
            chmin(tmp, (btwo + 1) * 2);
            chmin(tmp, (beki[idx] - bone) * 2);
            chmin(tmp, (beki[idx] - btwo) * 2);
            cout << ans + tmp << endl;
            return;
        }
    }
    cout << ans << endl;
}

