long long solve(long long ai, long long aj, long long bi, long long bj)
{
    long long size = 1;
    for (int i = 0; i < 30; ++i)
    {
        size *= 3;
    }

    long long dist = std::abs(ai - bi) + std::abs(aj - bj);
    while (size > 1)
    {
        size /= 3;
        long long nai = ai / size, naj = aj / size, nbi = bi / size, nbj = bj / size;
        if (nai != nbi)
        {
            break;
        }
        if (std::abs(naj - nbj) >= 2)
        {
            if (nai % 3 == 1)
            {
                long long up = aj - naj * size + 1 + bj - nbj * size + 1;
                long long bottom = (naj + 1) * size - aj + (nbj + 1) * size - bj;
                dist = std::abs(aj - bj) + std::min(up, bottom);
                break;
            }
        }
    }

    return dist;
}

