        for (int i = L-1; i >= 0; x0%=pw[i], x1%=pw[i], y0%=pw[i], y1%=pw[i], i--) {
            int b0 = (x0/pw[i]);
            int b1 = (x1/pw[i]);
            int c0 = (y0/pw[i]);
            int c1 = (y1/pw[i]);
            if (b0 != b1 && c0 != c1) return 0ll;
            if (b0 == b1 && c0 == c1) continue;
            if (c0 == c1) {
                swap(x0,y0);
                swap(x1,y1);
            }
            if (y0 > y1) {
                swap(y0,y1);
            }
            bool exist = (c0==0 && c1==2);
            for (; i >= 0; x0%=pw[i], x1%=pw[i], i--) {
                int b0 = (x0 / pw[i])%3;
                int b1 = (x1 / pw[i])%3;
                if (b0 != b1) return 0ll;
                if (b0 != 1 || !exist) {
                    y0%=pw[i], y1%=pw[i];
