                        exist = exist || !(c0==2&&c1==0);
                    }
                    continue;
                }
                if (x0 > x1) swap(x0,x1);
                return 2ll * min(2ll*pw[i] - x1, x0 - (pw[i]-1));
            }
            return 0ll;
        }
        return 0ll;
    };

    auto h = [&](ll x0, ll x1, ll y0, ll y1){
        if (x0>x1)swap(x0,x1);
        if (y0>y1)swap(y0,y1);
        if (x1-x0 > y1-y0) {
            swap(x0,y0);
            swap(x1,y1);
        }
        for (int i = L-1; i >= 0; i--) {
            if (x0/pw[i] == x1/pw[i] && (x0/pw[i])%3 == 1) {
                if (y1/pw[i] - y0/pw[i] > 1) {
                    return 2ll*min(x0 - x0/pw[i]*pw[i] + 1, (x0/pw[i] + 1)*pw[i] - x1);
                }
            }
        }
        return 0ll;
    };

