        swap(ai, bi);
        swap(aj, bj);
    }
    ll s = 1;
    rep(i, 30) s *= 3;
    ll dist = abs(ai-bi) + abs(aj-bj);
    ll res = dist;
    while(1) {
        s /= 3;
        if (s==0) {
            break;
        }
        ll nai = ai/s;
        ll nbi = bi/s;
        if (nai!=nbi) {
            break;
