void nor(ll &h1,ll &w1,ll &h2,ll &w2,ll level){
    if(h1>h2){
        h1=rui[level]-1-h1;
        h2=rui[level]-1-h2;
    }
    if(w1>w2){
        w1=rui[level]-1-w1;
        w2=rui[level]-1-w2;
    }
