vector<ll> closestLanders(ll xc, ll yc, ll sqSize, int goalSide, ll offset) {
//	printf("CL %lld %lld %lld %lld\n", xc, yc, sqSize, (ll)goalSide);
	if (sqSize == 1) return {offset, offset};
	ll subRange = sqSize / 3;
