const int L = 30; 
void solve() {

    vector<ll> pw(L+1);
    pw[0] = 1;
    for (int i = 1; i <= L; i++) {
        pw[i] = pw[i-1]*3;
    }

    int q; cin >> q;
    auto f = [&](ll x0, ll x1){
        for (int i = L-1; i >= 0; x0%=pw[i], x1%=pw[i], i--) {
            int b0 = (x0 / pw[i])%3;
            int b1 = (x1 / pw[i])%3;
            if (b0 != b1) break;
            if (b0 != 1) continue;
            if (x0 > x1) swap(x0,x1);
            return 2ll * min(2ll*pw[i] - x1, x0 - (pw[i]-1));
        }
        return 0ll;
    };
    while (q--) {
