pair<lli, lli> calc(vector<int> &a, vector<int> &b, vector<int> &c, vector<int> &d, int dep)
{
  assert(!(a[dep] == 1 && b[dep] == 1));
  assert(!(c[dep] == 1 && d[dep] == 1));

  int A = a[dep];
  int B = b[dep];
  int C = c[dep];
  int D = d[dep];
  if (dep == 0)
    return make_pair(A - C, B - D);
  auto s = calc(a, b, c, d, dep - 1);
  return make_pair((A - C) + 3ll * s.first, (B - D) + 3ll * s.second);
}
