const int N = 32;
ll p3[N + 1];

vector<int> gt(ll x) {
  vector<int> a(N + 1);
  for (int i = 0; i <= N; ++i) {
    a[i] = x % 3;
    x /= 3;
  }
  return a;
}

ll gt(vector<int> &a) {
  ll res = 0;
  for (int i = (int)a.size() - 1; i >= 0; --i) {
    res = res * 3 + a[i];
  }
  return res;
}

ll LQ(ll x, int mask) {
  ll res = 0;
  for (int j = N; j >= 0; --j) {
    if (res + 2 * p3[j] <= x) {
      res += 2 * p3[j];
    } else if ((mask & (1 << j)) && res + p3[j] <= x) {
      res += p3[j];
    }
  }
  return res;
}

ll GQ(ll x, int mask) {
  ll res = 0;
  for (int j = N; j >= 0; --j) {
    if (mask & (1 << j)) {
      if (res + p3[j] < x) {
        res += 2 * p3[j];
      } else if (res + p3[j] - 1 < x) {
        res += p3[j];
      }
    } else {
      if (res + p3[j] - 1 < x) {
        res += 2 * p3[j];
      }
    }
  }
  return res;
}

