#define REP(i,n) for (ll i = 0; i < (n); ++i)

const ll MAX_LEVEL = 30;

vector<ll> pow3;

void init_pow3(){
    pow3.resize(MAX_LEVEL + 1);
    pow3.at(0) = 1;
    for(ll i = 1; i <= MAX_LEVEL; ++i){
        pow3.at(i) = 3 * pow3.at(i - 1);
    }
}

ll solve(ll y1, ll x1, ll y2, ll x2, ll ly, ll lx){
    if(ly == 1){
        ll ret = abs(y1 - y2) + abs(x1 - x2);
        if((y1 == y2) != (x1 == x2)){
            ret += 2 * ((y1 == y2 && y1 == 1) || (x1 == x2 && x1 == 1));
        }
        return ret;
    }else if(lx == 1){
        return solve(x1, y1, x2, y2, lx, ly);
    }

    const ll h = pow3.at(ly - 1);
    const ll w = pow3.at(lx - 1);

    const ll yi1 = y1 / h, yi2 = y2 / h;
    const ll xi1 = x1 / w, xi2 = x2 / w;

    if(yi1 == yi2 && xi1 == xi2){
        return solve(y1 % h, x1 % w, y2 % h, x2 % w, ly - 1, lx - 1);
    }else if(yi1 != yi2 && xi1 != xi2){
        return abs(y1 - y2) + abs(x1 - x2);
    }else if(yi1 == yi2){
        assert(xi1 != xi2);
        if(yi1 == 1){
            ll ret = abs(x1 - x2);
            ret += min(y1 % h + y2 % h + 2, 2 * h - y1 % h - y2 % h);
            return ret;
        }else{
            return solve(y1 % h, x1, y2 % h, x2, ly - 1, lx);
        }
    }else{
        assert(xi1 == xi2 && yi1 != yi2);
        return solve(x1, y1, x2, y2, lx, ly);
    }
}

int main(){
    init_pow3();
    ll q;
    cin >> q;
    REP(i, q){
        ll ai, bi, ci, di;
        cin >> ai >> bi >> ci >> di;
        ai--; bi--; ci--; di--;
        cout << solve(ai, bi, ci, di, MAX_LEVEL, MAX_LEVEL) << endl;
    }
    return 0;
}

