    long long res = abs(c - a) + abs(d - b);
    for (int k = 0; k < 30; ++k) {
      auto w = power(3LL, k);
      auto aa = a / w, bb = b / w, cc = c / w, dd = d / w;
      if (aa == cc and bb == dd) continue;
      if (aa != cc and bb != dd) continue;
      if (bb == dd) {
        swap(a, b);
        swap(c, d);
        swap(aa, bb);
        swap(cc, dd);
      }
      if (aa % 3 != 1) continue;
      aa = a % w, cc = c % w;
      res = max(res, min(aa + cc + 2, 2 * w - aa - cc) + abs(d - b));
    }
    cout << res << '\n';
  }
}

