bool obs(ll a, ll b) {
    if (a > b) swap(a, b);
    for (ll m = a + 1; m < min(b, a + 4); ++m) {
        if (m % 3 == 1) return true;
    }
    return false;
}

ll solve(ll a, ll b, ll c, ll d) {
    ll bl = 1;
    ll loss = 0;

    rep(i, 30) {
        // yoko
        ll p = a / bl, q = b / bl, r = c / bl, s = d / bl;
        if (p == r && p % 3 == 1 && obs(q, s)) {
            ll d1 = min(p % bl, r % bl) + 1;
            ll d2 = bl - max(p % bl, r % bl);
            chmax(loss, min(d1, d2));
            debug(i, d1, d2);
        }
        // tate
        if (q == s && q % 3 == 1 && obs(p, r)) {
            ll d1 = min(q % bl, s % bl) + 1;
            ll d2 = bl - max(q % bl, s % bl);
            chmax(loss, min(d1, d2));
            debug(i, d1, d2);
        }

        bl *= 3;
    }

    return loss * 2 + abs(a - c) + abs(b - d);
}

