ll man(ll x1, ll y1, ll x2, ll y2) {
	return abs(x1 - x2) + abs(y1 - y2);
}

ll f(ll a, ll b, ll c, ll d, ll e) {
	if(e == 1) return 0;
	if(a / e == c / e && b / e == c / e) {
		return f(a % e, b % e, c % e, d % e, e / 3);
	}
	else {
		if(b / e == 1 && d / e == 1) {
			if(a / e == 2) {
				swap(a, c); swap(b, d);
			}
			return min(
					man(a, b, e - 1, e - 1) + man(e - 1, e - 1, 2 * e - 1, e - 1) + man(2 * e - 1, e - 1, c, d),
					man(a, b, e - 1, 2 * e - 1) + man(e - 1, 2 * e - 1, 2 * e - 1, 2 * e - 1) + man(2 * e - 1, 2 * e - 1, c, d)
					);
		}
		if(a / e == 1 && c / e == 1) {
			if(b / e == 2) {
				swap(a, c);
				swap(b, d);
			}
			return min(
					man(a, b, e - 1, e - 1) + man(e - 1, e - 1, e - 1, 2 * e - 1) + man(e - 1, 2 * e - 1, c, d),
					man(a, b, 2 * e - 1, e - 1) + man(2 * e - 1, e - 1, 2 * e - 1, 2 * e - 1) + man(2 * e - 1, 2 * e - 1, c, d)
					);
		}
		else {
			return man(a, b, c, d);
		}
	}
}

