/*
 * 避けなければならないものは高々一つです。
 * 大きい方から順にためします。
 *
 * i を L で割った商 I が異なるか、j を L で割った商 J が異なるかである最小の L にセットです。
 * これらが両方とも成り立っていたら、コストは 0 です。
 * I が同じで J が異なるとしましょう。
 * I%3==1 であり、J の差が 2 以上ならば壁はこれです。
 * このとき、コストは min(i0%L+1,i1%L+1,L-i0%L,L-j0%L) です。
 * そうでないときには、L / 3 をチェックです。
 * このように繰り返します。繰り返しのたびに、i の方まで違っていないかをチェックです。
 */

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define rep(i, n) for (int i = 0; i < (n); i++)
#define repr(i, n) for (int i = (n) - 1; i >= 0; i--)
