ll f(ll n, ll a, ll b, ll c, ll d) {
  if (a > c) {
    a = n - 1 - a;
    c = n - 1 - c;
  }
  if (b > d) {
    b = n - 1 - b;
    d = n - 1 - d;
  }
  if (n == 3) {
    if (a == 1 && b == 0 && c == 1 && d == 2) {
      return 4;
    }
    if (a == 0 && b == 1 && c == 2 && d == 1) {
      return 4;
    }
    return abs(c - a) + abs(d - b);
  }
  ll m = n / 3;
  if (a / m == c / m && b / m == d / m) {
    cerr << "here2" << endl;

    return f(m, a % m, b % m, c % m, d % m);
  }
  if (a / m != c / m && b / m != d / m) {
    cerr << "here1" << endl;
    return abs(c - a) + abs(d - b);
  }
  if (a / m == c / m) {
    a %= m;
    c %= m;
  } else {
    b %= m;
    d %= m;
  }
  if (a / m < c / m) {
    swap(a, b);
    swap(c, d);
  }
  ll o = m / 3;
  if (a / o != c / o && b / o != d / o) {
    return abs(c - a) + abs(d - b);
  }
  if (a / o == 2) {
    a %= m;
    c %= m;
  }
  if (d / o - b / o == 1) {
    return f(m, a, b % o, c, d % o + o);
  }
  cerr << "here3" << endl;
  // cout << a << ' ' << b % o << ' ' << c << ' ' << d % o + 2*o << ' ' << o << endl;
  return f(m, a, b % o, c, d % o + 2 * o) + (d / o - b / o - 2) * o;
}

