  ll p = 1;
  for (int i = 1; i <= 30; i++) {
    p *= 3;
  }
  while (Q--) {
    ll a, b, c, d; cin >> a >> b >> c >> d;
    a--; b--; c--; d--;
    cout << f(p, a, b, c, d) << endl;
  }
}

