enum class ClockDirection : u8 {
  Null = 0, Even, Clockwise, Counterclockwise,
};

// 時計盤 Clock Face (Dial)
struct Dial3x3 {

  static constexpr u8 dial3x3[3][3] = {
    {7, 0, 1},
    {6, 9, 2},
    {5, 4, 3},
  };

  u8 val;

  Dial3x3(u8 x, u8 y) {
    assert(0 <= x && 0 <= y && x < 3 && y < 3);
    val = dial3x3[y][x];
  }

  Dial3x3(u8 val) {
    assert(0 <= val && val < 8);
    this->val = val;
  }

  // 与えられた位置に対し、どちら周りで進むのが早いかを求める
  ClockDirection GetClockDirection(const Dial3x3& a) {

    if (val == a.val) return ClockDirection::Even;

    // 時計盤での時計回り距離
    auto d = a.val >= val ? a.val - val : a.val + 8 - val;

    return d < 4 ? ClockDirection::Clockwise :
      d > 4 ? ClockDirection::Counterclockwise : ClockDirection::Even;
  }

  // 与えられた位置に時計回りで向かうまでの移動方向を全て求める
  vector<Direction> GetClockwiseMoves(const Dial3x3& a) {
    vector<Direction> result;

    auto vt = val;
    while (vt != a.val) {
      switch (vt) {
      case 1:
      case 2:
        result.push_back(Direction::Down);
        break;
      case 3:
      case 4:
        result.push_back(Direction::Left);
        break;
      case 5:
      case 6:
        result.push_back(Direction::Up);
        break;
      default:
        result.push_back(Direction::Right);
        break;
      }
      if (++vt >= 8) vt = 0;
    }
    return move(result);
  }

  // 与えられた位置に反時計回りで向かうまでの移動方向を全て求める
  vector<Direction> GetCounterclockwiseMoves(const Dial3x3& a) {
    vector<Direction> result;

    auto vt = val;
    while (vt != a.val) {
      switch (vt) {
      case 0:
      case 1:
        result.push_back(Direction::Left);
        break;
      case 2:
      case 3:
        result.push_back(Direction::Up);
        break;
      case 4:
      case 5:
        result.push_back(Direction::Right);
        break;
      default:
        result.push_back(Direction::Down);
        break;
      }
      vt == 0 ? vt = 7 : --vt;
    }
    return move(result);
  }

  // 与えられた方向の外周に接するための移動を全て求める
  vector<vector<Direction>> GetMovesToEdge(const Direction& d) {
    vector<vector<Direction>> results;

    // 辺の中央
    u8 ec;
    // 辺の左右
    u8 es[2];

    switch (d) {
    case Direction::Up:
      ec = 0; es[0] = 7; es[1] = 1;
      break;
    case Direction::Right:
      ec = 2; es[0] = 1; es[1] = 3;
      break;
    case Direction::Down:
      ec = 4; es[0] = 3; es[1] = 5;
      break;
    case Direction::Left:
      ec = 6; es[0] = 5; es[1] = 7;
      break;
    default:
      return results;
    }

    if (val == ec || val == es[0] || val == es[1]) {
      results.push_back(vector<Direction>());
    }
    else {
      auto m1 = GetClockwiseMoves(es[0]);
      auto m2 = GetCounterclockwiseMoves(es[1]);

      // どちらも同じ距離なら両方追加する
      if (m1.size() <= m2.size()) results.push_back(m1);
      if (m2.size() <= m1.size()) results.push_back(m2);
    }

    return results;
  }

  friend bool operator ==(const Dial3x3& l, const Dial3x3& r) {
    return l.val == r.val;
  }
  friend bool operator !=(const Dial3x3& l, const Dial3x3& r) {
    return l.val != r.val;
  }
};

// このレベル内を、指定した方向の辺から出る
i64 toward(i64 l, i64 t, i64& a, i64& b, Direction dir, int level) {

  assert(dir != Direction::Null);
  i64 result = 0;

  if (level == 0) {
    result++;
    switch (dir) {
    case Direction::Left:
      a--;
      break;
    case Direction::Up:
      b--;
      break;
    case Direction::Right:
      a++;
      break;
    case Direction::Down:
      b++;
      break;
    default:
      cerr << "Invalid direcition\n";
      break;
    }
    return result;
  }

  i64 cellSize = pow(3, level - 1);

  auto d = Dial3x3((a - l) / cellSize, (b - t) / cellSize);

  //cout << "toward()" << newl;
  //debug(l); debug(t); debug(a); debug(b);
  //cout << "level=" << level << " " << ToString(dir) << " dial" << (int)d.val << newl;

  auto moves = d.GetMovesToEdge(dir)[0];

  // 指定した方向の辺に接するまで
  for (auto move : moves) {
    //cout << ToString(move);
    result += toward((a - l) / cellSize * cellSize, (b - l) / cellSize * cellSize, a, b, move, level - 1);
  }

  // 指定した方向の辺から出る
  //cout << ToString(dir);
  result += toward((a - l) / cellSize * cellSize, (b - l) / cellSize * cellSize, a, b, dir, level - 1);
  //cout << newl;

  return result;
}

// 目的地に向かう
i64 toward(i64 l, i64 t, i64& a, i64& b, i64 c, i64 d, int level) {

  i64 result = 0;

  if (level == 0) return result;

  i64 cellSize = pow(3, level - 1);

  u8 p1 = (a - l) / cellSize, q1 = (b - t) / cellSize;
  u8 p2 = (c - l) / cellSize, q2 = (d - t) / cellSize;

  auto d1 = Dial3x3(p1, q1), d2 = Dial3x3(p2, q2);

  if (d1 != d2) {
    //debug((int)d1.val);
    //debug((int)d2.val);
    // セルが違うので、そちらのセルに向かって移動する
    auto cd = d1.GetClockDirection(d2);
    vector<Direction> moves =
      cd == ClockDirection::Clockwise ? d1.GetClockwiseMoves(d2)
      : d1.GetCounterclockwiseMoves(d2);
    for (auto move : moves) {
      // セルの左上を(0, 0)とした座標にする
      //cout << (int)d1.val << ' ' << (int)d2.val << ' ' << ToString(move) << newl;
      i64 l2 = (a - l) / cellSize * cellSize,
        t2 = (b - t) / cellSize * cellSize;
      result += toward(l2, t2, a, b, move, level - 1);
    }
  }

  // 同じセルの中にいる
  i64 l2 = (a - l) / cellSize * cellSize,
    t2 = (b - t) / cellSize * cellSize;
  result += toward(l2, t2, a, b, c, d, level - 1);

  return result;
}

i64 getDist(i64 a, i64 b, i64 c, i64 d) {

  i64 dist = toward(0, 0, a, b, c, d, 2);
  return dist;
}

