using namespace std;
typedef long long int ll;
vector<ll> power(31);

bool sameline(ll a, ll b, int k){
    ll line1=(a-1)/power[k-1];
    ll line2=(b-1)/power[k-1];
    if(line1==line2&&line1%3==1)return true;
    return false;
}

bool otherside(ll a, ll b, int k){
    ll line1=(a-1)/power[k-1];
    ll line2=(b-1)/power[k-1];
    if(line2-line1>1)return true;
    return false;
}

ll min_path(ll a,ll b, ll c,ll d){
    ll x1,x2,y1,y2;
    if(abs(a-c)<abs(b-d)){
        x1=min(a,c);
        x2=max(a,c);
        y1=min(b,d);
        y2=max(b,d);
    }else{
        x1=min(b,d);
        x2=max(b,d);
        y1=min(a,c);
        y2=max(a,c);
    }
    for (int k = 30; k > 0 ; k--){
        if(sameline(x1,x2,k)){
            if(otherside(y1,y2,k)){
                ll upl=(x1-1)%power[k-1]+1;
                ll upr=(x2-1)%power[k-1]+1;
                ll downl=power[k-1]-upl+1;
                ll downr=power[k-1]-upr+1;
                return min(upl+upr,downl+downr)+y2-y1;
            }
        }
    }
    return x2-x1+y2-y1;
}
