typedef long long ll;

ll pw[31];

ll dist(ll a, ll b, ll c, ll d, int x = -1) {
    if (x == -1) x = upper_bound(pw, pw + 31, max(max(a, c), max(b, d))) - pw - 1;
    ll A = a / pw[x], B = b / pw[x], C = c / pw[x], D = d / pw[x];
    if (A != C && B != D) {
        return abs(a - c) + abs(b - d);
    }
    if (A == C && B == D) {
        return dist(a % pw[x], b % pw[x], c % pw[x], d % pw[x], x - 1);
    }
    if (B == D) {
        swap(A, B), swap(C, D), swap(a, b), swap(c, d);
    }
    if (A == 1) {
        if (abs(b - d) < 2 * pw[x]) return dist(a - pw[x], b, c - pw[x], d, x - 1);
        return abs(b - d) + min(4 * pw[x] - a - c, a + c - 2 * (pw[x] - 1));
    }
    return x > 0 ? dist(a % pw[x], b, c % pw[x], d, x - 1) : abs(b - d);
}

