		a-=n[k-2]*x11;
		return (x22-x11-2)*n[k-2]+solve(a, b, c, d, k-1);
	}
	c-=n[k-2]*(x22-1);
	a-=n[k-2]*x11;
	return (x22-x11-1)*n[k-2]+solve(a, b, c, d, k-1);

}
