ll p3[31];

vector<int> gt(ll x) {
  vector<int> a(31);
  for (int i = 0; i <= 30; ++i) {
    a[i] = x % 3;
    x /= 3;
  }
  return a;
}

ll gt(vector<int> &a) {
  ll res = 0;
  for (int i = 30; i >= 0; --i) {
    res = res * 3 + a[i];
  }
  return res;
}

ll LQ(ll x, int mask) {
  ll res = 0;
  for (int j = 30; j >= 0; --j) {
    if (res + 2 * p3[j] <= x) {
      res += 2 * p3[j];
    } else if ((mask & (1 << j)) && res + p3[j] <= x) {
      res += p3[j];
    }
  }
  return res;
}

