ll seica(ll a, ll b, ll c, ll d, ll tmp){
	//cout << "seica " << tmp << endl;
	if(((a / tmp) % 3 == 1) && ((c / tmp) % 3 == 1)) {
		//cout << "A" << endl;
		ll ans = abs(b - d);
		ll keymoon = (a % tmp) + (c % tmp) + 2;
		keymoon = min(keymoon, (tmp - (a % tmp)) + (tmp - (c % tmp)));
		return ans + keymoon;
	}
	else if(((b / tmp) % 3 == 1) && ((d / tmp) % 3 == 1)) {
		//cout << "B" << endl;
		ll ans = abs(a - c);
		ll keymoon = (b % tmp) + (d % tmp) + 2;
		keymoon = min(keymoon, (tmp - (b % tmp)) + (tmp - (d % tmp)));
		return ans + keymoon;
	}
	else if(tmp == 1){
		//cout << "C" << endl;
		return abs(a - c) + abs(b - d);
	}
	else {
		return seica(a, b, c, d, tmp / 3);
	}
}

