#define LL long long

const LL dx[4] = {1, -1, 0, 0};
const LL dy[4] = {0, 0, 1, -1};

LL _abs(LL x) {
	if (x > 0) {
		return x;
	}
	return (-x);
}

vector<int> getBit(LL x, int bitn = 35) {
	vector<int> res;
	res.clear();
	while (x > (LL)(0)) {
		res.push_back((int)(x % (LL)(3)));
		x /= (LL)(3);
	}
	while (res.size() < bitn) {
		res.push_back(0);
	}
	return res;
}
int bitn = 35;

LL getDis(LL a, LL b, LL sz) {
	LL down = (a + b + 2);
	LL up = (sz - a) + (sz - b);
	return min(up, down) - _abs(a - b);
}
LL getX(vector<int> x, int k) {
	LL res = 0;
	for (int i = k - 1; i >= 0; --i) {
		res = res * (LL)(3) + (LL)(x[i]);
	}
	return res;
}
LL getM3(int k) {
	LL res = 1;
	for (int i = 0; i < k; ++i) {
		res *= (LL)(3);
	}
	return res;
}

vector<int> cutV(vector<int> &a, int x) {
	vector<int> res;
	res.clear();
	for (int i = 0; i < x; ++i) {
		res.push_back(a[i]);
	}
	return res;
}
LL shortestNeighbor(vector<int> x1, vector<int> y1, vector<int> x2, vector<int> y2, bool sameX) {
	int n = x1.size();
	bool diffX = !sameX;
	LL res = 0;
	for (int i = n - 1; i >= 0; --i) {
		if (diffX) {
			if (y1[i] == 1 && y2[i] == 1) {
				LL yy1 = getX(y1, i);
				LL yy2 = getX(y2, i);
				LL sz = getM3(i);
				return getDis(yy1, yy2, sz);
			}
			else if (y1[i] != y2[i]) {
				return res;
			}
		}
		else {
			if (x1[i] == 1 && x2[i] == 1) {
				LL xx1 = getX(x1, i);
				LL xx2 = getX(x2, i);
				LL sz = getM3(i);
				return getDis(xx1, xx2, sz);
			}
			else if (x1[i] != x2[i]) {
				return res;
			}
		}
	}
	return res;
}

LL getPath(LL x1, LL y1, LL x2, LL y2) {
	vector<int> xb1 = getBit(x1), xb2 = getBit(x2);
	vector<int> yb1 = getBit(y1), yb2 = getBit(y2);

	LL res = _abs(x1 - x2) + _abs(y1 - y2);
	for (int i = bitn - 1; i >= 0; --i) {
		if (xb1[i] == xb2[i] && yb1[i] == yb2[i]) {
			continue;
		}
		int xx1 = xb1[i], xx2 = xb2[i];
		int yy1 = yb1[i], yy2 = yb2[i];
