long long blocked(long long b,long long d, long long width) {
    if (width == 1) return 0;
    long long block_width = width / 3;
    if (b / block_width == d / block_width) {
        if (b / block_width == 1) {
            return min(b - block_width + 1 + d - block_width + 1, 2 * block_width - b + 2 * block_width - d);
        } else {
            return blocked(b % block_width, d % block_width, block_width);
        }
    } else {
        return 0;
    }
}

long long dist(long long a, long long b, long long c, long long d) {
    if (abs(a - c) < abs(b - d)) {
        swap(a, b);
        swap(c, d);
    }
    if (b > d) {
        swap(a, c);
        swap(b, d);
    }
    // b <= d and abs(a - c) >= abs(b - d)
    cerr << a << " " << b << " " << c << " " << d << " " << endl;
    return blocked(b, d, 205891132094649LL) + abs(a - c) + abs(b - d);
}

