		per(k,30){
			ll L = p3[k];
			ll aa = a/L, bb = b/L, cc = c/L, dd = d/L;
			if(aa == cc && aa%3 == 1 && Inc(bb,dd)){
				shows(aa,bb,cc,dd);
				ll X = a/L*L-1;
				ll Y = X+L+1;
				return abs(b-d) + min(abs(a-X)+abs(c-X),abs(a-Y)+abs(c-Y));
