ll obstacle(int a, int b, int c, int d) {
  tie(a,c) = minmax(a,c);
  tie(b,d) = minmax(b,d);
  if (d-b > c-a) swap(a,c), swap(b,d);
  ll res = 0;
  rep(k, 30) {
    ll len = power(3, k);
    if (d-b > len) continue;
    if (c/len - a/len <= 1) continue;
    ll bmod = b % len;
    ll dmod = d % len;
    chmax(res, min(bmod+1, len-dmod));
  }
  return res;
}

int main() {
  int q = IN;
  rep(q) {
    int a = IN, b = IN, c = IN, d = IN;
    a--; b--; c--; d--;
    ll shrt = abs(a-c) + abs(b-d);
    OUT(shrt + 2 * obstacle(a,b,c,d));
  }
}

