}
signed main(){
	q=read();
	while(q--){
		a=read(),b=read(),x=read(),y=read();
		if(a>x)a^=x^=a^=x,b^=y^=b^=y;
		for(re int k=3;k<=1e18;k*=3){
			if(check(a,b,x,y,k)){
				a=(a-1)%k+1,b=(b-1)%k+1,x=(x-1)%k+1,y=(y-1)%k+1;
			//	printf("%d\n",k);
				break;
			}
		}
		re int pwx=1;
	//	printf("%lld %lld %lld %lld\n",a,b,x,y);
