void solve() {
  int n = 1;
  rep(i,30) n *= 3;

  int q; cin >> q;

  while (q--) {
    int a, b, c, d; cin >> a >> b >> c >> d;
    int level = 30;
    int lx = 0, rx = n;
    int ly = 0, ry = n;
    int A, B, C, D;

    while (level--) {
      int sx = lx + (rx-lx) / 3;
      int tx = rx - (rx-lx) / 3;
      A = (a<=sx ? 0 : (a<=tx ? 1 : 2));
      C = (c<=sx ? 0 : (c<=tx ? 1 : 2));
      int sy = ly + (ry-ly) / 3;
      int ty = ry - (ry-ly) / 3;
      B = (b<=sy ? 0 : (b<=ty ? 1 : 2));
      D = (d<=sy ? 0 : (d<=ty ? 1 : 2));

      lx += (tx-sx) * A;
      rx -= (tx-sx) * (2-A);
      ly += (ty-sy) * B;
      ry -= (ty-sy) * (2-B);

      if (A != C || B != D) break;
    }

    if (A != C && B != D) {
      cout << abs(a-c) + abs(b-d) << endl;
      continue;
    }

    if (B == D) {
      swap(a,b); swap(c,d);
      swap(A,B); swap(C,D);
      swap(lx,ly); swap(rx,ry);
    }

    if (A == 1) {
      cout << min(a-lx + c-lx, rx-a+1 + rx-c+1) + abs(b-d) << endl;
      continue;
    }

    if (level == 0) {
      cout << abs(a-c) + abs(b-d) << endl;
      continue;
    }

    int dist = ry - ly;

    while (level--) {
      int sx = lx + (rx-lx) / 3;
      int tx = rx - (rx-lx) / 3;
      A = (a<=sx ? 0 : (a<=tx ? 1 : 2));
      C = (c<=sx ? 0 : (c<=tx ? 1 : 2));
      lx += (tx-sx) * A;
      rx -= (tx-sx) * (2-A);

      if (A != C) {
        cout << abs(a-c) + abs(b-d) << endl;
        break;
      }

      if (A == 1 && abs(b-d) > dist/3*2) {
        cout << min(a-lx + c-lx, rx-a+1 + rx-c+1) + abs(b-d) << endl;
        break;
      }

      if (level == 0) {
        cout << abs(a-c) + abs(b-d) << endl;
        break;
      }

      dist /= 3;
    }
  }
}


