using namespace std;

llint Q;
llint sx, sy, tx, ty;
vector<llint> SX, SY, TX, TY;
llint beki[35];

vector<llint> get(llint x)
{
	vector<llint> ret;
	for(int i = 0; i < 30; i++){
		ret.push_back(x%3);
		x /= 3;
	}
	reverse(ret.begin(), ret.end());
	return ret;
}

llint dist(llint sx, llint sy, llint tx, llint ty)
{
	return abs(sx-tx) + abs(sy-ty);
}

llint trip(llint sx, llint sy, llint tx, llint ty, llint level)
{
	llint ret = inf;
	llint size = beki[29-level];

	llint px = tx/size*size, py = ty/size*size;
	ret = min(ret, dist(sx, sy, px-1, py-1) + dist(px-1, py-1, tx, ty));
	ret = min(ret, dist(sx, sy, px+size, py-1) + dist(px+size, py-1, tx, ty));
	ret = min(ret, dist(sx, sy, px-1, py+size) + dist(px-1, py+size, tx, ty));
	ret = min(ret, dist(sx, sy, px+size, py+size) + dist(px+size, py+size, tx, ty));
	return ret;
}

llint calc(llint sx, llint sy, llint tx, llint ty)
{
	if(sy > ty) swap(sy, ty);
	SX = get(sx), SY = get(sy);
	TX = get(tx), TY = get(ty);

	llint diff = 30; bool flag = false;
	for(int i = 0; i < 30; i++){
		if(flag){
			if(SY[i] == 2 && TY[i] == 0) continue;
			else{
				diff = i;
				break;
			}
		}
		if(SY[i] != TY[i]){
			if(!flag && TY[i] - SY[i] == 1){
				flag = true;
				continue;
			}
			diff = i;
			break;
		}
	}

	llint level = -1;
	for(int i = 0; i < 30; i++){
		if(SX[i] != TX[i]) return -1;
		if(SX[i] == 1){
			if(diff <= i){
				level = i;
				break;
			}
		}
	}
	if(level == -1) return -1;

	return trip(sx, sy, tx, ty, level);
}

int main(void)
{
	beki[0] = 1;
	for(int i = 1; i <= 30; i++) beki[i] = beki[i-1] * 3;

	cin >> Q;
	for(int q = 0; q < Q; q++){
		cin >> sx >> sy >> tx >> ty;
		sx--, sy--, tx--, ty--;

		llint ret = calc(sx, sy, tx, ty);
		if(ret != -1){
			cout << ret << endl;
			continue;
		}
		swap(sx, sy), swap(tx, ty);

		ret = calc(sx, sy, tx, ty);
		if(ret != -1){
			cout << ret << endl;
			continue;
		}

		cout << dist(sx, sy, tx, ty) << endl;
	}
}

