const int L=30;
int p3[L+1];

void slv(){
	int a,b,c,d;cin>>a>>b>>c>>d;
	a--;b--;c--;d--;
	int ans=-1;
	per(lv,30){
		int w=p3[lv];
		int e=a/w;
		int f=b/w;
		int g=c/w;
		int h=d/w;
		if(e!=g&&f!=h){
			ans=abs(a-c)+abs(b-d);
			break;
		}else if(e==g&&f==h){
			a%=w;
			b%=w;
			c%=w;
			d%=w;
		}else{
			if(f==h){
				swap(a,b);
				swap(c,d);
				swap(e,f);
				swap(g,h);
			}
			assert(e==g);
			if(e==1){
				ans=abs(b-d)+min(a%w+1+c%w+1,w-a%w+w-c%w);
			}else{
				if(lv==0)ans=abs(b-d);
				else{
					ans=abs(b-d)+min(abs(a%w-(p3[lv-1]-1))+abs(c%w-(p3[lv-1]-1)),abs(a%w-(p3[lv-1]*2))+abs(c%w-(p3[lv-1]*2)));
					if((a%w<p3[lv-1]&&c%w<p3[lv-1])||(p3[lv-1]*2<=c%w&&p3[lv-1]*2<=c%w))
						chmin(ans,abs(a-c)+abs(b-d));
				}
			}
			break;
		}
	}
	assert(ans!=-1);
	print(ans);
}

