const int K = 32;
ll bs[K+1];

ll acost(int k, ll a, ll b) {
        ll s = bs[k];
        if (a<s || b<s || a>=2*s || b>=2*s) return labs(a-b);
        a -= s;
        b -= s;
        return min(a+b+2, s-a + s-b+2);
}

ll solve(int k, ll a, ll b, ll c, ll d) {
        ll s = bs[k];
        ll aa=a/s, bb=b/s, cc=c/s, dd=d/s;
        if (aa==cc && bb==dd) return solve(k-1, a%s,b%s,c%s,d%s);
        if (abs(aa-cc)+abs(bb-dd) == 1) return labs(c-a) + labs(d-b);
        if (aa!=cc && bb!=dd) return labs(c-a) + labs(d-b);
        if (aa==cc) return labs(d-b) + acost(k, a, c);
        return labs(c-a) + acost(k, b, d);
}

