        s /= 3;
        if (s==0) {
            break;
        }
        ll nai = ai/s;
        ll nbi = bi/s;
        if (nai!=nbi) {
            break;
        }
        ll naj = aj/s;
        ll nbj = bj/s;
        if (abs(naj-nbj)>1 && nai%3==1) {
            ll loss = 2 * (min(ai, bi) - s*nai + 1);
            loss = min(loss, 2*((1+nai)*s-max(ai, bi)));
            res = dist + loss;
            break;
        }
    }
    return res;
}

