    rep(qi, q) {
        ll ai, aj, bi, bj;
        cin >> ai >> aj >> bi >> bj;
        ai--; aj--; bi--; bj--;
        ll ans = solve(ai, aj, bi, bj);
        ans = max(ans, solve(aj, ai, bj, bi));
        cout << ans << endl;
    }

    return 0;
}

