int dfs(int D,pii p1,pii p2)
{
	if(D==0)
	{
		return 0;
	}
	int L=(int)pow(3,D);
	int SL=L/3;
	int p1x=p1.first/SL;
	int p1y=p1.second/SL;
	int p2x=p2.first/SL;
	int p2y=p2.second/SL;

	if(p1x==p2x&&p1y==p2y)
	{
		return dfs(D-1,mp(p1.first-p1x*SL,p1.second-p1y*SL),mp(p2.first-p2x*SL,p2.second-p2y*SL));
	}

	if(p1x==p2x&&p1y!=p2y)
	{
		if(p1x==1)
		{
			int lx=p1x*SL-1,rx=(p1x+1)*SL;
			int res=INF;
			chmin(res,abs(lx-p1.first));
			chmin(res,abs(lx-p2.first));
			chmin(res,abs(rx-p1.first));
			chmin(res,abs(rx-p2.first));
			return res*2;
		}
		else
		{
			return dfs(D-1,mp(p1.first-p1x*SL,p1.second-p1y*SL),mp(p2.first-p1x*SL,min(SL-1,max(0LL,p2.second-p1y*SL))));
		}

	}
	else if(p1x!=p2x&&p1y==p2y)
	{
		if(p1y==1)
		{
			int uy=p1y*SL-1,dy=(p1y+1)*SL;
			int res=INF;
			chmin(res,abs(uy-p1.second));
			chmin(res,abs(uy-p2.second));
			chmin(res,abs(dy-p1.second));
			chmin(res,abs(dy-p2.second));
			return res*2;
		}
		else
		{
			return dfs(D-1,mp(p1.first-p1x*SL,p1.second-p1y*SL),mp(min(SL-1,max(0LL,p2.first-p1x*SL)),p2.second-p1y*SL));
		}
	}
	else
	{
		return 0;
	}
}

