ll distance(ll a,ll b,ll c,ll d,ll level=30){
  if(level==0){
    return abs(b-d);
  }
  ll size=1;
  REP(level){
    size*=3;
  }
  ll sizes=size/3;
  pll f,s;
  f.first=a/sizes;
  f.second=b/sizes;
  s.first=c/sizes;
  s.second=d/sizes;
  if(f.first==s.first&&f.second==s.second){
    return distance(a%sizes,b%sizes,c%sizes,d%sizes,level-1);
  }
  if(f.first!=s.first&&f.second!=s.second){
    return abs(a-c)+abs(b-d);
  }
  if(f.second==s.second){
    swap(f.first,f.second);
    swap(s.first,s.second);
    swap(a,b);
    swap(c,d);
  }
  if(sizes<=a&&a<2*sizes){
    return abs(b-d)+min(abs(sizes-1-a)+abs(sizes-1-c),abs(2*sizes-a)+abs(2*sizes-c));
  }
  if(2*sizes<=a){
    a-=2*sizes;
    c-=2*sizes;
  }
  return distance(a,b,c,d,level-1);
}
