long long AB(long long a,long long b,long long c,long long d,int level) {
  int x = 1000000000;
  int A[9][9] = {{0,0,1,0,x,1,1,1,2},
               {0,0,0,0,x,0,1,1,1},
               {1,0,0,1,x,0,2,1,1},
