               {1,1,2,0,x,1,0,0,1},
               {1,1,1,0,x,0,0,0,0},
               {2,1,1,1,x,0,1,0,0}};
  int B[9][9] = {{0,1,1,1,x,2,1,2,2},
               {1,0,1,2,x,2,2,3,2},
               {1,1,0,2,x,1,2,2,1},
               {1,2,2,0,x,3,1,2,2},
               {x,x,x,x,x,x,x,x,x},
               {2,2,1,3,x,0,2,2,1},
               {1,2,2,1,x,2,0,1,1},
               {2,3,2,2,x,2,1,0,1},
               {2,2,1,2,x,1,1,1,0}};
  long long y = pow(3,level);
  int i = (a/y%3)*3+b/y%3,j = (c/y%3)*3+d/y%3;
  return y*A[i][j] + B[i][j];
}
