long long func(long long a,long long b,long long c,long long d,int level) {
//  printf("(%lld,%lld)-(%lld,%lld) Lv.%d\n",a,b,c,d,level);
  if(level == -1)return 0;
  else if(same(a,b,c,d,level))return func(a,b,c,d,level-1);
  else {
    long long w,x,y,z;
    if(same(a,b,c,b,level)) {
      w = y = func2(a,c);
    }
    else {
      if(a<c) {
        w = a-a%pow(3,level)+pow(3,level)-1;
        y = c-c%pow(3,level);
      }
      else {
        w = a-a%pow(3,level);
        y = c-c%pow(3,level)+pow(3,level)-1;
      }
    }
    if(same(a,b,a,d,level)) {
      x = z = func2(b,d);
    }
    else {
      if(b<d) {
        x = b-b%pow(3,level)+pow(3,level)-1;
        z = d-d%pow(3,level);
      }
      else {
        x = b-b%pow(3,level);
        z = d-d%pow(3,level)+pow(3,level)-1;
      }
    }
    return func(a,b,w,x,level-1)+func(y,z,c,d,level-1)+AB(a,b,c,d,level);
  }
}
