  rep(i , last){
    // 四隅への距離は？
    rep(j,2)rep(k,2){
      x[j][k] += 
        ( (j ? 2 - s[i] : s[i]) + (k ? 2 - t[i] : t[i]) ) * beki[i];

      y[j][k] += 
        ( (j ? 2 - u[i] : u[i]) + (k ? 2 - v[i] : v[i]) ) * beki[i];
    }
  }

  trc(x[0][0],x[0][1],x[1][0],x[1][1]);
  trc(y[0][0],y[0][1],y[1][0],y[1][1]);

  // s[last - 1],t[last - 1]からu[last-1],v[last-1]へ

  WeightedGraph<ll> g(36);
  auto idx=[](int a,int b,int c,int d){
    return a * 12 + b * 4 + c * 2 + d;
  };
  auto ok=[](int a,int b){
    if(a==1&&b==1)return false;
    return 0<=a&&a<3&&0<=b&&b<3;
  };
  auto add =[&g](int a,int b,ll val){
    g[a].eb(a,b,val);
    g[b].eb(b,a,val);
  };
  rep(j,3)rep(k,3) {
    if(!ok(j,k))continue;
    {
      int dj = j+1,dk=k;
      if(ok(j,k)&&ok(dj,dk)){
        add(idx(j,k,1,0),idx(dj,dk,0,0),1);
        add(idx(j,k,1,1),idx(dj,dk,0,1),1);
      }
    }
    {
      int dj = j,dk=k+1;
      if(ok(j,k)&&ok(dj,dk)){
        add(idx(j,k,0,1),idx(dj,dk,0,0),1);
        add(idx(j,k,1,1),idx(dj,dk,1,0),1);
      }
    }
    add(idx(j,k,1,0),idx(j,k,1,1),beki[last-1]*2);
    add(idx(j,k,0,0),idx(j,k,0,1),beki[last-1]*2);
    add(idx(j,k,0,1),idx(j,k,1,1),beki[last-1]*2);
    add(idx(j,k,0,0),idx(j,k,1,0),beki[last-1]*2);
  }

  ll ans = 1LL<<62;
  trc(s[last],t[last],u[last],v[last]);
  rep(j,2)rep(k,2){
    auto d = dijkstra(g,idx(s[last],t[last],j,k));
    trc(d);
    rep(l,2)rep(m,2){
      amin(ans,d[idx(u[last],v[last],l,m)] + x[j][k] + y[l][m]);
    }
    //trc(j,k,ans);
  }
  return ans;




}

