                }
                calced=true;
                break;

                fin:;
            }

            if(!ydif && b[i]==1)
            {
                if(abs(xpre)<=1)
                {
                    if(xpre>0 && a[i]==0 && c[i]==2)
                    {
                        goto fin2;
                    }
                    else if(xpre<0 && a[i]==2 and c[i]==0)
                    {
                        goto fin2;
                    }
                    else if(!xpre && a[i]==c[i])
                    {
                        goto fin2;
                    }
                }

                for(i64 y: {B/pow3[i+1]*pow3[i+1]+pow3[i]-1, B/pow3[i+1]*pow3[i+1]+pow3[i]*2})
                {
                    chmin(ans, abs(A-C) + abs(y-B) + abs(y-D));
                }
                calced=true;
                break;

                fin2:;
            }
        }

        if(!calced) ans=abs(B-D)+abs(A-C);
        cout << ans << "\n";
    }
};

