void rotate_counter(int *x, int *y, int len) {
    rep(i, 0, len) {
        y[i] = (2 - y[i]);
        swap(x[i], y[i]);
    }
}

ll solve(int pos) {
    //cout << pos << endl;
    //cout << x1[pos] << " " << y1[pos] << " " << x2[pos] << " " << y2[pos] << endl;
    if (x1[pos] != x2[pos] && y1[pos] != y2[pos]) {
        return abs(get_val(pos + 1, x1) - get_val(pos + 1, x2)) + 
            abs(get_val(pos + 1, y1) - get_val(pos + 1, y2));
    }
    if (x1[pos] == x2[pos] && y1[pos] == y2[pos]) {
        if (pos == 0) {
            return 0;
        }
        return solve(pos - 1);
    }
    while (true) {
        //cout << x1[pos] << " " << y1[pos] << " " << x2[pos] << " " << y2[pos] << endl;
        if ((y1[pos] == 0 && y2[pos] == 0) || (y1[pos] == 1 && y2[pos] == 1)) {
            break;
        }
        rotate_counter(x1, y1, pos + 1);
        rotate_counter(x2, y2, pos + 1);
    }
    if (x1[pos] > x2[pos]) {
        swap(x1, x2);
        swap(y1, y2);
    }
    //cout << x1[pos] << " " << y1[pos] << " " << x2[pos] << " " << y2[pos] << endl;
    if (y1[pos] == 0) {
        if (pos == 0) {
            return abs(x1[pos] - x2[pos]);
        }
        int p1 = x1[pos] * 3 + x1[pos - 1];
        int p2 = x2[pos] * 3 + x2[pos - 1];
        assert(p1 < p2);
        if (p2 - p1 == 1) {
            if (y1[pos - 1] == y2[pos - 1]) {
                x1[pos - 1] = 0; y1[pos - 1] = 0;
                x2[pos - 1] = 1; y2[pos - 1] = 0;
                return solve(pos - 1);
            } else {
                return abs(get_val(pos + 1, x1) - get_val(pos + 1, x2)) + 
                    abs(get_val(pos + 1, y1) - get_val(pos + 1, y2));
            }
        } else {
            x1[pos - 1] = 0;
            x2[pos - 1] = 2;
            return solve(pos - 1) + ((p2 - p1) - 2) * pw[pos - 1];
        }
    } else {
        //cout << x1[pos - 1] << " " << y1[pos - 1] << " " << x2[pos - 1] << " " << y2[pos - 1] << endl;
        ll v1 = ((pw[pos] - 1) - get_val(pos, x1)) + get_val(pos, y1);
        ll v2 = ((pw[pos] - 1) - get_val(pos, x1)) + ((pw[pos] - 1) - get_val(pos, y1));
        ll v3 = get_val(pos, x2) + get_val(pos, y2);
        ll v4 = get_val(pos, x2) + ((pw[pos] - 1) - get_val(pos, y2));
        //cout << v1 << " " << v2 << " " << v3 << " " << v4 << endl;
        return min(v1 + v3, v2 + v4) + 2 + 1 + pw[pos];
    }
}

