using VI = vector <int> ;
using VVI = vector <VI> ;
using VLL = vector <long long>;
using VVLL = vector <VLL>;
using PLL = pair<long long, long long>;

const int MAXD = 32;
VLL digits(MAXD+2);
inline PLL toCoor(int level, long long a, long long b) {
    return make_pair(a / digits[level], b / digits[level]);
}

inline long long getDist(int level, long long a, long long b) {
    long long from = digits[level];
    long long to = digits[level]*2 - 1;

    if (a >= from && a <= to
        && b >= from && b <= to) {
            return min(abs(a-from)+abs(b-from), abs(b-to)+abs(b-from));
    }

    return abs(a-b);
}

inline long long get2DDist(int level, long long a, long long b, long long c, long long d) {
    return getDist(level, a, c) + getDist(level, b, d);
}

long long solve(int level, long long a, long long b, long long c, long long d) {
    if (level < 0) {
        return 0;
    }

    // 3 x 3
    auto C1 = toCoor(level, a, b);
    auto C2 = toCoor(level, c, d);
    const long long INF = 1000000000LL * 1000000000LL;
    // cout << "DEBUG " << (C1 == C2) << " " << a << " " << b << " " << c << " " << d << endl;

    if (C1 == C2) {
        return solve(level-1, a % digits[level], b % digits[level], c % digits[level], d % digits[level]);
    } else {
        // move the same blocks
        long long bestDist = INF;

        VVLL cand; // four corners
        // corners of C1
        long long upper = digits[level] - 1;
        cand.push_back({C1.first*digits[level], C1.second*digits[level]});
        cand.push_back({C1.first*digits[level]+upper, C1.second*digits[level]});
        cand.push_back({C1.first*digits[level], C1.second*digits[level]+upper});
        cand.push_back({C1.first*digits[level]+upper, C1.second*digits[level]+upper});

        if ( (C1.first == 1 && C2.first == 1)
            || (C1.second == 1 && C2.second == 1) ) {

            for (int i = 0; i < cand.size(); ++i) {
                long long res = get2DDist(level, c, d, cand[i][0], cand[i][1])
                + solve(level-1, a % digits[level], b % digits[level], cand[i][0] % digits[level], cand[i][1] % digits[level]);
                bestDist = min(bestDist, res);
            }
        } else {
            long long localMin = INF;
            int bestDir = -1;

            for (int i = 0; i < cand.size(); ++i) {
                long long res = get2DDist(level, c, d, cand[i][0], cand[i][1]);
                if (res < localMin) {
                    localMin = res;
                    bestDir = i;
                }
            }

            long long res = get2DDist(level, c, d, cand[bestDir][0], cand[bestDir][1]) +
            solve(level-1, a % digits[level], b % digits[level], cand[bestDir][0] % digits[level], cand[bestDir][1] % digits[level]);
            bestDist = min(bestDist, res);
        }

        return bestDist;
    }
}

int main() {
    digits[0] = 1;

    for (int i = 1; i < MAXD; ++i) {
        digits[i] = digits[i-1] * 3;
    }

    int Q;
    cin >> Q;

    while (Q--) {
        long long a;
        long long b;
        long long c;
        long long d;

        cin >> a >> b >> c >> d;
        cout << solve(MAXD-1, a, b, c, d) << endl;
    }

    return 0;
}

