using namespace std;

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  vector<long long> p3(30);
  for (int i = 0; i < 30; ++i) {
    p3[i] = i ? 3 * p3[i - 1] : 1;
  }
  auto f = [&](auto&& self, long long si, long long sj, long long ti, long long tj, int lv) -> long long {
    if (si / p3[lv] != ti / p3[lv] and sj / p3[lv] != tj / p3[lv]) {
      return abs(ti - si) + abs(tj - sj);
    }
    if (si / p3[lv] == ti / p3[lv] and sj / p3[lv] == tj / p3[lv]) {
      assert(lv);
      return self(self, si % p3[lv], sj % p3[lv], ti % p3[lv], tj % p3[lv], lv - 1);
    }
    if (si / p3[lv] != ti / p3[lv]) {
      swap(si, sj);
      swap(ti, tj);
    }
    assert(si / p3[lv] == ti / p3[lv] and sj / p3[lv] != tj / p3[lv]);
    if (sj > tj) {
      swap(si, ti);
      swap(sj, tj);
    }
    if (si / p3[lv] == 1) {
      return abs(tj - sj) + min((si - p3[lv] + 1) + (ti - p3[lv] + 1), (2 * p3[lv] - si) + (2 * p3[lv] - ti));
    } else {
      if (lv == 0) {
        return abs(tj - sj);
      }
      if (si / p3[lv] == 2) {
        si -= 2 * p3[lv];
        ti -= 2 * p3[lv];
      }
      if (si / p3[lv - 1] == ti / p3[lv - 1]) {
        auto w = p3[lv - 1];
        if (si / p3[lv - 1] == 1) {
          if ((sj < w and 2 * w <= tj) or (sj < 4 * w and 5 * w <= tj) or (sj < 7 * w and 8 * w <= tj)) {
            return abs(tj - sj) + min((si - w + 1) + (ti - w + 1), (2 * w - si) + (2 * w - ti));
          } else {
            si -= w;
            ti -= w;
            while (tj >= 3 * w) {
              sj -= w;
              tj -= w;
            }
            return self(self, si, sj, ti, tj, lv - 1);
          }
        } else {
          long long offset = 0;
          while (tj - sj >= 3 * w) {
            tj -= 3 * w;
            offset += 3 * w;
          }
          while (tj >= 3 * w) {
            sj -= w;
            tj -= w;
          }
          return offset + self(self, si, sj, ti, tj, lv - 1);
        }
      } else {
        return abs(ti - si) + abs(tj - sj);
      }
    }
  };
  int q;
  cin >> q;
  while (q--) {
    long long si, sj, ti, tj;
    cin >> si >> sj >> ti >> tj;
    --si, --sj, --ti, --tj;
    cout << f(f, si, sj, ti, tj, 29) << '\n';
  }
}

