ll LQ(ll x, int mask) {
  ll res = 0;
  for (int j = N; j >= 0; --j) {
    if (res + 2 * p3[j] <= x) {
      res += 2 * p3[j];
    } else if ((mask & (1 << j)) && res + p3[j] <= x) {
      res += p3[j];
    }
  }
  return res;
}

ll GQ(ll x, int mask) {
  ll res = 0;
  for (int j = N; j >= 0; --j) {
    if (mask & (1 << j)) {
      if (res + p3[j] < x) {
        res += 2 * p3[j];
      } else if (res + p3[j] - 1 < x) {
        res += p3[j];
      }
    } else {
      if (res + p3[j] - 1 < x) {
        res += 2 * p3[j];
      }
    }
  }
  return res;
