template <class T> T maximum(T a, T b) { return a < b ? b : a; }
template <class T> T minimum(T a, T b) { return a > b ? b : a; }
template <class T> void swap(T& a, T& b) { T c = a; a = b; b = c; }
template <class T> T abs_(T a) { return a < 0 ? -a : a; }
using std::pair;
