ll solve(ll ai, ll aj, ll bi, ll bj) {
    if (aj > bj) {
        swap(ai, bi);
        swap(aj, bj);
    }

    ll s = 1;
    rep(i,30) s *= 3;
    ll dist = abs(ai-bj) + abs(aj-bj);
    ll res = dist;
    while(1) {
        s /= 3;
        if (s <= 0) break;

        ll nai = ai / s, nbi = bi / s;
        if (nai != nbi) break;

        ll naj = aj / s, nbj = bj / s;
        if (nai % 3 == 1 && abs(naj-nbj) > 1) {
            ll up = s*nai-1;
            ll bot = s*(nai+1);
            ll loss = min(ai,bi) - up;
            loss = min(loss, bot - max(ai, bi));
            res = dist + loss * 2;
            break;
        }
    }
    return res;
}

