int bitn = 35;

LL getDis(LL a, LL b, LL sz) {
	LL down = (a + b + 2);
	LL up = (sz - a) + (sz - b);
	return min(up, down) - _abs(a - b);
}
LL getX(vector<int> x, int k) {
	LL res = 0;
	for (int i = k - 1; i >= 0; --i) {
		res = res * (LL)(3) + (LL)(x[i]);
	}
	return res;
}
LL getM3(int k) {
	LL res = 1;
	for (int i = 0; i < k; ++i) {
		res *= (LL)(3);
	}
	return res;
}

vector<int> cutV(vector<int> &a, int x) {
	vector<int> res;
	res.clear();
	for (int i = 0; i < x; ++i) {
		res.push_back(a[i]);
	}
	return res;
}
LL shortestNextNeighbor(vector<int> x1, vector<int> y1, vector<int> x2, vector<int> y2, bool sameX) {
	int n = x1.size();
	bool diffX = !sameX;
	LL res = 0;
	for (int i = n - 1; i >= 0; --i) {
		if (diffX) {
			if (y1[i] == 1 && y2[i] == 1) {
				LL yy1 = getX(y1, i);
				LL yy2 = getX(y2, i);
				LL sz = getM3(i);
				return getDis(yy1, yy2, sz);
			}
			else if (y1[i] != y2[i]) {
				return res;
			}
		}
		else {
			// cout << "here" << endl;
			if (x1[i] == 1 && x2[i] == 1) {
				LL xx1 = getX(x1, i);
				LL xx2 = getX(x2, i);
				LL sz = getM3(i);
				// printf("xx1 = %lld, xx2 = %lld, sz = %lld\n", xx1, xx2, sz);
				// printf("dis = %lld\n", getDis(xx1, xx2, sz));
				return getDis(xx1, xx2, sz);
			}
			else if (x1[i] != x2[i]) {
				return res;
			}
		}
	}
	return res;
}

LL shortestNeighbor(vector<int> x1, vector<int> y1, vector<int> x2, vector<int> y2, int xx1, int yy1, int xx2, int yy2) {
	int n = x1.size();
	bool noContact = false;
	if (yy1 == yy2) {
		if (xx1 > xx2) {
			swap(y1, y2);
			swap(x1, x2);
		}
		for (int i = n - 1; i >= 0; --i) {
			// cout << "i = " << i << endl;
			if (y1[i] == 1 && y2[i] == 1 && (noContact || (x1[i] < 1 || x2[i] > 1))) {
				LL yy1 = getX(y1, i);
				LL yy2 = getX(y2, i);
				LL sz = getM3(i);
				// cout << "stop at i = " << i << endl;
				return getDis(yy1, yy2, sz);
			}
			else if (y1[i] != y2[i]) {
				return 0;
			}
			else if (x1[i] <= 1 || x2[i] >= 1) {
				noContact = true;
			}
		}
	}
	if (xx1 == xx2) {
		if (yy1 > yy2) {
			swap(x1, x2);
			swap(y1, y2);
		}
		for (int i = n - 1; i >= 0; --i) {
			if (x1[i] == 1 && x2[i] == 1 && (noContact || (y1[i] < 1 || y2[i] > 1))) {
				LL xx1 = getX(x1, i);
				LL xx2 = getX(x2, i);
