				return getDis(xx1, xx2, sz);
			}
			else if (x1[i] != x2[i]) {
				return 0;
			}
			else if (y1[i] <= 1 || y2[i] >= 1) {
				noContact = true;
			}
		}
	}
	return 0;
}

