LL getPath(LL x1, LL y1, LL x2, LL y2) {
	vector<int> xb1 = getBit(x1), xb2 = getBit(x2);
	vector<int> yb1 = getBit(y1), yb2 = getBit(y2);

	// cout << "x1 = ";
	// printVector(xb1);
	// cout << "x2 = ";
	// printVector(xb2);
	// cout << "y1 = ";
	// printVector(yb1);
	// cout << "y2 = ";
	// printVector(yb2);

	LL res = _abs(x1 - x2) + _abs(y1 - y2);
	for (int i = bitn - 1; i >= 0; --i) {
		if (xb1[i] == xb2[i] && yb1[i] == yb2[i]) {
			continue;
		}
		int xx1 = xb1[i], xx2 = xb2[i];
		int yy1 = yb1[i], yy2 = yb2[i];
		// printf("(%d, %d), (%d, %d)\n", xx1, yy1, xx2, yy2);

		bool corner1 = true;
		/* if (xx1 == 0 && yy1 == 1) {
			corner1 = false;
		}
		if (xx1 == 2 && yy1 == 1) {
			corner1 = false;
		}
		if (xx1 == 1 && yy1 == 0) {
			corner1 = false;
		}
		if (xx1 == 1 && yy1 == 2) {
			corner1 = false;
		} */
		corner1 = (((xx1 + yy1) % 2) == 0);


		//LL zero = (LL)(0), one = (LL)(1), two = (LL)(2);
		if (corner1) {
			if (xx2 != xx1 && yy2 != yy1) {
				return res;
			}
			else {
				int diff = abs(xx1 - xx2) + abs(yy1 - yy2);
				if (diff == 2) {
				// cout << "here" << endl;
					return res + shortestNextNeighbor(cutV(xb1, i), cutV(yb1, i), cutV(xb2, i), cutV(yb2, i), (xx1 == xx2));
				}
				else {
					return res + shortestNeighbor(cutV(xb1, i), cutV(yb1, i), cutV(xb2, i), cutV(yb2, i), xx1, yy1, xx2, yy2);
				}
				// continue;
			}
		}
		else {
			int diff = _abs(xx1 - xx2) + _abs(yy1 - yy2);
			if (diff == 1) {
				// cout << "here" << endl;
				return res + shortestNeighbor(cutV(xb1, i), cutV(yb1, i), cutV(xb2, i), cutV(yb2, i), xx1, yy1, xx2, yy2);
				// continue;
			}
			else {
				// return res;
				if (xx2 == xx1 && yy2 + yy1 == 2 && xx1 == 1) {
					LL sz = getM3(i);
					LL xz1 = getX(xb1, i), xz2 = getX(xb2, i);
					return res + getDis(xz1, xz2, sz);
				}
				if (yy2 == yy1 && xx2 + xx1 == 2 && yy1 == 1) {
					LL sz = getM3(i);
					LL yz1 = getX(yb1, i), yz2 = getX(yb2, i);
					return res + getDis(yz1, yz2, sz);
				}
				return res;
			}
		}
	}
	return res;
}
