ll da[33],db[33],dc[33],dd[33];
int ca,cb,cc,cd;
ll dp[35];
ll mi=1;

ll solve(ll a,ll b,ll c,ll d){
	if(labs(a-c)+labs(b-d)<=1){
		return labs(a-c)+labs(b-d);
	}
	ll ta=a,tb=b,tc=c,td=d;
	for(int i=0;i<35;i++){
		dp[i]=mi+1LL;
	}
	int g=0;
	while(a>0){
		da[g]=a%3;
		a/=3;
		if(da[g]==1){
			ca++;
		}
		g++;
	}
	g=0;
	while(b>0){
		db[g]=b%3;
		b/=3;
		if(db[g]==1){
			cb++;
		}
		g++;
	}
	g=0;
	while(c>0){
		dc[g]=c%3;
		c/=3;
		if(dc[g]==1){
			cc++;
		}
		g++;
	}
	g=0;
	while(d>0){
		dd[g]=d%3;
		d/=3;
		if(dd[g]==1){
			cd++;
		}
		g++;
	}
	ll sum=0;
	if(ca+cb==0){
		return labs(ta-tc)+labs(tb-td);
	}
	if(ca>0){
		if(cc==0){
			return labs(ta-tc)+labs(tb-td);
		}
		dp[0]=0;
		ll dig=1;
		for(int i=0;i<31;i++){
			for(ll j=0;j<3;j++){
				if(j==1)continue;
				ll dif=labs(j-da[i])+labs(j-dc[i]);
				dp[i+1]=min(dp[i+1],dp[i]+dif*dig);
			}
			dig*=3LL;
		}
		return labs(tb-td)+dp[31];
	}
	if(cb>0){
		if(cd==0){
			return labs(ta-tc)+labs(tb-td);
		}
		dp[0]=0;
		ll dig=1;
		for(int i=0;i<31;i++){
			for(ll j=0;j<3;j++){
				if(j==1)continue;
				ll dif=labs(j-db[i])+labs(j-dd[i]);
				dp[i+1]=min(dp[i+1],dp[i]+dif*dig);
			}
			dig*=3LL;
		}
		return labs(ta-tc)+dp[31];
	}
	assert(false);
	return -1;
}

