	ll x1=a/n[k-1], y1=b/n[k-1], x2=c/n[k-1], y2=d/n[k-1];
	if(P(x1, y1)==P(x2, y2)){
		a-=n[k-1]*x1, b-=n[k-1]*y1, c-=n[k-1]*x2, d-=n[k-1]*y2;
		return solve(a, b, c, d, k-1);
	}
	if(x1!=x2 && y1!=y2) return abs(a-c)+abs(b-d);
	if(y1!=y2){
		swap(a, b), swap(c, d), swap(x1, y1), swap(x2, y2);
	}
