		ll s=b-n[k-1]+1+d-n[k-1]+1;
		return abs(a-c)+min(s, 2*(n[k-1]+1)-s);
	}
	b-=y1*n[k-1], d-=y1*n[k-1];
	if(k==1) return abs(a-c)+abs(b-d);
	if(x1>x2){
		swap(x1, x2), swap(a, c), swap(b, d);
	}
	ll ret=0;
	if(abs(x1-x2)==2){
		ret+=n[k-1];
		x2--;
