string combine(string s, string t) {

	string res = s + t;

	for (int i = s.size() - 1; i >= 0; i--){
		int p = s.size() - i;
		bool ok = true;

		for (int j = 0; j < p && ok; j++)
		{
			if (!(s[i + j] == t[j]
				|| s[i + j] == '?' || t[j] == '?')) {
				ok = false;
			}
		}

		if (!ok) continue;
		string v = "";
		for (int j = 0; j < i; j++)
		{
			v += s[j];
		}
		for (int j = 0; j < t.size(); j++)
		{
			if (j < p) {
				if (s[i + j] == '?' && t[j] != '?') {
					v += t[j];
				}
				else if (s[i + j] != '?' && t[j] == '?') {
					v += s[i + j];
				}
				else {
					v += t[j];
				}
			}
			else
				v += t[j];
		}
		res = v;
	}
	return res;
}
