	vector<ll> p3(1, 1);
	REP(i, 30) p3.emplace_back(p3.back() * 3);

	auto dist = [](ll y1, ll x1, ll y2, ll x2) -> ll {
		return abs(y1 - y2) + abs(x1 - x2);
	};

	auto flip = [](ll &a, ll &b, ll &c, ll &d) -> void {
		swap(a, b);
		swap(c, d);
	};

	auto dfs1 = [&](auto &&dfs1, auto &&dfs2, int level, ll y1, ll x1, ll y2, ll x2, ll sum) -> ll {
		if (level == 0) return sum;

		ll by1 = y1 / p3[level - 1], bx1 = x1 / p3[level - 1], by2 = y2 / p3[level - 1], bx2 = x2 / p3[level - 1];
		if (by1 != by2 && bx1 != bx2) return sum + dist(y1, x1, y2, x2);
		if (bx1 == bx2) { flip(y1, x1, y2, x2); flip(by1, bx1, by2, bx2); }
		// by1 = by2
		if (x1 > x2) { flip(x1, x2, y1, y2); flip(bx1, bx2, by1, by2); }
		// x1 <= x2

		if (by1 == 1 && bx1 != bx2) {
			return sum + abs(x1 - x2)
			+ min(abs(p3[level - 1] - 1 - y1) + abs(p3[level - 1] - 1 - y2)
				, abs(p3[level - 1] * 2 - y1) + abs(p3[level - 1] * 2 - y2));
		}

		y1 %= p3[level - 1]; by1 = 0;
		y2 %= p3[level - 1]; by2 = 0;

		while (bx1 > 0 && bx2 > 0) {
			x1 -= p3[level - 1];
			x2 -= p3[level - 1];
			--bx1; --bx2;
		}

		if (bx1 == bx2) return dfs1(dfs1, dfs2, level - 1, y1, x1, y2, x2, sum);
		if (bx1 == 0 && bx2 == 2) {
			return dfs1(dfs1, dfs2, level - 1, y1, 0, y2, p3[level - 1] - 1, sum + (p3[level - 1] - x1) + (x2 - p3[level - 1] * 2 + 1));
		}

		// bx1 = 0 and bx2 = 1
		return dfs2(dfs1, dfs2, level - 1, y1, x1, y2, x2, sum);
	};

	// 横
	auto dfs2 = [&](auto &&dfs1, auto &&dfs2, int level, ll y1, ll x1, ll y2, ll x2, ll sum) -> ll {
		if (level == 0) return 1 + sum;

		ll by1 = y1 / p3[level - 1], bx1 = x1 / p3[level - 1], by2 = y2 / p3[level - 1], bx2 = x2 / p3[level - 1];
		if (by1 != by2) return sum + dist(y1, x1, y2, x2);

		if (by1 == 1) {
			if (bx1 == 0) return dfs1(dfs1, dfs2, level, y1, x1, y2, p3[level] - 1, sum + x2 - p3[level] + 1);
			if (bx2 == 5) return dfs1(dfs1, dfs2, level, y1, 0, y2, x2 % p3[level], sum + p3[level] - x1);
		}

		y1 %= p3[level - 1]; by1 = 0;
		y2 %= p3[level - 1]; by2 = 0;

		if (bx1 < 2) {
			sum += 2 * p3[level - 1] - x1;
			x1 = 0;
		}
		else x1 %= p3[level - 1];
		if (bx2 > 3) {
			sum += x2 - p3[level - 1] * 4 + 1;
			x2 = p3[level - 1] * 2 - 1;
		}
		else x2 = x2 % p3[level - 1] + p3[level - 1];

		return dfs2(dfs1, dfs2, level - 1, y1, x1, y2, x2, sum);
	};

	int Q;
