vector<vector<ll>> sim = {
    {0,1,2,1,0,3,2,3,4},
    {1,0,1,2,0,2,3,4,3},
    {2,1,0,3,0,1,4,3,2},
    {1,2,3,0,0,4,1,2,3},
    {0,0,0,0,0,0,0,0,0},
    {3,2,1,4,0,0,3,2,1},
    {2,3,4,1,0,3,0,1,2},
    {3,4,3,2,0,2,1,0,1},
    {4,3,2,3,0,1,2,1,0}};

ll calc(ll a, ll b, ll c, ll d) {
    if (a == c && b == d) return 0LL;
    ll res = 0;
    ll mx = max(max(a, b), max(c, d));
    if (mx <= 2) {
        ll s = a*3+b;
        ll t = c*3+d;
        return sim[s][t];
    }
    ll na = a/3, nb = b/3, nc = c/3, nd = d/3;
    res += calc(na, nb, nc, nd)*3;
    if (a == c && a%3 == 1) res += 2;
    if (b == d && b%3 == 1) res += 2;
    if (a < c) res += (1-a%3) + (c%3-1);
    if (a > c) res += (a%3-1) + (1-c%3);
    if (b < d) res += (1-b%3) + (d%3-1);
    if (b > d) res += (b%3-1) + (1-d%3);
    return res;
}

