using namespace std;

typedef long long ll;
typedef pair <ll, ll> pll;

const ll N = 205891132094649;

ll a, b, c, d;

pll get_block(ll x1, ll y1, ll len, ll a, ll b) {
	ll xx = x1, yy = y1;
	if (x1 + len <= a) xx = x1 + len;
	if (x1 + len + len <= a) xx = x1 + len + len;
	if (y1 + len <= b) yy = y1 + len;
	if (y1 + len + len <= b) yy = y1 + len + len;
	return mp(xx, yy);
}

ll dfs(ll x1, ll y1, ll x2, ll y2) {
	ll len = (x2 - x1) / 3;
	pll id1 = get_block(x1, y1, len, a, b);
	pll id2 = get_block(x1, y1, len, c, d);
	if (id1 == id2) return dfs(id1.fi, id1.se, id1.fi + len - 1, id1.se + len - 1);
	if (id1.fi == x1 + len && id2.fi == x1 + len) {
		return abs(d - b) + min(a - id1.fi + c - id1.fi, 2 * len - a + id1.fi - c + id1.fi);
	}
	if (id1.se == y1 + len && id2.se == y1 + len) {
		return abs(c - a) + min(b - id1.se + d - id1.se, 2 * len - b + id1.se - d + id1.se);
	}
	return abs(c - a) + abs(b - d);
}

