typedef long long ll;
ll q,seq[2][2][33],doc[33],a,b,c,d,ans;
void input(ll a,int ty1,int ty2)
{
	int st=0;
	for(int i=0;i<30;i++)seq[ty1][ty2][i]=0;
	while(a)
	{
		seq[ty1][ty2][st++]=a%3;
		a/=3;
	}
}
ll calc(int p,ll a,ll b)
{
	ll sum=2-abs(a-b),sum0=0,sum1=0;
	sum0=a%doc[p]+b%doc[p];
	sum1=4ll*doc[p]-2ll-sum0;
	return sum+min(sum0,sum1);
}
int main(){
	doc[0]=1;
	for(int i=1;i<=30;i++)doc[i]=3ll*doc[i-1];
	scanf("%lld",&q);
	for(int _=1;_<=q;_++)
	{
		scanf("%lld%lld%lld%lld",&a,&b,&c,&d);
		a--;b--;c--;d--;
		ans=abs(a-c)+abs(b-d);
		input(a,0,0);
		input(b,0,1);
		input(c,1,0);
		input(c,1,1);
		if(a==c&&b==d)
		{
			printf("0\n");
			continue;	
		}	
		int i;
		for(i=29;i>=0;i--)
		{
			if(seq[0][0][i]!=seq[1][0][i]||seq[0][1][i]!=seq[1][1][i])
			{
				break;
			}
		}
		for(;i>=0;i--)
		{
			if(seq[0][0][i]==1&&seq[1][0][i]==1)
			{
				ans+=calc(i,a,c);
				break;
			}
			if(seq[0][1][i]==1&&seq[1][1][i]==1)
			{
				ans+=calc(i,b,d);
				break;
			}
		}
		printf("%lld\n",ans);
	}
}

