			if(b / e == 2) {
				swap(a, c);
				swap(b, d);
			}
			return min(
					man(a, b, e - 1, e - 1) + man(e - 1, e - 1, e - 1, 2 * e - 1) + man(e - 1, 2 * e - 1, c, d),
