const ll s = pow(3, 29);
ll solve(ll a1, ll a2, ll b1, ll b2) {
  if (a2 > b2) {
    swap(a1, b1);
    swap(a2, b2);
  }
  ll res = abs(a1-b1) + abs(a2-b2);
  for (ll ss = s; ss >= 0; ss /= 3) {
    ll na1 = a1 / ss, nb1 = b1 / ss;
    if (na1 != nb1) break;
    ll na2 = a2 / ss, nb2 = b2 / ss;
    if (na1%3 == 1 && abs(nb2 - na2) > 1) {
      ll up = ss*na1 - 1;
      ll down = ss*(na1+1);
      ll loss = min(min(a1, b1)-up, down-max(a1, b1));
      res += 2*loss;
      break;
    }
  }
  return res;
}

