int32_t main() {
    constexpr int M = 30;
    int pow3[M+1] = {1};
    rep (i,M) pow3[i+1] = pow3[i]*3;

    def (solve, int x0, int y0, int x1, int y1, int level) -> int {
        assert(level >= 0);
        assert(x0 < pow3[level+1]);
        assert(y0 < pow3[level+1]);
        assert(x1 < pow3[level+1]);

        const int dist = abs(x0-x1) + abs(y0-y1);
        const int L = pow3[level];
        const int xx = (x0/L == x1/L), yy = (y0/L == y1/L);
        if (xx && yy) return solve(x0%L, y0%L, x1%L, y1%L, level-1);
        if (!xx && !yy) return dist;
        if (!xx && yy) swap(x0,y0), swap(x1,y1);

        if (y0/L > y1/L) swap(x0,x1), swap(y0,y1);
        assert(x0/L == x1/L && y0/L < y1/L);

        if (x0/L != 1) {
            if (level == 0) return dist;
            const int dy = y0/L*L;
            return solve(x0%L, y0-dy, x1%L, y1-dy, level-1);
        } else if (abs(y0/L - y1/L) == 1) {
            if (level == 0) return dist;
            assert(y0/L == 2);
            return solve(x0-L, y0-2*L, x1-L, y1-2*L, level-1);
        } else {
            x0 -= L, x1 -= L;
            return min(2+x0+x1, 2*L-(x0+x1)) + abs(y0-y1);
        }
    };

    int q; cin >> q;
    while (q--) {
        int a,b,c,d; cin >> a >> b >> c >> d;
        --a,--b,--c,--d;
//        cout << a << b << c << d;
        cout << solve(a,b,c,d,M-1) << "\n";
