vector<long long> three;

bool ismid(int K, long long x) {
    long long l = three[K-1], r = l * 2;
    if (x >= l && x < r) return true;
    return false;
}

bool ismid(int K, long long x, long long y) {
    return ismid(K, x) || ismid(K, y);
}

long long solve(long long sx, long long sy, long long tx, long long ty) {
    long long def = abs(sx - tx) + abs(sy - ty);
    long long len = max(abs(sx - tx), abs(sy - ty));
    long long low = 0, high = 30;
    while (high - low > 1) {
        long long mid = (high + low) / 2;
        if (len < three[mid]) high = mid;
        else low = mid;
    }
    long long K = high;
    sx %= three[K];
    sy %= three[K];
    tx %= three[K];
    ty %= three[K];

    /*
    COUT("-------------");
    COUT(sx); COUT(sy); COUT(tx); COUT(ty);
    COUT(K); COUT(def);
    COUT(ismid(K, sx)); COUT(ismid(K, tx)); COUT(ismid(K, sy)); COUT(ismid(K, ty));
    */
    long long l = three[K-1]-1, r = three[K-1]*2;
    if (ismid(K, sx) && ismid(K, tx)) {
        long long left = abs(sx - l) + abs(sy - ty) + abs(tx - l);
        long long right = abs(sx - r) + abs(sy - ty) + abs(tx - r);
        return min(left, right);
    }
    else if (ismid(K, sy) && ismid(K, ty)) {
        long long left = abs(sy - l) + abs(sx - tx) + abs(ty - l);
        long long right = abs(sy - r) + abs(sx - tx) + abs(ty - r);
        return min(left, right);
    }
    else return def;
}

int main() {
    three.assign(31, 1);
    for (int i = 0; i < 30; ++i) three[i+1] = three[i] * 3;
    //COUT(three);
    int Q;
    cin >> Q;
    for (int i = 0; i < Q; ++i) {
        long long a, b, c, d;
        cin >> a >> b >> c >> d;
        --a, --b, --c, --d;
        cout << solve(a, b, c, d) << endl;
    }   
}

