int64_t p3[30];

int64_t iabs(int64_t x) { return std::max(x, -x); }
// zero-base
// 0 1 2
// 3 4 5
// 6 7 8
int64_t calc(int64_t a, int64_t b, int64_t c, int64_t d, int l) {
  int64_t L = p3[l-1], LL = p3[l]-1;
  if(l == 1) return iabs(a-c) + iabs(b-d);
  if(L <= b && b < L*2 && L <= d && d < L*2) { std::swap(a, b); std::swap(c, d); }
  if(L <= a && a < L*2 && L <= c && c < L*2) {
    // (a,b)(c,d): 1 or 7
    a %= L; c%= L;
    if(b > d) { std::swap(a, c); std::swap(b, d); }
    if(d < L || L < b) return calc(a, b%L, c, d%L, l-1);
    b %= L; d%= L;
    int64_t r1 = iabs(a+1) + iabs(c+1);
    int64_t r2 = iabs(a-L) + iabs(c-L);
    return std::min(r1, r2) + iabs(b-d);
  }
  // make (a,b) = 0,3,6
  if(L <= a && a < L*2) { std::swap(a, c); std::swap(b, d); }
  if(a >= L) { a = LL - a; c = LL - c; }
  if(L <= b && b < L*2) {
    // (a,b) = 3; (c,d)!=5
    if(d >= L) { d = p3[l]-1 - d; b = p3[l]-1 - b; }
    // (c,d) = 0,1,2
    if(c >= L) return iabs(a-c)+iabs(b-d); // 3-2, 3-1
    // 3-0 thru
  }
  if(L <= b && b < L*2) { std::swap(a, b); std::swap(c, d); }
  if(b >= L*2) { b = LL - b; d = LL - d; }
  // (a,b)=0
  if(c < d) { std::swap(a, b); std::swap(c, d); }
  // (c,d)=0,1,2,5,8
  if(d >= L) return iabs(a-c)+iabs(b-d); // 0-5, 0-8
  if(c < L) return calc(a, b, c, d, l-1); // 0-0
  // 0-1,2
  int64_t Ls = p3[l-2];
  if(iabs(b-d) >= Ls) return iabs(a-c)+iabs(b-d);
  if(b >= 2*Ls) { b = L-1-b; d = L-1-d; }
  if(b < Ls) {
    int64_t aa = a%Ls, cc = c%Ls+Ls;
    return (c - cc) - (a - aa) + calc(aa, b, cc, d, l-1); 
  }
  if(a > Ls && c < L+Ls) return calc(a - Ls, b - Ls, c - Ls, d - Ls, l-1);
  int64_t r1 = iabs(Ls-1-b) + iabs(Ls-1-d);
  int64_t r2 = iabs(Ls*2-b) + iabs(Ls*2-d);
  return iabs(a-c) + std::min(r1, r2);
}

int main() {
  p3[0] = 1;
  for(int i = 1; i < 30; ++i) p3[i] = p3[i-1]*3;
  int Q; std::cin >> Q;
  for(int i = 0; i < Q; ++i) {
    int64_t a, b, c, d; std::cin >> a >> b >> c >> d;
    std::cout << calc(a-1, b-1, c-1, d-1, 30) << std::endl;
  }
  return 0;
}

