auto ce = [](auto a, auto b) { assert(b != 0); return a / b + (a % b != 0 && ((a >= 0) == (b >= 0)) ? 1 : 0); };

int main() {
	IN(int, Q);

	auto diff = [](auto a, auto b) { return abs(a - b); };

	vector<LL> T(31);
	inc(i, 31) { T[i] = (i == 0 ? 1 : T[i - 1] * 3); }

	inc(q, Q) {
		IN(LL, ax, ay, AX, AY);
		ax--; ay--; AX--; AY--;
		if_not(ax <= AX) { swap(ax, AX); }
		if_not(ay <= AY) { swap(ay, AY); }

		LL ans = diff(ax, AX) + diff(ay, AY);
		dec(k, 30) {
			LL ox = (fl(ax - T[k], T[k + 1]) + 1) * T[k + 1] + T[k];
			LL oy = (fl(ay - T[k], T[k + 1]) + 1) * T[k + 1] + T[k];

			LL px = ox - T[k + 1];
			LL py = oy;
			LL PX = px + T[k] - 1;
			LL PY = py + T[k] - 1;

			LL qx = ox;
			LL qy = oy - T[k + 1];
