long long work(long long x1, long long y1, long long x2, long long y2, int bz){
	if(bz == 0)
        return abs(y1 - y2);
	long long Tempbz = BZ[bz - 1];
	if(x1 / Tempbz != x2 / Tempbz)
        return abs(x1 - x2) + abs(y1 - y2);
	if(x1 / Tempbz == 1 && y1 / Tempbz != y2 / Tempbz)
		return abs(y1 - y2) + min(x1 % Tempbz + x2 % Tempbz + 2, (Tempbz - (x1 % Tempbz)) + (Tempbz - (x2 % Tempbz)));
	return work(x1 % Tempbz, y1, x2 % Tempbz, y2, bz - 1);
}
