const int K = 32;
ll bs[K+1];

ll acost(int k, ll a, ll b) {
        if (k<0) return 0;
//      cout<<"acost "<<k<<' '<<a<<' '<<b<<'\n';
        ll s = bs[k];
        if (a<s || b<s || a>=2*s || b>=2*s) {
                if (a<s && b<s) return acost(k-1, a, b);
                if (a>=2*s && b>=2*s) return acost(k-1, a-2*s, b-2*s);
                return llabs(b-a);
        }
//      cout<<"bad\n";
        a -= s;
        b -= s;
        return min(a+b+2, s-a + s-b);
}

ll solve(int k, ll a, ll b, ll c, ll d) {
        if (k<0) return 0;
//      cout<<"solve "<<k<<' '<<a<<' '<<b<<' '<<c<<' '<<d<<'\n';
        ll s = bs[k];
        ll aa=a/s, bb=b/s, cc=c/s, dd=d/s;
        if (aa==cc && bb==dd) return solve(k-1, a%s,b%s,c%s,d%s);
        if (abs(aa-cc)+abs(bb-dd) == 1) {
//              cout<<"asd "<<k<<' '<<a<<' '<<b<<' '<<c<<' '<<d<<'\n';
                if (aa==cc) {
                        if (b>d) swap(a,c), swap(b,d), swap(bb,dd);
                        if (s-b%s < d%s+1) return solve(k-1, a%s, 0, c%s, d%s) + s-b%s;
                        return solve(k-1, a%s, b%s, c%s, s-1) + d%s+1;
                } else {
                        if (c>a) swap(b,c), swap(a,c), swap(aa,cc);
                        if (s-a%s < c%s+1) return solve(k-1, 0, b%s, c%s, d%s) + s-a%s;
                        return solve(k-1, a%s, b%s, s-1, d%s) + c%s+1;
                }
        }
//      cout<<"zxc "<<aa<<' '<<bb<<' '<<cc<<' '<<dd<<'\n';
        if (aa!=cc && bb!=dd) return llabs(c-a) + llabs(d-b);
        if (aa==cc) return llabs(d-b) + acost(k, a, c);
        return llabs(c-a) + acost(k, b, d);
}

