pair<int, int> calc(int n) {
  if (n == -1) return make_pair(n, 0);
  if (h1[n] == 1 && h2[n] == 1 && w1[n] != w2[n]) return make_pair(n, 0);
  if (w1[n] == 1 && w2[n] == 1 && h1[n] != h2[n]) return make_pair(n, 1);
  else return calc(n - 1);
