using namespace std;
const int bs = 30;
vector<pair<long long, long long> > get_candidate(long long x, long long y) {
	vector<pair<long long, long long> > gs;
	gs.push_back(make_pair(x, y));
	long long mul = 1;
	for (int i = 0; i < bs; ++i) {
		x /= 3; y /= 3;
		mul *= 3;
		for (long long j = mul / 3 - 1; j <= 2 * mul / 3; j += mul / 3 + 1) {
			for (long long k = mul / 3 - 1; k <= 2 * mul / 3; k += mul / 3 + 1) {
				gs.push_back(make_pair(x * mul + j, y * mul + k));
			}
		}
	}
	return gs;
}
bool check(long long x, long long l, long long r) {
	int pos = -1;
	for (int i = 0; i < bs; ++i) {
		if (x % 3 == 1) {
			pos = i;
			break;
		}
		x /= 3;
		l /= 3;
		r /= 3;
	}
	if (pos == -1) return true;
	l += 2, r += 2;
	return l / 3 == r / 3;
}
long long calc(long long A, long long B, long long C, long long D) {
	vector<pair<long long, long long> > sl = get_candidate(A, B);
	vector<pair<long long, long long> > sr = get_candidate(C, D);
	vector<pair<long long, long long> > ss;
	ss.insert(ss.end(), sl.begin(), sl.end());
	ss.insert(ss.end(), sr.begin(), sr.end());
	sort(ss.begin(), ss.end());
	ss.erase(unique(ss.begin(), ss.end()), ss.end());
	int S = ss.size();
	vector<long long> X(S), Y(S);
	for (int i = 0; i < S; ++i) {
		X[i] = ss[i].first;
		Y[i] = ss[i].second;
	}
	vector<int> yperm(S);
	for (int i = 0; i < S; ++i) {
		yperm[i] = i;
	}
	sort(yperm.begin(), yperm.end(), [&](int i, int j) { return Y[i] != Y[j] ? Y[i] < Y[j] : X[i] < X[j]; });
	vector<vector<pair<int, long long> > > G(S);
	for (int i = 1; i < S; ++i) {
		if (X[i] == X[i - 1] && check(X[i], Y[i - 1], Y[i])) {
			G[i].push_back(make_pair(i - 1, Y[i] - Y[i - 1]));
			G[i - 1].push_back(make_pair(i, Y[i] - Y[i - 1]));
		}
		if (Y[yperm[i - 1]] == Y[yperm[i]] && check(Y[yperm[i]], X[yperm[i - 1]], X[yperm[i]])) {
			long long dist = X[yperm[i]] - X[yperm[i - 1]];
			G[yperm[i]].push_back(make_pair(yperm[i - 1], dist));
			G[yperm[i - 1]].push_back(make_pair(yperm[i], dist));
		}
	}
	int start = lower_bound(ss.begin(), ss.end(), make_pair(A, B)) - ss.begin();
	int goal = lower_bound(ss.begin(), ss.end(), make_pair(C, D)) - ss.begin();
	vector<bool> vis(S, false);
	priority_queue<pair<long long, int> > que;
	que.push(make_pair(0, start));
	vector<long long> dist(S, 1LL << 61);
	dist[start] = 0;
	while (!que.empty()) {
		int u = que.top().second; que.pop();
		if (vis[u]) continue;
		vis[u] = true;
		if (u == goal) return dist[u];
		for (pair<int, long long> e : G[u]) {
			if (dist[e.first] > dist[u] + e.second) {
				dist[e.first] = dist[u] + e.second;
				que.push(make_pair(-dist[e.first], e.first));
			}
		}
	}
	return -1;
}
