unsigned long long pow3[31];

unsigned long long dist(a, b, c, d, n)
{
    int a1, b1, c1, d1;
    int u, v;

    a1 = a / pow3[n - 1];
    b1 = b / pow3[n - 1];
    c1 = c / pow3[n - 1];
    d1 = d / pow3[n - 1];

    if (a1 == c1 && b1 == d1)
    {
        return dist(a - a1 * pow3[n - 1], b - b1 * pow3[n - 1], c - c1 * pow3[n - 1], d - d1 * pow3[n - 1], n - 1);
    }
    else if (a1 == c1 && a1 == 1)
    {
        u = a - pow3[n - 1] + b - pow3[n - 1];
        v = 2 * pow3[n - 1] - a + 2 * pow3[n - 1] - b;
        return abs(d - b) + (u > v ? v : u);
    }
    else if (b1 == d1 && b1 == 1)
    {
        u = b - pow3[n - 1] + d - pow3[n - 1];
        v = 2 * pow3[n - 1] - b + 2 * pow3[n - 1] - d;
        return abs(a - c) + (u > v ? v : u);
    }
    else
    {
        return abs(a - c) + abs(d - b);
    }
    return 0;
}

