ll p3[50];
ll f(ll a,ll b,ll c,ll d,int k){
	ll aa=a/p3[k];
	ll bb=b/p3[k];
	ll cc=c/p3[k];
	ll dd=d/p3[k];
//	printf("%lld %lld %lld %lld %d\n",aa,bb,cc,dd,k);
	ll ans=llabs(a-c)+llabs(b-d);
	if(aa==cc&&aa%3==1){
		//はい
		ans+=min(
			min(llabs(aa*p3[k]-1-a),llabs((aa+1)*p3[k]-a)),
			min(llabs(aa*p3[k]-1-c),llabs((aa+1)*p3[k]-c))
		)*2;
		return ans;
	}else if(bb==dd&&bb%3==1){
		//はい2
		ans+=min(
			min(llabs(bb*p3[k]-1-b),llabs((bb+1)*p3[k]-b)),
			min(llabs(bb*p3[k]-1-d),llabs((bb+1)*p3[k]-d))
		)*2;
		return ans;
	}
	if(k==0)return ans;
	return f(a,b,c,d,k-1);
}

