    f3[0] = 1;
    for (int i = 0; i < 30; i++) {
      f3[i + 1] = f3[i] * 3;
    }


    for (int i = 0; i < q; i++) {
      long a = nl() - 1;
      long b = nl() - 1;
      long c = nl() - 1;
      long d = nl() - 1;

      long y = f(a) & f(c);
      long x = f(b) & f(d);

      long ret = Math.abs(a - c) + Math.abs(b - d);

      for (int j = 30; j >= 1; j--) {
        if (((y >> j) & 1) == 1 && Math.abs(b - d) > f3[j]) {
          ret += Math.min(Math.abs(f3[j] - 1 - a), Math.abs(f3[j] * 2 - a)) * 2;
          break;
        }
      }

      for (int j = 30; j >= 1; j--) {
