            var x2 = abcd[3] - 1;
            var y = Abs(y1 - y2);
            var x = Abs(x1 - x2);
            if (y < x)
            {
                var tmp1 = x1;
                x1 = y1;
                y1 = tmp1;
                var tmp2 = x2;
                x2 = y2;
