                if (x1 / size != x2 / size || (x1 / size) % 3 != 1) continue;
                maxSize = size;
            }
            if (maxSize == 0)
            {
                Console.WriteLine(y + x);
                continue;
            }
            var edgeA = (x1 / maxSize) * maxSize;
            var edgeB = (x1 / maxSize + 1) * maxSize;
