class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    long solve(long a, long b, long c, long d, long p) {
        if (p == 0) {
            return Math.Abs(a - c) + Math.Abs(b - d);
        }
        long aa = a / p, bb = b / p, cc = c / p, dd = d / p;
        if (aa == cc && bb == dd) {
            return solve(a, b, c, d, p / 3);
        }
        else if (aa != cc && bb != dd) {
            return Math.Abs(a - c) + Math.Abs(b - d);
        }
        else if (aa == cc) {
            if (aa % 3 == 1 && Math.Abs(bb - dd) > 1) {
                return Math.Abs(b - d) + Math.Min(a % p + 1 + c % p + 1,  p - a % p + p - c % p);
            }
            else {
                return solve(a, b, c, d, p / 3);
            }
        }
        else {
            if (bb % 3 == 1 && Math.Abs(aa - cc) > 1) {
                return Math.Abs(a - c) + Math.Min(b % p + 1 + d % p + 1,  p - b % p + p - d % p);
            }
            else {
                return solve(a, b, c, d, p / 3);
            }
        }
    }
    bool[][] board;
    int[][][][] dist;
    bool[][] frac(int k) {
        if (k == 0) {
            var res = new bool[1][];
            res[0] = new bool[1];
            res[0][0] = true;
            return res;
        }
        else {
            var a = frac(k - 1);
            var res = new bool[a.Length * 3][];
            for (int i = 0; i < a.Length * 3; i++)
            {
                res[i] = new bool[a.Length * 3];
                for (int j = 0; j < a.Length * 3; j++)
                {
                    if (a.Length <= i && i < a.Length * 2 && a.Length <= j && j < a.Length * 2) {
                        res[i][j] = false;
                    }
                    else {
                        res[i][j] = a[i % a.Length][j % a.Length];
                    }
                }
            }
            return res;
        }
    }
    void naive(int lev) {
        board = frac(lev);
        int n = board.Length;
        dist = new int[n][][][];
        for (int i = 0; i < n; i++)
        {
            dist[i] = new int[n][][];
            for (int j = 0; j < n; j++)
            {
                dist[i][j] = new int[n][];
                for (int k = 0; k < n; k++)
                {
                    dist[i][j][k] = new int[n];
                    for (int l = 0; l < n; l++)
                    {
                        dist[i][j][k][l] = M;
                    }
                }
                var q = new Queue<P>();
                q.Enqueue(new P(i, j));
                dist[i][j][i][j] = 0;
                while (q.Any()) {
                    var p = q.Dequeue();
                    foreach (var item in p.adjacents(n, n))
                    {
                        if (board[item.v1][item.v2] && dist[i][j][item.v1][item.v2] == M) {
                            dist[i][j][item.v1][item.v2] = dist[i][j][p.v1][p.v2] + 1;
                            q.Enqueue(item);
                        }
                    }
                }
            }
        }
    }


