        //                     Prt(solve(a, b, c, d, p), dist[a][b][c][d]);
        //                 }
        //             }
        //         }
        //     }
        // }
        for (int _ = 0; _ < T; _++)
        {
            long a, b, c, d;
            sc.Multi(out a, out b, out c, out d);
