    public object Calc()
    {
        var N = cr.Int;

        pows[0] = 1;
        for (int i = 1; i < pows.Length; i++)
            pows[i] = pows[i - 1] * 3;

        var res = new long[N];
        for (int i = 0; i < N; i++)
        {
            var a = cr.Long - 1; var b = cr.Long - 1;
            var c = cr.Long - 1; var d = cr.Long - 1;
            res[i] = CalcImpl(a, b, c, d, 29);
        }
        return AllLines(res);
    }

    long[] pows = new long[31];

    long CalcImpl(long a, long b, long c, long d, int size)
    {
        long res = 0;
        var po = pows[size];//3^29
        while (a / po == c / po && b / po == d / po)
        {
            size--;
            po /= 3;
        }
        while (true)
        {
            var pp = po * 3;
            var ps = po / 3;


            if (a / po != c / po && b / po != d / po)
                return res + Math.Abs(a - c) + Math.Abs(b - d);

            if (a / po == c / po)
            {
                long tmp;
                tmp = a;
                a = b;
                b = tmp;

                tmp = c;
                c = d;
                d = tmp;

                if (a > c)
                {
                    tmp = c;
                    c = a;
                    a = tmp;
                }
            }
            else if (a > c)
            {
                long tmp;

                tmp = c;
                c = a;
                a = tmp;

                tmp = d;
                d = b;
                b = tmp;
            }

            a %= pp; b %= pp; c %= pp; d %= pp;
            if (size == 0)
            {
                if (b / po == 1)
                    return res + 4;
                else
                    return res + c - a;
            }

            if (b / po == 1)
                return res + Math.Min(b - (po - 1) + d - (po - 1), 2 * po - b + 2 * po - d) + Math.Abs(a - c);

            if (c - 1 == a)
                return res + Math.Abs(c - a) + Math.Abs(b - d);

            if ((b % po) / ps != (d % po) / ps)
                return res + Math.Abs(a - c) + Math.Abs(b - d);

            if ((a % po) / ps == 0)
            {
                res += 1 + c % po + (c / po - a / po - 1) * po;
                size--;
                a %= po;
                c = po - 1;
                po /= 3;
            }
            else if ((c % po) / ps == 2)
            {
                res += (po - a % po) + (c / po - a / po - 1) * po;
                size--;
                a = 0;
                c %= po;
                po /= 3;
            }
            else if (c / po - a / po == 2)
            {
                res += (po - a % po) + 1 + c % po;
                size--;
                a = 0;
                c = 3 * po - 1;
                po /= 3;
            }
            else
            {
                c = c % ps + (c - (a / ps * ps)) / ps * ps;
                a %= ps; b %= ps; d %= ps;
                return res + CalcImpl(a, b, c, d, size);
            }
        }
    }
}

