        else if (aa == cc) {
            if (aa % 3 == 1) {
                return Math.Abs(b - d) + Math.Min(a % p + 1 + c % p + 1,  p - a % p + p - c % p);
            }
            else {
                return solve(a, b, c, d, p / 3);
            }
        }
        else {
            if (bb % 3 == 1) {
                return Math.Abs(a - c) + Math.Min(b % p + 1 + d % p + 1,  p - b % p + p - d % p);
            }
            else {
                return solve(a, b, c, d, p / 3);
            }
        }
    }

    public void solve() {
        int T = sc.Int;
        long p = 1;
        for (int i = 0; i < 30; i++)
        {
            p *= 3;
        }
        for (int _ = 0; _ < T; _++)
        {
            long a, b, c, d;
            sc.Multi(out a, out b, out c, out d);
            --a;
            --b;
            --c;
            --d;
            Prt(solve(a, b, c, d, p));
        }
    }
}

