        {
            var pp = po * 3;
            var ps = po / 3;

            // ブロックが斜めに違うならまっすぐ行ける
            if (a / po != c / po && b / po != d / po)
                return Math.Abs(a - c) + Math.Abs(b - d);

            // 縦横のブロックが同じだと困る
            // とりあえず横のブロックが同じのときは縦が同じになるように入れ替える
            if (a / po == c / po)
            {
                Swap(ref a, ref b);
                Swap(ref c, ref d);
            }

            // aの方が小さくなるようにする
            if (a > c)
            {
                Swap(ref a, ref c);
                Swap(ref b, ref d);
            }

            a %= pp; b %= pp; c %= pp; d %= pp;
            if (size == 0)
            {
                if (b / po == 1)
                    return 4;
                else
                    return c - a;
            }
            if (b / po == 1)
                return Math.Min(b - (po - 1) + d - (po - 1), 2 * po - b + 2 * po - d) + Math.Abs(a - c);

            if (c - 1 == a)
                return Math.Abs(c - a) + Math.Abs(b - d);

            if ((b % po) / ps != (d % po) / ps)
                return Math.Abs(a - c) + Math.Abs(b - d);
            if ((a % po) / ps == 0)
                return 1 + c % po + (c / po - a / po - 1) * po + CalcImpl(a % po, b, po - 1, d, size - 1);
            else if ((c % po) / ps == 2)
                return (po - a % po) + (c / po - a / po - 1) * po + CalcImpl(0, b, c % po, d, size - 1);
            else if (c / po - a / po == 2)
                return (po - a % po) + 1 + c % po + CalcImpl(0, b, 3 * po - 1, d, size - 1);
            else
                return CalcImpl(a % ps, b % ps, c % ps + (c - (a / ps * ps)) / ps * ps, d % ps, size);
        }

    }
    static void Swap<T>(ref T a, ref T b)
    {
        T tmp;
        tmp = a;
        a = b;
        b = tmp;
    }
}

