internal partial class Solver {
    long[] three;
    public void Run() {
        three = new long[33];
        three[0] = 1;
        for (int i = 1; i < three.Length; i++) {
            three[i] = three[i - 1] * 3L;
        }

        var q = ni();
        for (int i = 0; i < q; i++) {
            var a = nl() - 1;
            var b = nl() - 1;
            var c = nl() - 1;
            var d = nl() - 1;
            cout.WriteLine(Solve(a, b, c, d));
        }
    }

    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }

    private long Solve(long a, long b, long c, long d) {
        long ans = Math.Abs(a - c) + Math.Abs(b - d);
        for (int k = 29; k >= 0; k--) {
            var ta = a / three[k];
            var tb = b / three[k];
            var tc = c / three[k];
            var td = d / three[k];
            if (ta == tc && tb == td) { // same
                a %= three[k];
                b %= three[k];
                c %= three[k];
                d %= three[k];
                continue;
            } else if (ta == tc || tb == td) {
                if (tb == td) {
                    Swap(ref ta, ref tb);
                    Swap(ref tc, ref td);
                    Swap(ref a, ref b);
                    Swap(ref c, ref d);
                }
                // ta == tc
                if (ta == 1 && tc == 1) {
                    var low = three[k] - 1;
                    var high = three[k] * 2;
                    var cost = long.MaxValue;
                    cost = Math.Min(cost, Math.Min(Math.Abs(a - low), Math.Abs(c - low)));
                    cost = Math.Min(cost, Math.Min(Math.Abs(a - high), Math.Abs(c - high)));
                    ans += cost * 2;
                    break;
                }
                a %= three[k];
                c %= three[k];
                if (k - 1 >= 0) {
                    var sa = a / three[k - 1];
                    var sb = b / three[k - 1];
                    var sc = c / three[k - 1];
                    var sd = d / three[k - 1];
                    if (sa != sc) {
                        break;
                    }
                    if (sb > sd) {
                        Swap(ref a, ref c); Swap(ref b, ref d);
                        Swap(ref sa, ref sc); Swap(ref sb, ref sd);
                    }
                    // sa == sc
                    // sb <= sd
                    var sdis = Math.Abs(sb - sd);

                    if (sa == 1 && sc == 1 && sdis >= 2) {
                        var low = three[k - 1] - 1;
                        var high = three[k - 1] * 2;
                        var cost = long.MaxValue;
                        cost = Math.Min(cost, Math.Min(Math.Abs(a - low), Math.Abs(c - low)));
                        cost = Math.Min(cost, Math.Min(Math.Abs(a - high), Math.Abs(c - high)));
                        ans += cost * 2;
                        break;
                    }
                    a %= three[k - 1];
                    c %= three[k - 1];
                    var offset = sb * three[k - 1];
                    b -= offset;
                    d -= offset;
                    while (sdis > 2) {
                        d -= three[k - 1];
                        sdis--;
                    }
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        return ans;
    }
}

