	}
}

type solution struct {
	debuggable
	sideLength uint64
}

func (sol *solution) solve(x1, y1, x2, y2 uint64) uint64 {
	sol.debug(func() {
		fmt.Printf("\nsolving %d %d %d %d\n", x1, y1, x2, y2)
	})
	return sol.abs(x1, x2) + sol.abs(y1, y2) + sol.max(sol.getExtra(x1, y1, x2, y2), sol.getExtra(y1, x1, y2, x2))
}

func (sol *solution) abs(m, n uint64) uint64 {
	if m < n {
		return n - m
	} else {
		return m - n
	}
}

func (spl *solution) max(m, n uint64) uint64 {
	if m < n {
		return n
	} else {
		return m
	}
}

func (spl *solution) min(m, n uint64) uint64 {
	if m < n {
		return m
	} else {
		return n
	}
}

func (sol *solution) getExtra(x1, y1, x2, y2 uint64) uint64 {
	s := sol.sideLength
	var blockX1, blockY1, blockX2, blockY2 uint64
	var left, right uint64
	var result uint64 = 0
	for {
		s /= 3
		if s == 0 {
			break
		}
		blockX1, blockX2 = x1/s, x2/s
		if blockX1 != blockX2 {
			break
		}
		if blockX1%3 != 1 {
			continue
		}
		blockY1, blockY2 = y1/s, y2/s
		if sol.abs(blockY1, blockY2) <= 1 {
			continue
		}
		left = s*blockX1 - 1
		right = s * (blockX1 + 1)
		result = 2 * sol.min(sol.min(x1, x2)-left, right-sol.max(x1, x2))
		sol.debug(func() {
			fmt.Printf("size %d: (%d, %d), (%d, %d); left %d, right %d, result %d\n", s, x1, y1, x2, y2, left, right, result)
		})
	}
	return result
}

