int[] f(long u){
	int[] res;
	while(u > 0){
		res ~= u % 3;
		u /= 3;
	}
	while(res.length < 30) res ~= 0;
	return res;
}

long q(long a, long b, long c, long d){
	static long[] pow3;
	if(! pow3.length){
		pow3 ~= 1;
		while(pow3.length < 30) pow3 ~= pow3[$ - 1] * 3;
	}

	int[] ax = f(a), bx = f(b), cx = f(c), dx = f(d);

	// b と d が下から見て初めて差異をもつ桁 k
	int k = 0;
	while(k < 30 && bx[k] == dx[k]) k ++;

	// a と c が上から見て数字が同じで最後に1だった桁 j
	int j = 29, j0 = 30;
	while(j >= 0 && ax[j] == cx[j]){
		if(ax[j] == 1){
			j0 = j;
			if(j <= k) break;
		}
		j --;
	}
	log("a:", a, "b:", b, "c:", c, "d:", d);
	log("ax:", ax);
	log("bx:", bx);
	log("cx:", cx);
	log("dx:", dx);
	log("k:", k, "j0:", j0);

	if(j0 >= k && j0 < 30){
		return min(
			2 + a % pow3[j0] + c % pow3[j0],
			(pow3[j0] - a % pow3[j0]) + (pow3[j0] - c % pow3[j0])
		);
	}
	else return abs(a - c);
}


/*
黒マスは三進法で見たときxとyが両方とも1である桁がある場合
（例：02112と10100は3桁目がともに1）

aとcを三進法で見て上から連続した共通部分の中に1があれば
それは黒マスのある行
それのbとdを比べて当該桁以上で差異があったらアウト
アウトというのは黒マスを迂回するということ
迂回する一番大きい黒マスの幅が3**kであるとすると

