long[] THREE;

long prevPassage(long a) {
  for (int k = 0; ; ++k) {
    if (a < THREE[k]) {
      return THREE[k] - 1 - nextPassage(THREE[k] - 1 - a);
    }
  }
}
long nextPassage(long a) {
  for (int k = 0; ; ++k) {
    if (a < THREE[k]) {
      foreach_reverse (i; 0 .. k) {
        if (a / THREE[i] % 3 == 1) {
          return (a / THREE[i] + 1) * THREE[i];
        }
      }
      return a;
    }
  }
}

long solve(int k, long a, long b, long c, long d) {
  long ret;
  if (k == 0) {
    ret = 0;
  } else {
    const r = THREE[k - 1];
    const s = (a / r) * 3 + (b / r);
    const t = (c / r) * 3 + (d / r);
    /*
      012
      345
      678
    */
    if (s == t) {
      ret = solve(k - 1, a % r, b % r, c % r, d % r);
    } else if (s / 3 == t / 3) {
      const x0 = prevPassage(a), x1 = nextPassage(a);
      ret = abs(b - d) + min(abs(a - x0) + abs(c - x0), abs(a - x1) + abs(c - x1));
    } else if (s % 3 == t % 3) {
      const y0 = prevPassage(b), y1 = nextPassage(b);
      ret = abs(a - c) + min(abs(b - y0) + abs(d - y0), abs(b - y1) + abs(d - y1));
    } else {
      ret = abs(a - c) + abs(b - d);
    }
  }
  return ret;
}

