            # x1 と x2 の間に 1, 4, 7, ... があればそれ
            if x2 - x1 >= 2:
                while x1 % 3 != 1:
                    x1 += 1
                return x1 * size, y1 * size, size
        if x1 == x2 and x1 % 3 == x2 % 3 == 1:
            if y2 - y1 >= 2:
                while y1 % 3 != 1:
                    y1 += 1
                return x1 * size, y1 * size, size
        size //= 3
    return None


