def between(x, y1, y2):
    if x % 3 != 1:return False
    if y1 > y2:
        y1,y2= y2,y1
    for i in range(1,4):
        if y1 + i >= y2:break
        if (y1 + i) % 3 == 1:
            return True
    return False

