def man(a, b, c, d):
    return abs(a - c) + abs(b - d)

def solve(a, b, c, d, i, carry):
    if (a, b) == (c, d):
        return carry
    if i == 29:
        if (a, c) == (1, 1) or (b, d) == (1, 1):
            return 4 + carry
        else:
            return man(a,b,c,d) + carry
    k = 3 ** (30 - 1 - i)
    ga = a // k
    gb = b // k
    gc = c // k
    gd = d // k
    if (ga, gb) == (gc, gd):
        a %= k
        b %= k
        c %= k
        d %= k
        return solve(a,b,c,d,i+1,carry)
    if ga != gc and gb != gd:
        return man(a,b,c,d) + carry
    if gb == gd:
        a,b,c,d = b,a,d,c
        ga = a // k
        gb = b // k
        gc = c // k
        gd = d // k
    if ga == 1:
        return 2 * min(min(a, c) - k + 1, 2 * k - max(a, c)) + man(a,b,c,d) + carry
    if b > d:
        a,b,c,d = c,d,a,b
        ga = a // k
        gb = b // k
        gc = c // k
        gd = d // k
    # ga == gc != 1 and gb < gd
    kk = k // 3
    gga = (a % k) // kk
    ggb = b // kk
    ggc = (c % k) // kk
    ggd = d // kk
    if (gga, ggc) == (1, 1):
        if ggd - ggb == 1:
            return solve(a % kk, b % kk, c % kk, d % kk + kk, i+1, carry)
        else:
            a %= k
            c %= k
            return carry + d - b + min(a + c - 2*(kk-1), 4*k - a - c)
    else:
        a %= k
        c %= k
        nb = b % kk
        nd = d % kk
        carry += (d - b) - (nd - nb)
        return solve(a,nb,c,nd,i+1,carry)

