fn calc(a: i64, b: i64, c: i64, d: i64, x: i64) -> i64 {
    if x == 0 {
        return (a - c).abs() + (b - d).abs();
    }
    if a / x != c / x && b / x != d / x {
        return (a - c).abs() + (b - d).abs();
    }
    if a / x == c / x && b / x == d / x {
        return calc(a % x, b % x, c % x, d % x, x / 3);
    }
    if b / x != d / x {
        return calc(b, a, d, c, x);
    }
    assert_ne!(a / x, c / x);
    assert_eq!(b / x, d / x);
    let (a, b, c, d) = if a < c {
        (a, b, c, d)
    } else {
        (c, d, a, b)
    };
    if b / x == 1 {
        if c / x - a / x >= 2 || c - a >= 2 * x {
            let t = min((b - x + 1) + (d - x + 1),
                        (2 * x - b) + (2 * x - d));
            return c - a + t;
        }
    }
    calc(a, b % x, c, d % x, x / 3)
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        abcd: [(i64, i64, i64, i64)],
    }
    let mut p30: i64 = 1;
    for _ in 0..30 { p30 *= 3; }
    for &(a, b, c, d) in &abcd {
        let a = a - 1;
        let b = b - 1;
        let c = c - 1;
        let d = d - 1;
        puts!("{}\n", calc(a, b, c, d, p30 / 3));
    }
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

