// Input macro from https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
  (source = $s:expr, $($r:tt)*) => {
    let mut iter = $s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
  ($($r:tt)*) => {
    let s = {
      use std::io::Read;
      let mut s = String::new();
      std::io::stdin().read_to_string(&mut s).unwrap();
      s
    };
    let mut iter = s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
}

macro_rules! input_inner {
  ($iter:expr) => {};
  ($iter:expr, ) => {};

  ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
    let $var = read_value!($iter, $t);
    input_inner!{$iter $($r)*}
  };
}

macro_rules! read_value {
  ($iter:expr, ( $($t:tt),* )) => {
    ( $(read_value!($iter, $t)),* )
  };

  ($iter:expr, [ $t:tt ; $len:expr ]) => {
    (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  };

  ($iter:expr, chars) => {
    read_value!($iter, String).chars().collect::<Vec<char>>()
  };

  ($iter:expr, usize1) => {
    read_value!($iter, usize) - 1
  };

  ($iter:expr, [ $t:tt ]) => {{
    let len = read_value!($iter, usize);
    (0..len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  }};

  ($iter:expr, $t:ty) => {
    $iter.next().unwrap().parse::<$t>().expect("Parse error")
  };
}

fn block(bsize: i64, x: (i64, i64)) -> (i64, i64) {
  (x.0 / bsize, x.1 / bsize)
}

fn dist_next(lev: u32, x: (i64, i64), y: (i64, i64)) -> i64 {
  if lev == 0 {
    (x.0 - y.0).abs() + (x.1 - y.1).abs()
  } else {
    dist_lev(lev - 1, x, y)
  }
}

fn dist_lev(lev: u32, x: (i64, i64), y: (i64, i64)) -> i64 {
  let bsize = 3_i64.pow(lev);
  let bx = block(bsize, x);
  let by = block(bsize, y);
  // dbg!((bsize, bx, by));
  match (bx.0 == by.0, bx.1 == by.1) {
    (true, true) => dist_next(lev, x, y),
    (false, false) => (x.0 - y.0).abs() + (x.1 - y.1).abs(),
    (false, true) => {
      if bx.1 % 3 == 1 {
        let remx = x.1 % bsize;
        let remy = y.1 % bsize;
        (x.0 - y.0).abs() + cmp::min(remx + remy + 2, bsize - remx + bsize - remy)
      } else {
        dist_next(lev, x, y)
      }
    },
    (true, false) => {
      if bx.0 % 3 == 1 {
        let remx = x.0 % bsize;
        let remy = y.0 % bsize;
        (x.1 - y.1).abs() + cmp::min(remx + remy + 2, bsize - remx + bsize - remy)
      } else {
        dist_next(lev, x, y)
      }
    }
  }
}

fn main() {
  let out = std::io::stdout();
  let mut out = std::io::BufWriter::new(out.lock());
  macro_rules! puts {
    ($($format:tt)*) => (write!(out,$($format)*).unwrap());
  }
  input! {
    q: usize,
    qs: [(i64, i64, i64, i64); q],
  }
  for &(a, b, c, d) in &qs {
    puts!("{}\n", dist_lev(31, (a-1, b-1), (c-1, d-1)));
  }
}

