fn main() {
    let q = read::<usize>();
    let mut queries = vec![];

    for i in 0..q {
        let v = read_vec::<i64>();
        let (a, b, c, d) = (v[0], v[1], v[2], v[3]);
        queries.push((a, b, c, d));
    }
    for (mut a, mut b, mut c, mut d) in queries {
        let mut crossed = 0;
        let mut max_axis = 0;
        for &(a, b, c, d, axis) in &[(a, b, c, d, 0), (c, d, a, b, 1)] {
            let mut a_clone = a;
            let mut b_clone = b;
            let mut c_clone = c;
            let mut d_clone = d;

            for level in 1..31 {
                if (d_clone - c_clone).abs() <= 2 {
                    break;
                }
                if a_clone % 3 == 1 && b_clone % 3 == 1 && (a_clone - b_clone).abs() < 3 {
                    if level > crossed {
                        crossed = max(crossed, level);
                        max_axis = axis;
                    }
                }
                a_clone /= 3;
                b_clone /= 3;
                c_clone /= 3;
                d_clone /= 3;
            }
        }
        let mut ans = (a - b).abs() + (c - d).abs();
        if crossed != 0 {
            if max_axis == 1 {
                std::mem::swap(&mut a, &mut c);
                std::mem::swap(&mut c, &mut d);
            }
            ans += min(
                a % 3i64.pow(crossed - 1) + b % 3i64.pow(crossed - 1),
                3i64.pow(crossed - 1) - a % 3i64.pow(crossed - 1) + 3i64.pow(crossed - 1)
                    - b % 3i64.pow(crossed - 1),
            );
        }
        println!("{}", ans);
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

