fn abs(x: usize, y: usize) -> usize {
    max(x, y) - min(x, y)
}
fn rec(a: usize, b: usize, c: usize, d: usize) -> usize {
    let (x1, y1, x2, y2) = if b < d { (a, b, c, d) } else { (c, d, a, b) };
    for i in (0..30).rev() {
        let p = 3usize.pow(i);
        let (i1, j1, i2, j2) = (x1 / p, y1 / p, x2 / p, y2 / p);
        if i1 != i2 {
            break;
        }
        if i1 % 3 == 1 && abs(j2, j1) > 1 {
            return min(min(x1, x2) + 1 - p * i1, p * (i1 + 1) - max(x1, x2)) * 2;
        }
    }
    0
}
fn solve(a: usize, b: usize, c: usize, d: usize) -> usize {
    let best = abs(a, c) + abs(b, d);
    best + max(rec(a, b, c, d), rec(b, a, d, c))
}
use std::cmp::{max, min};
fn main() {
    input! { iter = iter, q };
    for _ in 0..q {
        input_inner! { iter, a: usize1, b: usize1, c: usize1, d: usize1 };
        println!("{}", solve(a, b, c, d));
    }
}

