fn block(bsize: i64, x: (i64, i64)) -> (i64, i64) {
  (x.0 / bsize, x.1 / bsize)
}

fn dist_lev(lev: u32, x: (i64, i64), y: (i64, i64)) -> i64 {
  let bsize = 3_i64.pow(lev);
  let bx = block(bsize, x);
  let by = block(bsize, y);
  // dbg!((bsize, bx, by));
  if (bx.0, by.0) == (1, 1) && bx.1 != by.1 {
    let remx = x.0 % bsize;
    let remy = y.0 % bsize;
    return (x.1 - y.1).abs() + cmp::min(remx + remy + 2, bsize - remx + bsize - remy);
  } else if (bx.1, by.1) == (1, 1) && bx.0 != by.0 {
    let remx = x.1 % bsize;
    let remy = y.1 % bsize;
    return (x.0 - y.0).abs() + cmp::min(remx + remy + 2, bsize - remx + bsize - remy);
  }
  if lev == 0 {
    return (x.0 - y.0).abs() + (x.1 - y.1).abs();
  }
  dist_lev(lev - 1, x, y)
}

