fn rec(a: usize, b: usize, c: usize, d: usize, p: usize) -> usize {
    // println!("{} {} {} {} {}", a, b, c, d, p);
    let (x1, y1, x2, y2) = (a / p, b / p, c / p, d / p);
    let (a, b, c, d) = (a % p, b % p, c % p, d % p);
    if x1 == x2 && x1 == 1 {
        if b < d {
            if d - b < p || d - b < 2 * p && y2 == 0 && y1 == 2 {
                return rec(a, b, c, d, p / 3);
            }
        } else if d < b {
            if b - d < p || b - d < 2 * p && y1 == 0 && y2 == 2 {
                return rec(a, b, c, d, p / 3);
            }
        }
        return min(min(p - a, a + 1), min(p - c, c + 1)) * 2;
    }
    0
}
fn solve(a: usize, b: usize, c: usize, d: usize, p: usize) -> usize {
    // println!("{} {} {} {} {}", a, b, c, d, p);
    let (x1, y1, x2, y2) = (a / p, b / p, c / p, d / p);
    if x1 == x2 && y1 == y2 {
        return solve(a % p, b % p, c % p, d % p, p / 3);
    }
    let best = max(a, b) - min(a, b) + max(c, d) - min(c, d);
    let (a, b, c, d) = (a % p, b % p, c % p, d % p);
    if x1 == x2 {
        if x1 == 1 {
            return best + min(min(p - b, b + 1), min(p - d, d + 1)) * 2;
        }
        return best + rec(a, b, c, d, p / 3);
    }
    if y1 == y2 {
        if y1 == 1 {
            return best + min(min(p - a, a + 1), min(p - c, c + 1)) * 2;
        }
        return best + rec(b, a, d, c, p / 3);
    }
    best
}
